const ESP = {
  getFreeHeap: () => 200000, getHeapSize: () => 300000, getFreePsram: () => 7000000, getPsramSize: () => 8388608,
  getMinFreeHeap: () => 150000, restart: () => {}, getCpuFreqMHz: () => 240,
};

// ---- FreeRTOS ----
// The phone runs one task besides loop(): audioTask (the speaker and the
// microphone). The board steps it (see RUNTIME 5), the desk phone never starts it.
let deskTasks = 0;
function xTaskCreatePinnedToCore(fn) { deskTasks++; BOARD.taskStarted(fn); return 1; }
function xTaskCreate(fn) { return xTaskCreatePinnedToCore(fn); }
function vTaskDelay(ticks) { BOARD.taskDelay(ticks); }
function vTaskDelete() {}
function xTaskGetTickCount() { return millis(); }
function esp_err_to_name() { return S('ESP_FAIL'); }

// ============================================================================
// RUNTIME 4/6 - files: LittleFS (the phone's flash) and SD (the card)
// ============================================================================
// The same file system as the desk phone's (desk_support.cpp): paths, folders,
// open/read/write/seek, listing. In the emulator the flash is kept in the
// emulator's storage (it survives a reload, like the real flash survives a
// power cut); the card lives in memory and starts empty each time.
const FILE_READ = S('r'), FILE_WRITE = S('w'), FILE_APPEND = S('a');
const CARD_NONE = 0, CARD_MMC = 1, CARD_SD = 2, CARD_SDHC = 3, CARD_UNKNOWN = 4;

function normPath(p) {
  let s = typeof p === 'string' ? p : jstr(p);
  if (s === '' || s[0] !== '/') s = '/' + s;
  while (s.length > 1 && s[s.length - 1] === '/') s = s.slice(0, -1);
  return s;
}
function parentOf(p) { const k = p.lastIndexOf('/'); return k === 0 ? '/' : p.slice(0, k); }

class Disk {
  constructor(name, total) {
    this.name = name;
    this.files = new Map();       // path -> Uint8Array (its length is the file's size)
    this.dirs = [];
    this.present = true; this.mounted = false;
    this.total = total;
    this.onChange = null;         // the emulator saves the flash after changes
  }
  isDir(p) { return p === '/' || this.dirs.includes(p); }
  begin() { this.mounted = this.present; return this.mounted; }
  end() { this.mounted = false; }
  open(path, mode, create) {
    const f = new File();
    if (!this.mounted) return f;
    const p = normPath(path);
    const m = mode == null ? 'r' : (typeof mode === 'string' ? mode : jstr(mode));
    const w = m[0] === 'w' || m[0] === 'a';
    if (this.isDir(p) && !w) {
      f.disk = this; f.p = p; f.dir = true;
      const pre = p === '/' ? '/' : p + '/';
      const names = [];
      for (const d of this.dirs) if (d.length > pre.length && d.startsWith(pre) && d.indexOf('/', pre.length) < 0) names.push(d);
      for (const k of [...this.files.keys()].sort()) if (k.length > pre.length && k.startsWith(pre) && k.indexOf('/', pre.length) < 0) names.push(k);
      f.kids = names;
      return f;
    }
    if (!w && !this.files.has(p)) return f;
    if (w && !this.isDir(parentOf(p))) return f;
    f.disk = this; f.p = p; f.wr = w;
    if (m[0] === 'w') { this.files.set(p, new Uint8Array(0)); this.changed(); }
    else if (m[0] === 'a') { if (!this.files.has(p)) this.files.set(p, new Uint8Array(0)); f.pos = this.files.get(p).length; }
    return f;
  }
  exists(path) { if (!this.mounted) return false; const p = normPath(path); return this.files.has(p) || this.isDir(p); }
  remove(path) { if (!this.mounted) return false; const ok = this.files.delete(normPath(path)); if (ok) this.changed(); return ok; }
  rename(a, b) {
    if (!this.mounted) return false;
    const pa = normPath(a), pb = normPath(b);
    if (!this.files.has(pa)) return false;
    this.files.set(pb, this.files.get(pa)); this.files.delete(pa); this.changed(); return true;
  }
  mkdir(path) { if (!this.mounted) return false; const p = normPath(path); if (this.isDir(p)) return true; this.dirs.push(p); this.changed(); return true; }
  rmdir(path) {
    if (!this.mounted) return false;
    const p = normPath(path); const i = this.dirs.indexOf(p);
    if (i < 0) return false;
    this.dirs.splice(i, 1); this.changed(); return true;
  }
  totalBytes() { return this.total; }
  usedBytes() { let u = 0; for (const v of this.files.values()) u += v.length; return u; }
  cardSize() { return this.present ? 15560867840 : 0; }
  cardType() { return this.present && this.mounted ? CARD_SD : CARD_NONE; }
  format() { this.files.clear(); this.dirs = []; this.changed(); return true; }
  changed() { if (this.onChange) this.onChange(); }
}

class File {
  constructor() { this.disk = null; this.p = ''; this.pos = 0; this.dir = false; this.wr = false; this.kids = []; this.kid = 0; }
  valid() { return this.disk !== null; }
  data() { return this.disk.files.get(this.p) || new Uint8Array(0); }
  // read(buf, n) -> bytes read; read() -> one byte or -1
  read(b, n) {
    if (b === undefined) {
      const one = new Uint8Array(1);
      return this.read(one, 1) === 1 ? one[0] : -1;
    }
    if (!this.disk || this.dir) return 0;
    const d = this.data();
    const k = this.pos < d.length ? Math.min(n, d.length - this.pos) : 0;
    if (k) bytesInto(b, d.subarray(this.pos, this.pos + k), k);
    this.pos += k;
    return k;
  }
  readBytes(b, n) { return this.read(b, n); }
  peek() { if (!this.disk || this.dir) return -1; const d = this.data(); return this.pos < d.length ? d[this.pos] : -1; }
  available() { if (!this.disk || this.dir) return 0; const d = this.data(); return this.pos < d.length ? d.length - this.pos : 0; }
  readStringUntil(t) { let s = ''; let c; while ((c = this.read()) >= 0 && c !== t) s += String.fromCharCode(c); return s; }
  write(b, n) {
    if (n === undefined) { return this.write(new Uint8Array([b & 0xFF]), 1); }
    if (!this.disk || !this.wr) return 0;
    const src = bytesOf(b, n);
    let d = this.data();
    const need = Math.max(d.length, this.pos + n);
    if (need > d.length) { const nd = new Uint8Array(need); nd.set(d); d = nd; }
    d.set(src.subarray(0, n), this.pos);
    this.disk.files.set(this.p, d);
    this.pos += n;
    this.disk.changed();
    return n;
  }
  print(s) { const t = typeof s === 'string' ? s : (typeof s === 'number' ? String(s) : jstr(s)); return this.write(cstr(t), t.length); }
  println(s) { return this.print(s === undefined ? '' : s) + this.print('\n'); }
  printf(fmt, ...args) { const t = cformat(fmt, args); this.write(cstr(t), t.length); return t.length; }
  size() { if (!this.disk || this.dir) return 0; return this.data().length; }
  seek(to) { if (!this.disk || this.dir) return false; this.pos = to >>> 0; return true; }
  position() { return this.pos; }
  flush() {}
  close() { this.disk = null; }
  isDirectory() { return this.dir; }
  name() { const k = this.p.lastIndexOf('/'); return S(this.p.slice(k + 1)); }
  path() { return S(this.p); }
  openNextFile() {
    if (!this.disk || !this.dir || this.kid >= this.kids.length) return new File();
    return this.disk.open(this.kids[this.kid++], 'r');
  }
  getNextFileName(isDir) {
    if (!this.disk || !this.dir || this.kid >= this.kids.length) { if (isDir) isDir[0] = false; return ''; }
    const k = this.kids[this.kid++];
    if (isDir) isDir[0] = this.disk.isDir(k);
    return k;
  }
  rewindDirectory() { this.kid = 0; }
  getLastWrite() { return 0; }
}

const LittleFS = new Disk('flash', 1500000);
const SD = new Disk('card', 15560867840);

// ---- the flash in the emulator's storage ----
// One storage key holds the whole flash: { files: {path: base64}, dirs: [...] }.
// It is written a moment after the last change, not on every byte.
const FLASH_KEY = 'pxp_flash_v1';
let flashSaveTimer = null;
function b64(bytes) { let s = ''; for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]); return btoa(s); }
function unb64(s) { const t = atob(s); const b = new Uint8Array(t.length); for (let i = 0; i < t.length; i++) b[i] = t.charCodeAt(i); return b; }
function flashLoad() {
  try {
    const v = hardwareAPI.storage.read(FLASH_KEY);
    if (!v) return;
    for (const k of Object.keys(v.files || {})) LittleFS.files.set(k, unb64(v.files[k]));
    LittleFS.dirs = (v.dirs || []).slice();
  } catch (e) { RT.logLine('[HW] flash could not be read back: ' + e.message); }
}
function flashSaveNow() {
  flashSaveTimer = null;
  const files = {};
  for (const [k, v] of LittleFS.files) files[k] = b64(v);
  try { hardwareAPI.storage.write(FLASH_KEY, { files, dirs: LittleFS.dirs }); }
  catch (e) { RT.logLine('[HW] flash could not be saved: ' + e.message); }
}
function flashSaveSoon() {
  if (RT.desk) return;
  if (flashSaveTimer) clearTimeout(flashSaveTimer);
  flashSaveTimer = setTimeout(flashSaveNow, 400);
}

// ============================================================================
// RUNTIME 5/6 - the board: what the phone's chips do, done by the emulator
// ============================================================================
// The phone talks to its parts through Serial, a UART (the modem), WiFi, I2S
// (speaker and microphone), I2C (the camera), SPI (the card). Each is here,
// answering the way the emulator's hardware behaves. With RT.desk set, each
// answers exactly as the desk phone's stand-ins do (desk/desk_support.cpp).

// ---- the log ----
const Serial = {
  line: '',
  begin() {}, flush() {}, setTimeout() {}, valid() { return true; },
  out(s) {
    for (let i = 0; i < s.length; i++) {
      const c = s[i];
      if (c === '\n') { RT.logLine(this.line); this.line = ''; }
      else if (c !== '\r') this.line += c;
    }
  },
  text(v, d) {
    if (typeof v === 'string') return v;
    if (typeof v === 'number') return d !== undefined ? Number(v).toFixed(d) : String(v);
    if (typeof v === 'boolean') return v ? '1' : '0';
    return jstr(v);
  },
  print(v, d) { const t = this.text(v, d); this.out(t); return t.length; },
  println(v, d) { const n = v === undefined ? 0 : this.print(v, d); this.out('\n'); return n + 1; },
  printf(fmt, ...a) { const t = cformat(fmt, a); this.out(t); return t.length; },
  available() { return 0; }, read() { return -1; },
  write(b, n) { if (n === undefined) { this.out(String.fromCharCode(b & 0xFF)); return 1; } this.out(jstr(bytesOf(b, n).slice(0, n))); return n; },
};

// ---- the modem's UART ----
class HardwareSerial {
  constructor(n) { this.n = n; }
  begin() {}
  flush() {}
  available() { const m = BOARD.modem; m.tick(); return m.rx.length - m.rxAt; }
  read() {
    const m = BOARD.modem;
    if (m.rxAt >= m.rx.length) return -1;
    const c = m.rx[m.rxAt++];
    if (m.rxAt > 4096) { m.rx = m.rx.slice(m.rxAt); m.rxAt = 0; }
    return c;
  }
  print(v) {
    const t = typeof v === 'string' ? v : (typeof v === 'number' ? String(v) : jstr(v));
    for (let i = 0; i < t.length; i++) BOARD.modem.fromPhone(t.charCodeAt(i) & 0xFF);
    return t.length;
  }
  println(v) { return this.print(v === undefined ? '' : v) + this.print('\r\n'); }
  write(b, n) {
    if (n === undefined) { BOARD.modem.fromPhone(b & 0xFF); return 1; }
    const bs = bytesOf(b, n);
    for (let i = 0; i < n; i++) BOARD.modem.fromPhone(bs[i]);
    return n;
  }
}

// What both modems share: the byte queue to the phone, and splitting the
// phone's bytes into AT command lines (and the text of an SMS after CMGS).
class ModemBase {
  constructor() { this.rx = []; this.rxAt = 0; this.tx = ''; this.cmgs = false; this.cmgsNum = ''; this.cmgsBody = []; this.atLog = []; }
  send(s) { for (let i = 0; i < s.length; i++) this.rx.push(s.charCodeAt(i) & 0xFF); }
  sendBytes(bs) { for (const b of bs) this.rx.push(b); }
  tick() {}
  fromPhone(c) {
    if (this.cmgs) {
      if (c === 0x1A) { this.cmgs = false; this.smsSubmit(this.cmgsNum, this.cmgsBody); }
      else if (c === 0x1B) { this.cmgs = false; this.send('\r\nOK\r\n'); }
      else this.cmgsBody.push(c);
      return;
    }
    if (c === 13) return;
    if (c === 10) { if (this.tx !== '') this.command(this.tx); this.tx = ''; return; }
    this.tx += String.fromCharCode(c);
  }
  static quoted(c) { const out = []; const re = /"([^"]*)"/g; let m; while ((m = re.exec(c))) out.push(m[1]); return out; }
}

// The desk phone's fake modem, line for line (desk/desk_support.cpp): PIN 1234,
// PUK 12345678, the network 2 s after the PIN, CSQ 24, operator 216-30 on
// EUTRAN-BAND3, a dialled call answered after 6 s, a text answered after 5 s.
class FakeModem extends ModemBase {
  constructor() {
    super();
    this.simIn = true; this.simPinEnabled = true; this.simLocked = true; this.pinAttempts = 3;
    this.pin = '1234'; this.puk = '12345678';
    this.registered = true; this.netReady = false; this.netAt = 0; this.signal = 24;
    this.callState = 'idle'; this.callNumber = ''; this.dialAnswerAt = 0; this.smsReplies = [];
  }
  state() { if (!this.simIn) return 'absent'; if (this.simLocked) return this.pinAttempts > 0 ? 'pin' : 'puk'; return 'ready'; }
  isRegistered() { return this.state() === 'ready' && this.registered && this.netReady; }
  attach() { this.netReady = false; this.netAt = (millis() + 2000) >>> 0; if (!this.netAt) this.netAt = 1; }
  lockNow() { if (!this.simIn || !this.simPinEnabled) return; this.simLocked = true; this.pinAttempts = 3; this.netReady = false; this.netAt = 0; }
  tick() {
    const now = millis();
    if (this.netAt && ((now - this.netAt) | 0) >= 0) { this.netAt = 0; if (this.state() === 'ready') this.netReady = true; }
    if (this.dialAnswerAt && ((now - this.dialAnswerAt) | 0) >= 0) {
      this.dialAnswerAt = 0;
      if (this.callState === 'dialing') { this.callState = 'active'; this.send('\r\nVOICE CALL: BEGIN\r\n'); }
    }
    for (let i = 0; i < this.smsReplies.length;) {
      if (((now - this.smsReplies[i][0]) | 0) >= 0) {
        if (this.simIn) this.incomingSms(this.smsReplies[i][1], 'ok, talk later');
        this.smsReplies.splice(i, 1);
      } else i++;
    }
  }
  incomingSms(from, body) { this.send('\r\n+CMT: "' + from + '","","26/11/13,13:00:00+04"\r\n' + body + '\r\n'); }
  ring(from) { this.callState = 'ringing'; this.callNumber = from; this.send('\r\nRING\r\n\r\n+CLIP: "' + from + '",145,,,,0\r\n'); }
  remoteHangup() { if (this.callState === 'idle') return; this.callState = 'idle'; this.callNumber = ''; this.dialAnswerAt = 0; this.send('\r\nVOICE CALL: END\r\n\r\nNO CARRIER\r\n'); }
  farEndAnswers() { if (this.callState !== 'dialing') return; this.dialAnswerAt = 0; this.callState = 'active'; this.send('\r\nVOICE CALL: BEGIN\r\n'); }
  setSim(isIn) { this.simIn = isIn; if (isIn) this.lockNow(); else { this.netReady = false; this.netAt = 0; } }
  smsSubmit(num, body) {
    this.atLog.push('SMS to ' + num + ': ' + String.fromCharCode(...body));
    this.send('\r\n+CMGS: 7\r\n\r\nOK\r\n');
    this.smsReplies.push([(millis() + 5000) >>> 0, num]);
  }
  command(c) {
    this.atLog.push(c);
    const ok = () => this.send('\r\nOK\r\n');
    const err = () => this.send('\r\nERROR\r\n');
    const q = (p) => c.startsWith(p);
    if (c === 'AT' || c === 'ATE0' || q('AT+CTZU') || q('AT+CMUT') || q('AT+CSDVC') || q('AT+CVHU') || q('AT+CLIP=') || q('AT+CNMI') || q('AT+CMGF')) {
      if ((q('AT+CNMI') || q('AT+CMGF')) && this.state() !== 'ready') { err(); return; }
      ok(); return;
    }
    if (c === 'AT+CPIN?') {
      const st = this.state();
      if (st === 'absent') this.send('\r\n+CME ERROR: SIM not inserted\r\n');
      else if (st === 'pin') this.send('\r\n+CPIN: SIM PIN\r\n\r\nOK\r\n');
      else if (st === 'puk') this.send('\r\n+CPIN: SIM PUK\r\n\r\nOK\r\n');
      else this.send('\r\n+CPIN: READY\r\n\r\nOK\r\n');
      return;
    }
    if (q('AT+CPIN=')) {
      const args = ModemBase.quoted(c);
      const st = this.state();
      if (st === 'pin' && args.length >= 1) {
        if (args[0] === this.pin) { this.simLocked = false; this.pinAttempts = 3; this.attach(); ok(); }
        else { this.pinAttempts--; this.send('\r\n+CME ERROR: incorrect password\r\n'); }
        return;
      }
      if (st === 'puk' && args.length >= 2) {
        if (args[0] === this.puk) { this.simLocked = false; this.pinAttempts = 3; this.pin = args[1]; this.attach(); ok(); }
        else this.send('\r\n+CME ERROR: incorrect password\r\n');
        return;
      }
      err(); return;
    }
    if (c === 'AT+SPIC') { this.send('\r\n+SPIC: ' + this.pinAttempts + ',10,3,10\r\n\r\nOK\r\n'); return; }
    if (q('AT+CLCK="SC",2')) { this.send('\r\n+CLCK: ' + (this.simPinEnabled ? '1' : '0') + '\r\n\r\nOK\r\n'); return; }
    if (q('AT+CLCK="SC",')) {
      const args = ModemBase.quoted(c);
      const mode = c.length > 13 ? c.charCodeAt(13) - 48 : -1;
      if (this.state() !== 'ready' || args.length < 2) { err(); return; }
      if (args[1] !== this.pin) { this.pinAttempts--; if (this.pinAttempts <= 0) this.simLocked = true; this.send('\r\n+CME ERROR: incorrect password\r\n'); return; }
      this.pinAttempts = 3; this.simPinEnabled = (mode === 1); ok(); return;
    }
    if (q('AT+CPWD="SC"')) {
      const args = ModemBase.quoted(c);
      if (this.state() !== 'ready' || args.length < 3) { err(); return; }
      if (args[1] !== this.pin) { this.pinAttempts--; if (this.pinAttempts <= 0) this.simLocked = true; this.send('\r\n+CME ERROR: incorrect password\r\n'); return; }
      this.pinAttempts = 3; this.pin = args[2]; ok(); return;
    }
    if (c === 'AT+CREG?') { this.send('\r\n+CREG: 0,' + (this.isRegistered() ? '1' : '2') + '\r\n\r\nOK\r\n'); return; }
    if (c === 'AT+CSQ') { this.send('\r\n+CSQ: ' + ((this.state() === 'ready' && this.netReady) ? this.signal : 99) + ',99\r\n\r\nOK\r\n'); return; }
    if (c === 'AT+CPSI?') {
      if (this.isRegistered()) this.send('\r\n+CPSI: LTE,Online,216-30,0x1A2B,12345678,123,EUTRAN-BAND3,1300,5,5,-90,-1000,-60,15\r\n\r\nOK\r\n');
      else this.send('\r\n+CPSI: NO SERVICE,Online\r\n\r\nOK\r\n');
      return;
    }
    if (c === 'AT+COPS?') { this.send(this.isRegistered() ? '\r\n+COPS: 0,2,"21630",7\r\n\r\nOK\r\n' : '\r\n+COPS: 0\r\n\r\nOK\r\n'); return; }
    if (c === 'AT+CNSMOD?') { this.send('\r\n+CNSMOD: 0,8\r\n\r\nOK\r\n'); return; }
    if (c === 'AT+CCLK?') { this.send('\r\n+CCLK: "70/01/01,00:00:12+00"\r\n\r\nOK\r\n'); return; }
    if (c === 'AT+CLCC') {
      if (this.callState === 'idle') { ok(); return; }
      const stat = this.callState === 'active' ? 0 : (this.callState === 'dialing' ? 2 : 4);
      const dir = this.callState === 'ringing' ? 1 : 0;
      this.send('\r\n+CLCC: 1,' + dir + ',' + stat + ',0,0,"' + this.callNumber + '",129\r\n\r\nOK\r\n'); return;
    }
    if (q('ATD')) {
      if (!this.isRegistered()) { this.send('\r\nNO CARRIER\r\n'); return; }
      let num = c.slice(3); if (num.endsWith(';')) num = num.slice(0, -1);
      this.callState = 'dialing'; this.callNumber = num; this.dialAnswerAt = (millis() + 6000) >>> 0; if (!this.dialAnswerAt) this.dialAnswerAt = 1;
      ok(); return;
    }
    if (c === 'ATA') { if (this.callState === 'ringing') { this.callState = 'active'; ok(); this.send('\r\nVOICE CALL: BEGIN\r\n'); } else err(); return; }
    if (c === 'ATH') { if (this.callState !== 'idle') { this.callState = 'idle'; this.callNumber = ''; this.dialAnswerAt = 0; } ok(); return; }
    if (q('AT+VTS=')) { ok(); return; }
    if (q('AT+CMGS="')) {
      if (!this.isRegistered()) { err(); return; }
      const b = c.indexOf('"', 9);
      this.cmgsNum = c.slice(9, b < 0 ? undefined : b);
      this.cmgs = true; this.cmgsBody = []; this.send('\r\n> '); return;
    }
    err();
  }
}

// The emulator's modem, spoken to in AT commands. The SIM, the network, calls
// and texts are the emulator's (its panel drives them); this turns its answers
// and its events into the lines the real BK-A7670 sends.
// What the emulator's modem cannot do - change the PIN, switch the PIN off -
// is done here, in a small emulated block: the PIN typed on the phone is
// checked against this block's copy, and the emulator's SIM (PIN 1234) is
// unlocked behind it.
const EMU_SIM_PIN = '1234';
class EmuModem extends ModemBase {
  constructor() { super(); this.pin = EMU_SIM_PIN; this.pinEnabled = true; }
  get M() { return hardwareAPI.modem; }
  utf8(s) { return Array.from(new TextEncoder().encode(String(s))); }
  stamp() {
    const tm_ = new tm(); localtime_r([time(null)], tm_);
    const off = Math.round((tm_.tm_gmtoff || 0) / 900);
    const p2 = (v) => String(v).padStart(2, '0');
    return p2(tm_.tm_year % 100) + '/' + p2(tm_.tm_mon + 1) + '/' + p2(tm_.tm_mday) + ',' + p2(tm_.tm_hour) + ':' + p2(tm_.tm_min) + ':' + p2(tm_.tm_sec) + (off < 0 ? '-' : '+') + p2(Math.abs(off));
  }
  // ---- the emulator's events ----
  ring(num) { this.send('\r\nRING\r\n\r\n+CLIP: "'); this.sendBytes(this.utf8(num)); this.send('",145,,,,0\r\n'); }
  connected() { this.send('\r\nVOICE CALL: BEGIN\r\n'); }
  ended() { this.send('\r\nVOICE CALL: END\r\n\r\nNO CARRIER\r\n'); }
  sms(from, body) {
    this.send('\r\n+CMT: "'); this.sendBytes(this.utf8(from)); this.send('","","' + this.stamp() + '"\r\n');
    this.sendBytes(this.utf8(String(body).replace(/\r?\n/g, ' '))); this.send('\r\n');
  }
  state() {
    let st = this.M.getSimState();
    if (st === 'pin' && !this.pinEnabled) { this.M.enterPin(EMU_SIM_PIN); st = this.M.getSimState(); }
    return st;
  }
  smsSubmit(num, body) {
    let text;
    try { text = new TextDecoder('utf-8', { fatal: true }).decode(new Uint8Array(body)); }
    catch (e) { text = String.fromCharCode(...body); }
    if (this.M.sendSMS(num, text)) this.send('\r\n+CMGS: 7\r\n\r\nOK\r\n');
    else this.send('\r\nERROR\r\n');
  }
  command(c) {
    const M = this.M;
    const ok = () => this.send('\r\nOK\r\n');
    const err = () => this.send('\r\nERROR\r\n');
    const q = (p) => c.startsWith(p);
    if (c === 'AT' || c === 'ATE0' || q('AT+CTZU') || q('AT+CMUT') || q('AT+CSDVC') || q('AT+CVHU') || q('AT+CLIP=') || q('AT+CNMI') || q('AT+CMGF')) {
      if ((q('AT+CNMI') || q('AT+CMGF')) && this.state() !== 'ready') { err(); return; }
      ok(); return;
    }
    if (c === 'AT+CPIN?') {
      const st = this.state();
      if (st === 'absent') this.send('\r\n+CME ERROR: SIM not inserted\r\n');
      else if (st === 'pin') this.send('\r\n+CPIN: SIM PIN\r\n\r\nOK\r\n');
      else if (st === 'puk') this.send('\r\n+CPIN: SIM PUK\r\n\r\nOK\r\n');
      else this.send('\r\n+CPIN: READY\r\n\r\nOK\r\n');
      return;
    }
    if (q('AT+CPIN=')) {
      const args = ModemBase.quoted(c);
      const st = this.state();
      if (st === 'pin' && args.length >= 1) {
        const r = M.enterPin(args[0] === this.pin ? EMU_SIM_PIN : '\u0000' + args[0]);
        if (r && r.ok) ok(); else this.send('\r\n+CME ERROR: incorrect password\r\n');
        return;
      }
      if (st === 'puk' && args.length >= 2) {
        const r = M.enterPuk(args[0], args[1]);
        if (r && r.ok) { this.pin = args[1]; ok(); } else this.send('\r\n+CME ERROR: incorrect password\r\n');
        return;
      }
      err(); return;
    }
    if (c === 'AT+SPIC') { const a = M.getPinAttempts(); this.send('\r\n+SPIC: ' + a.pin + ',10,3,10\r\n\r\nOK\r\n'); return; }
    if (q('AT+CLCK="SC",2')) { this.send('\r\n+CLCK: ' + (this.pinEnabled ? '1' : '0') + '\r\n\r\nOK\r\n'); return; }
    if (q('AT+CLCK="SC",')) {
      const args = ModemBase.quoted(c);
      const mode = c.length > 13 ? c.charCodeAt(13) - 48 : -1;
      if (this.state() !== 'ready' || args.length < 2) { err(); return; }
      if (args[1] !== this.pin) { this.send('\r\n+CME ERROR: incorrect password\r\n'); return; }
      this.pinEnabled = (mode === 1); ok(); return;
    }
    if (q('AT+CPWD="SC"')) {
      const args = ModemBase.quoted(c);
      if (this.state() !== 'ready' || args.length < 3) { err(); return; }
      if (args[1] !== this.pin) { this.send('\r\n+CME ERROR: incorrect password\r\n'); return; }
      this.pin = args[2]; ok(); return;
    }
    if (c === 'AT+CREG?') { this.send('\r\n+CREG: 0,' + (M.isRegistered() ? '1' : '2') + '\r\n\r\nOK\r\n'); return; }
    if (c === 'AT+CSQ') { this.send('\r\n+CSQ: ' + M.getSignal() + ',99\r\n\r\nOK\r\n'); return; }
    if (c === 'AT+CPSI?') {
      if (M.isRegistered()) this.send('\r\n+CPSI: LTE,Online,' + M.getOperator() + ',0x1A2B,12345678,123,' + M.getBand() + ',1300,5,5,-90,-1000,-60,15\r\n\r\nOK\r\n');
      else this.send('\r\n+CPSI: NO SERVICE,Online\r\n\r\nOK\r\n');
      return;
    }
    if (c === 'AT+COPS?') { this.send(M.isRegistered() ? '\r\n+COPS: 0,2,"' + M.getOperator().replace('-', '') + '",7\r\n\r\nOK\r\n' : '\r\n+COPS: 0\r\n\r\nOK\r\n'); return; }
    if (c === 'AT+CNSMOD?') { this.send('\r\n+CNSMOD: 0,8\r\n\r\nOK\r\n'); return; }
    if (c === 'AT+CCLK?') { this.send('\r\n+CCLK: "' + (M.isRegistered() ? this.stamp() : '70/01/01,00:00:12+00') + '"\r\n\r\nOK\r\n'); return; }
    if (c === 'AT+CLCC') {
      const cs = M.getCallState();
      if (cs === 'idle') { ok(); return; }
      const stat = cs === 'active' ? 0 : (cs === 'dialing' ? 2 : 4);
      const dir = cs === 'ringing' ? 1 : 0;
      this.send('\r\n+CLCC: 1,' + dir + ',' + stat + ',0,0,"'); this.sendBytes(this.utf8(M.getCallNumber())); this.send('",129\r\n\r\nOK\r\n'); return;
    }
    if (q('ATD')) {
      let num = c.slice(3); if (num.endsWith(';')) num = num.slice(0, -1);
      if (!M.dial(num)) { this.send('\r\nNO CARRIER\r\n'); return; }
      ok(); return;
    }
    if (c === 'ATA') { if (M.answer()) { ok(); this.send('\r\nVOICE CALL: BEGIN\r\n'); } else err(); return; }
    if (c === 'ATH') { M.hangup(); ok(); return; }
    if (q('AT+VTS=')) { ok(); return; }
    if (q('AT+CMGS="')) {
      if (!M.isRegistered()) { err(); return; }
      const b = c.indexOf('"', 9);
      this.cmgsNum = c.slice(9, b < 0 ? undefined : b);
      this.cmgs = true; this.cmgsBody = []; this.send('\r\n> '); return;
    }
    err();
  }
}

