// ---- the camera: the emulator's picture (its grain), as an OV2640 would deliver it ----
// Frames come as "JPEG": a JPEG header the phone's jpegSize() reads, and the
// pixels kept raw in it (segment APP15 "PXPR") - jpg2rgb565() and fmt2rgb888()
// below unpack them. Photos saved to the card are in this form too.
const FRAME_SIZES = [[96, 96], [160, 120], [176, 144], [240, 176], [240, 240], [320, 240], [400, 296], [480, 320],
                     [640, 480], [800, 600], [1024, 768], [1280, 720], [1280, 1024], [1600, 1200]];
const CAM = { ready: false, size: 1, sensor: null, canvas: null };
function esp_camera_init(cfg) {
  if (RT.desk) return -1;
  CAM.ready = true; CAM.size = cfg.frame_size;
  const sn = new sensor_t();
  for (const k of Object.keys(sn)) if (k.startsWith('set_')) sn[k] = () => 0;
  sn.set_framesize = (s, fs) => { CAM.size = fs; return 0; };
  sn.id.PID = 0x26; sn.id.MIDH = 0x7F; sn.id.MIDL = 0xA2;
  CAM.sensor = sn;
  return 0;
}
function esp_camera_deinit() { CAM.ready = false; return 0; }
function esp_camera_sensor_get() { return CAM.ready ? CAM.sensor : null; }
function esp_camera_fb_return() {}
function esp_camera_fb_get() {
  if (!CAM.ready) return null;
  const [w, h] = FRAME_SIZES[CAM.size] || [160, 120];
  const px = cameraPixels(w, h);             // RGB565, one per pixel
  const jpg = fakeJpeg(w, h, px);
  const fb = new camera_fb_t();
  fb.buf = jpg; fb.len = jpg.length; fb.width = w; fb.height = h; fb.format = PIXFORMAT_JPEG;
  return fb;
}
// the emulator's preview, w x h, as RGB565
function cameraPixels(w, h) {
  const out = new Uint16Array(w * h);
  try {
    if (typeof document === 'undefined') return out;
    if (!CAM.canvas) CAM.canvas = document.createElement('canvas');
    const c = CAM.canvas; c.width = w; c.height = h;
    const ctx = c.getContext('2d');
    if (hardwareAPI.camera && hardwareAPI.camera.drawPreview) hardwareAPI.camera.drawPreview(ctx, w, h);
    const d = ctx.getImageData(0, 0, w, h).data;
    for (let i = 0; i < w * h; i++) out[i] = ((d[i * 4] >> 3) << 11) | ((d[i * 4 + 1] >> 2) << 5) | (d[i * 4 + 2] >> 3);
  } catch (e) { /* a black frame then */ }
  return out;
}
function fakeJpeg(w, h, px) {
  const raw = new Uint8Array(px.buffer, px.byteOffset, px.length * 2);
  const CH = 65000;
  const nseg = Math.ceil(raw.length / CH);
  const out = new Uint8Array(2 + 19 + nseg * (4 + 4) + raw.length + 2);
  let o = 0;
  out[o++] = 0xFF; out[o++] = 0xD8;                                    // SOI
  const sof = [0xFF, 0xC0, 0, 17, 8, h >> 8, h & 255, w >> 8, w & 255, 3, 1, 0x22, 0, 2, 0x11, 1, 3, 0x11, 1];
  out.set(sof, o); o += sof.length;                                    // SOF0: the size jpegSize() reads
  for (let s = 0; s < nseg; s++) {
    const part = raw.subarray(s * CH, Math.min(raw.length, (s + 1) * CH));
    const L = part.length + 6;
    out[o++] = 0xFF; out[o++] = 0xEF; out[o++] = L >> 8; out[o++] = L & 255;
    out[o++] = 80; out[o++] = 88; out[o++] = 80; out[o++] = 82;          // "PXPR"
    out.set(part, o); o += part.length;
  }
  out[o++] = 0xFF; out[o++] = 0xD9;                                    // EOI
  return out;
}
// the pixels back out of a frame (null if it is not one of ours)
function fakeJpegPixels(buf, len) {
  const d = bytesOf(buf, len);
  if (d[0] !== 0xFF || d[1] !== 0xD8 || d[2] !== 0xFF || d[3] !== 0xC0) return null;
  const h = (d[7] << 8) | d[8], w = (d[9] << 8) | d[10];
  const raw = new Uint8Array(w * h * 2);
  let o = 21, r = 0;
  while (o + 8 <= len && d[o] === 0xFF && d[o + 1] === 0xEF) {
    const L = (d[o + 2] << 8) | d[o + 3];
    raw.set(d.subarray(o + 8, o + 2 + L), r); r += L - 6; o += 2 + L;
  }
  return { w, h, px: new Uint16Array(raw.buffer) };
}
// scale: 0 = 1:1, 1 = 1/2, 2 = 1/4, 3 = 1/8 (as the ESP32 decoder)
function jpg2rgb565(buf, len, out, scale) {
  const f = fakeJpegPixels(buf, len);
  if (!f) return false;
  const div = 1 << scale, ow = Math.floor(f.w / div), oh = Math.floor(f.h / div);
  const o16 = view(out, Uint16Array);
  for (let y = 0; y < oh; y++) for (let x = 0; x < ow; x++) o16[y * ow + x] = f.px[(y * div) * f.w + x * div];
  return true;
}
function fmt2rgb888(buf, len, format, out) {
  const f = fakeJpegPixels(buf, len);
  if (!f) return false;
  for (let i = 0; i < f.w * f.h; i++) {
    const c = f.px[i];
    const r = (c >> 11) & 31, g = (c >> 5) & 63, b = c & 31;
    out[i * 3] = (b << 3) | (b >> 2); out[i * 3 + 1] = (g << 2) | (g >> 4); out[i * 3 + 2] = (r << 3) | (r >> 2);   // BGR, as the ESP32's converter
  }
  return true;
}
function frame2jpg() { return false; }
function fmt2jpg() { return false; }

// ============================================================================
// BOARD: the screens, the speaker, the audio task, power
// ============================================================================
const BOARD = {
  modem: null,
  task: null,                 // the audio task's one-pass function, once the phone starts it
  taskT: 0,                   // where the task has got to (phone ms): its writes and its sleeps move it on
  inTask: false,
  i2sRate: [16000, 16000],
  speaker: { cursor: 0, sources: [], gain: null },
  taskStarted(fn) {
    if (RT.desk) return;      // the desk phone never runs it
    if (fn === audioTask) this.task = audioTask__step;
  },
  taskDelay(ticks) { if (this.inTask) this.taskT += Number(ticks) || 1; },
  i2sRead(port, n) {
    if (this.inTask) this.taskT += (n / 2) / (this.i2sRate[port] || 16000) * 1000;
  },
  i2sWrite(port, buf, n) {
    const rate = this.i2sRate[port] || 16000;
    const samples = n >> 1;
    const ms = samples / rate * 1000;
    if (port === 1) this.play(buf, samples, rate);
    if (this.inTask) this.taskT += ms;
  },
  // runs the audio task until its sound reaches a little ahead of now
  runAudio() {
    if (!this.task) return;
    const now = millis();
    if (this.taskT < now) this.taskT = now;
    let steps = 0;
    while (this.taskT < now + 80 && steps < 60) {
      const before = this.taskT;
      this.inTask = true;
      try { this.task(); } finally { this.inTask = false; }
      if (this.taskT === before) this.taskT += 1;     // a pass that neither played nor slept still takes a moment
      steps++;
    }
  },
  // ---- the speaker: the task's samples, through the emulator's audio ----
  audioCtx() {
    const a = hardwareAPI.audio;
    if (!a || !a.ctx || a.ctx.state !== 'running') return null;
    return a.ctx;
  },
  play(buf, samples, rate) {
    if (RT.desk) return;
    const ctx = this.audioCtx();
    if (!ctx || samples <= 0) return;
    const sp = this.speaker;
    if (!sp.gain || sp.gain.context !== ctx) { sp.gain = ctx.createGain(); sp.gain.connect(ctx.destination); }
    sp.gain.gain.value = hardwareAPI.audio.volume === undefined ? 0.5 : hardwareAPI.audio.volume;
    const src16 = view(buf, Int16Array);
    let silent = true;
    for (let i = 0; i < samples; i++) if (src16[i] !== 0) { silent = false; break; }
    // where this piece belongs on the audio clock: the task's time, or straight after what is queued
    const lead = this.inTask ? (this.taskT - millis()) / 1000 : 0;
    let at = Math.max(ctx.currentTime + 0.03 + lead, sp.cursor);
    if (sp.cursor < ctx.currentTime) at = ctx.currentTime + 0.03 + Math.max(0, lead);
    sp.cursor = at + samples / rate;
    if (silent) return;
    this.played = (this.played || 0) + 1;
    const ab = ctx.createBuffer(1, samples, rate);
    const ch0 = ab.getChannelData(0);
    for (let i = 0; i < samples; i++) ch0[i] = src16[i] / 32768;
    const node = ctx.createBufferSource();
    node.buffer = ab; node.connect(sp.gain); node.start(at);
    sp.sources.push(node);
    node.onended = () => { const i = sp.sources.indexOf(node); if (i >= 0) sp.sources.splice(i, 1); };
  },
  speakerFlush() {
    const ctx = this.audioCtx();
    for (const s of this.speaker.sources.slice()) { try { s.stop(ctx ? ctx.currentTime : 0); } catch (e) {} }
    this.speaker.sources.length = 0;
    this.speaker.cursor = 0;
  },
};

// ---- the screens: what the phone sent to its PC viewer, the emulator shows ----
