// RGB565 -> the canvas
const BLIT = { img: {} };
function blitTo(ctx, fb, w, h) {
  if (!fb) return;
  let img = BLIT.img[w];
  if (!img || img.width !== w) { img = BLIT.img[w] = ctx.createImageData(w, h); }
  const d = img.data;
  for (let i = 0, j = 0; i < w * h; i++, j += 4) {
    const c = fb[i];
    const r = (c >> 11) & 31, g = (c >> 5) & 63, b = c & 31;
    d[j] = (r << 3) | (r >> 2); d[j + 1] = (g << 2) | (g >> 4); d[j + 2] = (b << 3) | (b >> 2); d[j + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
}

