const CAM_D6 = 41;
const CAM_D7 = 42;
const CAM_VSYNC = 1;
const CAM_HREF = 2;
const CAM_PCLK = 47;  // <- the module's DCLK pin goes here
const CAM_XCLK = 14;  // spare, only used if the module needs feeding
// The sensor makes SMALL frames for preview and a BIG one only when you shoot.
// Decoding is the expensive part of preview, and it scales with sensor pixels:
// QVGA is ~6x cheaper to decode than SVGA. Raise CAM_PREVIEW_SIZE for a nicer
// preview at the cost of CPU; raise CAM_PHOTO_SIZE for better photos (free -
// the shutter saves the sensor's JPEG without decoding it at all).
const CAM_PREVIEW_SIZE = FRAMESIZE_QQVGA;  // 160x120 live — was QVGA (320x240); ~4x cheaper to decode
const CAM_PHOTO_SIZE = FRAMESIZE_SVGA;  // 800x600 saved
let camReady = false;
let camSensorAddr = 0;

// ---- Mic + speaker (I2S, from the earlier chatbot build) ----
// Wired since stage 1 but never brought up by this OS until Voice Memos -
// everything else (call UI) still leaves these off until stage 7 (FINDINGS §12).
// Separate as WS/SCK/SD, not CLK+DATA, so this is a standard I2S mic, not PDM.
const MIC_WS = 4;
const MIC_SCK = 5;
const MIC_SD = 6;
const SPK_DIN = 7;
const SPK_BCLK = 15;
const SPK_LRC = 16;
// 16kHz/16-bit mono: the standard "voice memo" quality (phone calls run at
// 8kHz). Keeps the SD write rate to 32KB/s - trivial even at the breadboard's
// 4MHz SPI - and keeps the I2S DMA reads small enough not to compete with
// everything else the loop is already doing.
const AUDIO_SAMPLE_RATE = 16000;
const AUDIO_BYTES_PER_SAMPLE = 2;
const AUDIO_BYTES_PER_SEC = (AUDIO_SAMPLE_RATE * AUDIO_BYTES_PER_SAMPLE);
// A sound that plays ONCE - a ringtone preview, the text tone, the beep, a
// voice memo - ends with this much silence before the speaker is cleared. The
// speaker's DMA ring holds 8 x 512 samples (256 ms) still waiting to be heard,
// and clearing it the moment the last note was written threw that away: the
// end of a preview was cut off by a random amount. This is longer than the ring
// plus one buffer, so by the time it is cleared only silence is left in it.
const PLAY_TAIL_MS = 350;
const PLAY_TAIL_SAMPLES = Math.trunc(u32(Math.imul(PLAY_TAIL_MS, AUDIO_SAMPLE_RATE)) / 1000);
let audioMicReady = false;
let audioSpkReady = false;

