// Where we are. A stack rather than a single parent, so depth can grow later
// without rewriting Back.
let setPage = PG_ROOT;
let setRow = 0;
let setStackPage = new Uint8Array(4), setStackRow = new Uint8Array(4);
let setDepth = 0;

// Filled from the CPSI sweep, which until now formatted the reply into a log
// line and threw the parsed value away.
let netOperator = cbuf(16, "");
let netBand = cbuf(16, "");

// ⚠️ Defensive on purpose. CPSI's field layout differs between LTE and GSM, so
// this takes what it can RECOGNISE - an MCC-MNC in field 2, and any field
// containing "BAND" - rather than trusting fixed offsets. Unrecognised leaves
// the string empty and the row shows "--", which is honest. Untestable with no
// SIM in the tray.
function netParseCPSI(line) {
  netOperator[0] = 0; netBand[0] = 0;
  // atLine() hands over the reply with "+CPSI:" already cut off. This used to
  // insist on finding that colon and gave up without it, so the Network page
  // said "--" for operator and band even on a live network.
  let colon = line.indexOf(String.fromCharCode(ch(':')), );
  let s = (colon >= 0) ? line.substring(u32(colon + 1)) : line; s = strTrim(s);
  let f = 0, from = 0;
  while (from <= i32(s.length)) {
    let c = s.indexOf(String.fromCharCode(ch(',')), u32(from));
    let tok = (c < 0) ? s.substring(u32(from)) : s.substring(u32(from), u32(c));
    tok = strTrim(tok);
    if (f == 2 && tok.indexOf(String.fromCharCode(ch('-')), ) > 0)
      strncpy(netOperator, cstr(tok), u32(netOperator.length - 1));
    if (tok.indexOf("BAND", ) >= 0)
      strncpy(netBand, cstr(tok), u32(netBand.length - 1));
    else if (f == 0 && tok == "GSM" && netBand[0] == 0)
      strncpy(netBand, S("GSM"), u32(netBand.length - 1));
    if (c < 0) break;
    from = c + 1; f++;
  }
}

