// colour - callFlash is always red because it only reports a call that
// cannot happen.
let uiFlash = cbuf(40, "");
let uiFlashUntil = 0;
let uiFlashColour = 0;
function uiFlashShow(text, colour) {
  strncpy(uiFlash, text, u32(uiFlash.length - 1));
  uiFlash[uiFlash.length - 1] = 0;
  uiFlashColour = colour;
  uiFlashUntil  = u32(millis() + 2500);
}

