let fadeStartMs = 0;
let fadeNextMs = 0;
const FADE_DUR = 1000;

const DIGIT_LARGE = 8, DIGIT_MEDIUM = 4, DIGIT_SMALL = 2;

// ---- Name-text sizes, in 3x5 grid-font units. Height on screen = 5 x unit. ----
// Chosen against the REAL panel size, not how it looks zoomed on the PC:
//   inner panel 2.4" 240x320 -> 1 pixel = 0.152 mm
//   outer panel 1.5" 128x128 -> 1 pixel = 0.210 mm  (outer pixels are BIGGER)
// Below ~1.2 mm text is a squint. That rules out anything under 8px on the
// inner screen, which is why the old 7px "Aug" (1.07 mm) had to go.
const DAYNAME_UNIT_IN = 2;   // 10px = 1.52 mm - same size as the month below
                                 // Was 3 (15px). At unit 3 a 3-letter day name is
                                 // 33px against the 28px seconds beneath it, so it
                                 // stuck 5px out past the right edge. Unit 2 makes
                                 // it 22px: 6px short instead, which reads as margin
                                 // rather than overflow, and it matches MONTH_UNIT_IN
                                 // so the day and the month become a matched pair.
                                 // There is nothing between - the grid steps 11px at
                                 // a time for three glyphs. If 10px turns out too
                                 // small on the real panel, put it back to 3.
const MONTH_UNIT_IN = 2;   // 10px = 1.52 mm  readable
const MONTH_UNIT_OUT = 2;   // 10px = 2.10 mm  comfortable
const DATE_UNIT_OUT = 2;   // 10px = 2.10 mm  comfortable

// Shift the date row right to open up room after the month. One quarter-size
// character cell = 3 columns + its gap = 8px. Set to 0 for the strict old grid.
const DATE_NUDGE = 8;

// ---- Hold-to-repeat (burst delete etc). Real buttons send press AND release,
// so the repeat lives here on the device, not in the PC app. ----
// ---- hold-to-repeat ----
// The layering here is the hardware's, not ours: the keypad reports a key going
// down and coming back up, and the OS alone decides whether a continuous hold
// means one input, or one every N ms. The bridge already sends a release on
// KEYUP, which is what handleReleaseMsg() cancels the repeat on.
//
// The cadence is per-use because the two uses want opposite things: burst-delete
// wants to be fast enough to clear a field, a list wants to be slow enough that
// you can stop on the row you wanted.
let repeatBtn = "";
let repeatNext = 0;
let repeatEvery = 100;
const REPEAT_FIRST = 400;   // wait this long before the burst starts
const REPEAT_DELETE = 100;   // burst-delete: fast, you are clearing a field
const REPEAT_SCROLL = 250;   // list scrolling: slow enough to land on a row

function repeatArm(b, every) {
  repeatBtn = b; repeatEvery = every; repeatNext = u32(millis() + REPEAT_FIRST);
}

// Which screens let a held arrow keep scrolling. This is an OPT-IN list and must
// stay one: in ST_INCALL the arrows toggle the speaker, so arming repeat there
// would flap it on and off four times a second for as long as you held the key.
function stateScrollsWithArrows(s) {
  return s == ST_MENU     || s == ST_CONTACTS  || s == ST_MESSAGES || s == ST_CHAT
      || s == ST_CALLLOG  || s == ST_GALLERY   || s == ST_APPS     || s == ST_GAMES
      || s == ST_SETPAGE  || s == ST_RINGTONES || s == ST_TEXTTONES || s == ST_THEME
      || s == ST_ALARMTONES   // the alarm sound list, like the other two (9 Nov)
      || s == ST_THEME_RGB    // up/down picks the channel, so it scrolls too
      || s == ST_NOTES || s == ST_NOTE_VIEW
      || s == ST_CAL || s == ST_CAL_DAY   // a week at a time; the day page's entries
      || s == ST_ALARMS
      || s == ST_FILES || s == ST_FILES_TEXT   // the File explorer's list and a text file (9 Nov)
      || s == ST_MUSIC || s == ST_MUSIC_NOW    // Music's list; Now playing: up/down is the volume (11 Nov)
      || s == ST_TEXTEDIT;    // a line up or down in a long field (a message, a note)
}

// Left/right repeat on a NUMBER row in Settings, the same way the RGB sliders
// do. A number row only - a held key on an on/off row would flip it on, off, on,
// off for as long as it was held. No SetRow in the signature, on purpose: the
// auto-prototype trap from §1.2n.
function setRowRepeats() {
  return state == ST_SETPAGE
      && (SET_PAGES[setPage].rows)[setRow].kind == SK_RANGE;
}

// "Calls" sits with Messages and Contacts, where anyone would look for it.
// It used to be buried as row 5 of Settings, which is why it was impossible
// to find. Everything after index 1 shifted up by one - the dispatch in
// osButtonPress() was renumbered to match.
// Top level, in the order you actually reach for them. Everything that is not
// a first-class phone function now lives one level down in Apps or Games, so
// this list stops growing every time something new is built.
const menuNames = [S("Contacts"), S("Messages"), S("Call log"), S("Camera"),
                            S("Gallery"), S("Apps"), S("Games"), S("Settings")];
const menuCount = 8;

// ---- Apps submenu ----
// All real (File explorer since 9 Nov, Music and pptransfer since 11 Nov).
// pptransfer took Wallet's row: Wallet is dropped - the v1 prototype has no
// chip to sign offline (the owner, 11 Nov). Names taken from FINDINGS.md
// section 12's "Not started" list so the plan and the phone agree with each other.
const appsItems = [S("Voice memos"), S("Calendar"), S("Notes"), S("Calculator"),
                           S("Alarms"), S("File explorer"), S("Music"), S("pptransfer")];
const appsCount = 8;
let appsIdx = 0, appsTop = 0;

// ---- Games submenu ----
// Pong is first on purpose: it is the minimal dirty-rectangle case - three
// moving objects, constant, forever. Snake's dirty area grows with the body,
// so a fault in the frame loop shows up gradually and tangled with the growth
// logic. Pong's never changes size, so a fault shows immediately and alone.
const gamesItems = [S("Pong"), S("Snake"), S("Minesweeper"), S("Wirestack"), S("P_P's Casino"), S("Starfall"), S("Doom")];
const gamesCount = 7;               // Minesweeper added; Wirestack, our own falling blocks, in Tetris's place (the owner, 12 Nov); Blackjack inside P_P's Casino (13 Nov)
let gamesIdx = 0, gamesTop = 0;

// Whatever the "Coming soon" screen should call itself. Used to be indexed off
// menuNames[], which cannot name anything that lives in a submenu.
let comingSoonName = S("");
let comingSoonReturn = ST_MENU;   // which screen "Back" goes to

// Where a REAL app opened from a submenu should return to. Voice memos lives
// under Apps now, so its Back key has to land in the Apps list, not skip a
// whole level out to the main menu. Set on the way in.
let appReturnTo = ST_MENU;

// ==================== PIXEL DIGIT FONT (same shapes as pxp_os.js) ====================
// Each glyph: width in columns + 5 rows. In every row, bit0 = leftmost column.
// (struct DigitGlyph is defined at the top of the file.)

const DG_0 = mk(DigitGlyph, 3, new Uint8Array([7,5,5,5,7]));
const DG_1 = mk(DigitGlyph, 3, new Uint8Array([2,3,2,2,7]));
const DG_2 = mk(DigitGlyph, 3, new Uint8Array([7,4,7,1,7]));
const DG_3 = mk(DigitGlyph, 3, new Uint8Array([7,4,7,4,7]));
const DG_4 = mk(DigitGlyph, 3, new Uint8Array([5,5,7,4,4]));
const DG_5 = mk(DigitGlyph, 3, new Uint8Array([7,1,7,4,7]));
const DG_6 = mk(DigitGlyph, 3, new Uint8Array([7,1,7,5,7]));
const DG_7 = mk(DigitGlyph, 3, new Uint8Array([7,4,2,1,1]));
const DG_8 = mk(DigitGlyph, 3, new Uint8Array([7,5,7,5,7]));
const DG_9 = mk(DigitGlyph, 3, new Uint8Array([7,5,7,4,7]));
const DG_COL = mk(DigitGlyph, 1, new Uint8Array([0,1,0,1,0]));
const DG_DOT = mk(DigitGlyph, 1, new Uint8Array([0,0,0,0,1]));
const DG_PCT = mk(DigitGlyph, 3, new Uint8Array([5,4,2,1,5]));
const DG_PLS = mk(DigitGlyph, 3, new Uint8Array([0,2,7,2,0]));   // +
const DG_STR = mk(DigitGlyph, 3, new Uint8Array([5,2,7,2,5]));   // *
const DG_HSH = mk(DigitGlyph, 3, new Uint8Array([2,7,2,7,2]));   // #

function digitGlyph(c) {
  switch (c) {
    case ch('0'): return DG_0; case ch('1'): return DG_1; case ch('2'): return DG_2;
    case ch('3'): return DG_3; case ch('4'): return DG_4; case ch('5'): return DG_5;
    case ch('6'): return DG_6; case ch('7'): return DG_7; case ch('8'): return DG_8;
    case ch('9'): return DG_9; case ch(':'): return DG_COL; case ch('.'): return DG_DOT;
    case ch('%'): return DG_PCT; case ch('+'): return DG_PLS; case ch('*'): return DG_STR;
    case ch('#'): return DG_HSH; default: return null;
  }
}

// ==================== 3x5 GRID LETTER FONT ====================
// Letters on EXACTLY the same grid as the digits: 3 columns wide, 5 rows tall,
// one-unit gap between glyphs. So at pixel size p a letter is 5p tall - the same
// height as a digit at the same p. That gives sizes the 5x7 text font can't
// reach (10px instead of only 7 or 14), and everything stays on the pixel grid.
// Covers just the letters used by day and month names.
const LETTERS3x5 = [
  mk(LetterGlyph, ch('A'),new Uint8Array([2,5,7,5,5])), mk(LetterGlyph, ch('D'),new Uint8Array([3,5,5,5,3])), mk(LetterGlyph, ch('F'),new Uint8Array([7,1,3,1,1])), mk(LetterGlyph, ch('J'),new Uint8Array([4,4,4,5,2])),
  mk(LetterGlyph, ch('M'),new Uint8Array([5,7,7,5,5])), mk(LetterGlyph, ch('N'),new Uint8Array([5,7,7,7,5])), mk(LetterGlyph, ch('O'),new Uint8Array([7,5,5,5,7])), mk(LetterGlyph, ch('S'),new Uint8Array([7,1,7,4,7])),
  mk(LetterGlyph, ch('T'),new Uint8Array([7,2,2,2,2])), mk(LetterGlyph, ch('W'),new Uint8Array([5,5,7,7,5])),
  mk(LetterGlyph, ch('a'),new Uint8Array([0,2,5,7,5])), mk(LetterGlyph, ch('b'),new Uint8Array([1,1,3,5,3])), mk(LetterGlyph, ch('c'),new Uint8Array([0,6,1,1,6])), mk(LetterGlyph, ch('d'),new Uint8Array([4,4,6,5,6])),
  mk(LetterGlyph, ch('e'),new Uint8Array([0,6,7,1,6])), mk(LetterGlyph, ch('g'),new Uint8Array([0,7,5,7,4])), mk(LetterGlyph, ch('h'),new Uint8Array([1,1,3,5,5])), mk(LetterGlyph, ch('i'),new Uint8Array([2,0,2,2,2])),
  mk(LetterGlyph, ch('l'),new Uint8Array([2,2,2,2,2])), mk(LetterGlyph, ch('n'),new Uint8Array([0,3,5,5,5])), mk(LetterGlyph, ch('o'),new Uint8Array([0,2,5,5,2])), mk(LetterGlyph, ch('p'),new Uint8Array([0,3,5,3,1])),
  mk(LetterGlyph, ch('r'),new Uint8Array([0,3,5,1,1])), mk(LetterGlyph, ch('t'),new Uint8Array([2,7,2,2,6])), mk(LetterGlyph, ch('u'),new Uint8Array([0,5,5,5,6])), mk(LetterGlyph, ch('v'),new Uint8Array([0,5,5,5,2])),
  mk(LetterGlyph, ch('y'),new Uint8Array([0,5,5,6,4]))
];
const LETTERS3x5_COUNT = i32(Math.trunc(162 /*sizeof(LETTERS3x5)*/ / 6 /*sizeof(LETTERS3x5[0])*/));

function letter3x5(c) {
  for (let i = 0; i < LETTERS3x5_COUNT; i++)
    if (LETTERS3x5[i].ch == c) return LETTERS3x5[i].rows;
  return null;
}

// Width a word will occupy, without drawing it (needed for centring).
function measureLetterStringW(str, ps) {
  let n = 0;
  for (let p = str; p[0]; p = ptrAdd(p, 1)) n++;
  if (n == 0) return 0;
  return n * (3 * ps + ps) - ps;
}

// Draws a word on the pixel grid. Returns its width. Height is always 5*ps.
function drawLetterString(fb, fbW, fbH, x, y,
                     str, ps, color) {
  let cx = x;
  for (let p = str; p[0]; p = ptrAdd(p, 1)) {
    let rows = letter3x5(p[0]);
    if (rows) {
      for (let r = 0; r < 5; r++)
        for (let c = 0; c < 3; c++)
          if (rows[r] & (1 << c))
            fbRect(fb, fbW, fbH, cx + c * ps, y + r * ps, ps, ps, color);
    }
    cx += 3 * ps + ps;          // glyph + one-unit gap, same pitch as digits
  }
  return cx - x - ps;
}

