// ==================== LOGGING ====================
// Goes to the USB Serial Monitor AND to the browser console via the bridge
function pxlog(msg) {
  Serial.println("[OS] " + msg);
  if (bridgeKnown && WiFi.status() == WL_CONNECTED) {
    let out = "LOG:" + msg;
    udp.beginPacket(clone(bridgeIP), PORT_FRAME);
    udp.write(cstr(out), out.length);
    udp.endPacket();
  }
}

// Once-a-second health report: CPU load, heap, PSRAM, loop rate.
// One tiny UDP packet per second - costs nothing measurable.
// sendStat(): a health report for the PC viewer; nothing to send it to here - the board part has it (RUNTIME 5).

// sendCtl(): tells the PC viewer the brightness; here the emulator sets it - the board part has it (RUNTIME 5).

// ==================== DRAWING PRIMITIVES ====================
function fbRect(fb, fbW, fbH, x, y, w, h, color) {
  if (w <= 0 || h <= 0) return;
  let x0 = x < 0 ? 0 : x;         let y0 = y < 0 ? 0 : y;
  let x1 = x + w > fbW ? fbW : x + w;
  let y1 = y + h > fbH ? fbH : y + h;
  for (let yy = y0; yy < y1; yy++) {
    let row = ptrAdd(fb, yy * fbW);
    for (let xx = x0; xx < x1; xx++) row[xx] = color;
  }
}

function fbOutline(fb, fbW, fbH, x, y, w, h, color) {
  fbRect(fb, fbW, fbH, x, y, w, 1, color);
  fbRect(fb, fbW, fbH, x, y + h - 1, w, 1, color);
  fbRect(fb, fbW, fbH, x, y, 1, h, color);
  fbRect(fb, fbW, fbH, x + w - 1, y, 1, h, color);
}

function fbCircle(fb, fbW, fbH, cx, cy, r, color) {
  for (let yy = -r; yy <= r; yy++)
    for (let xx = -r; xx <= r; xx++)
      if (xx*xx + yy*yy <= r*r) {
        let px = cx + xx, py = cy + yy;
        if (px >= 0 && px < fbW && py >= 0 && py < fbH) fb[py * fbW + px] = color;
      }
}

// Copies a decoded image onto the screen, centred. Uses memcpy per ROW instead
// of a per-pixel loop with bounds checks - same result, a fraction of the work,
// and it runs 5x a second during camera preview so it matters.
function blitImage(fb, img, w, h, areaH, swapBytes) {
  if (!img || w <= 0 || h <= 0) return;
  let x0 = Math.trunc((IN_W - w) / 2); if (x0 < 0) x0 = 0;
  let y0 = Math.trunc((areaH - h) / 2); if (y0 < 0) y0 = 0;
  let copyW = (x0 + w > IN_W) ? IN_W - x0 : w;
  for (let y = 0; y < h; y++) {
    let dy = y0 + y;
    if (dy < 0 || dy >= areaH) continue;
    let src = ptrAdd(img, y * w);
    let dst = ptrAdd(ptrAdd(fb, dy * IN_W), x0);
    if (!swapBytes) {
      memcpy(dst, src, u32(Math.imul(u32(copyW), 2)));          // bulk copy, the fast path
    } else {
      for (let x = 0; x < copyW; x++) dst[x] = u16(((src[x] >> 8) | (src[x] << 8)));
    }
  }
}

// Text: 5x7 font, scaled. Like the old canvas fillText, y is the text BASELINE.
// Width of a 5x7-font string without drawing it (for centring).
// ==================== UTF-8 -> ASCII FOLDING ====================
//
// The 5x7 font is ASCII 32-126 only, and the sketch's source is UTF-8, so a
// Hungarian "a" arrives as TWO bytes (0xC3 0xA1) and the old byte-walking loop
// turned it into two '?'. That is what you were seeing.
//
// Accents are STRIPPED rather than drawn: a -> a, o -> o, u -> u. At 0.152mm
// per pixel an accent mark is a single dot, and o / o / o would be impossible
// to tell apart anyway, so the bare letter is the honest choice.
//
// Returns one folded character and advances *p past however many bytes it used,
// so measure and draw always agree on the character count by construction.
function nextFoldedChar(p) {
  let c = p[0][0];
  if (c == 0) return 0;
  if (c < 0x80) { (p[0]) = ptrAdd((p[0]), 1); return c; }

  let len = (c >= 0xF0) ? 4 : (c >= 0xE0) ? 3 : (c >= 0xC0) ? 2 : 1;
  for (let i = 1; i < len; i++) {           // never run off a truncated string
    if ((ptrAdd(p[0], i))[0] == 0) { len = i; break; }
  }
  let c2 = u8((len >= 2) ? (ptrAdd(p[0], 1))[0] : 0);
  p[0] = ptrAdd(p[0], len);

  if (len == 2 && c == 0xC3) {              // Latin-1 supplement
    switch (c2) {
      case 0xA0: case 0xA1: case 0xA2: case 0xA3: case 0xA4: case 0xA5: return ch('a');
      case 0x80: case 0x81: case 0x82: case 0x83: case 0x84: case 0x85: return ch('A');
      case 0xA8: case 0xA9: case 0xAA: case 0xAB:                       return ch('e');
      case 0x88: case 0x89: case 0x8A: case 0x8B:                       return ch('E');
      case 0xAC: case 0xAD: case 0xAE: case 0xAF:                       return ch('i');
      case 0x8C: case 0x8D: case 0x8E: case 0x8F:                       return ch('I');
      case 0xB2: case 0xB3: case 0xB4: case 0xB5: case 0xB6: case 0xB8: return ch('o');
      case 0x92: case 0x93: case 0x94: case 0x95: case 0x96: case 0x98: return ch('O');
      case 0xB9: case 0xBA: case 0xBB: case 0xBC:                       return ch('u');
      case 0x99: case 0x9A: case 0x9B: case 0x9C:                       return ch('U');
      case 0xBD: case 0xBF: return ch('y');   case 0x9D: return ch('Y');
      case 0xB1: return ch('n');              case 0x91: return ch('N');
      case 0xA7: return ch('c');              case 0x87: return ch('C');
      case 0x9F: return ch('s');              // sharp s
      default:   return ch('?');
    }
  }
  if (len == 2 && c == 0xC5) {              // Latin Extended-A: o and u double acute
    switch (c2) {
      case 0x90: return ch('O');   case 0x91: return ch('o');
      case 0xB0: return ch('U');   case 0xB1: return ch('u');
      case 0x9A: case 0x9C: case 0x9E: return ch('S');
      case 0x9B: case 0x9D: case 0x9F: return ch('s');
      case 0xB9: case 0xBB: case 0xBD: return ch('Z');
      case 0xBA: case 0xBC: case 0xBE: return ch('z');
      default:   return ch('?');
    }
  }
  if (len == 2 && c == 0xC4) {              // c-caron, e-ogonek, g-breve etc.
    switch (c2) {
      case 0x8C: case 0x86: return ch('C');   case 0x8D: case 0x87: return ch('c');
      case 0x98: return ch('E');              case 0x99: return ch('e');
      case 0x9E: return ch('G');              case 0x9F: return ch('g');
      case 0xB0: return ch('I');              case 0xB1: return ch('i');
      case 0xB9: case 0xBB: return ch('L');   case 0xBA: case 0xBC: return ch('l');
      case 0x84: return ch('A');              case 0x85: return ch('a');
      default:   return ch('?');
    }
  }
  return ch('?');
}

function measureTextStrW(text, sizePx) {
  let scale = Math.trunc((sizePx + 4) / 8); if (scale < 1) scale = 1;
  let n = 0;
  let p = text;
  while (p[0]) { nextFoldedChar(ref(() => p, v => p = v)); n++; }   // counts CHARACTERS, not bytes
  if (n == 0) return 0;
  return n * 6 * scale - scale;      // last inter-letter gap doesn't count
}

// Set to 0 for release. Costs nothing when off - the compiler deletes it all.
const PXP_TEXT_WARN = 1;

// Set by drawTextFitCentered() around its scrolling text, which runs past the
// edges ON PURPOSE. Its x moves every frame, so every frame looked like a new
// overflow and the log filled with [FIT] lines (5.1, 8 Nov).
let fitCheckOff = false;

let drawTextStr__seen = new Uint32Array(48);
let drawTextStr__seenN = 0;
function drawTextStr(fb, fbW, fbH, x, y, text, sizePx, color) {
  let scale = Math.trunc((sizePx + 4) / 8); if (scale < 1) scale = 1;

// #if PXP_TEXT_WARN
  // Overflow check. It lives HERE, not in a script, because 48 of the 120
  // drawTextStr() calls pass a variable rather than a literal - names, snprintf
  // results, IP addresses. No static scanner can see 40% of the text this OS
  // draws. This sees all of it, including strings that do not exist until the
  // moment they are drawn.
  //
  // Each distinct string logs ONCE per boot, tracked by hash. A plain rate
  // limit would not work: the first offender in draw order would win every
  // frame and hide every other one on the same screen.
  {
    let wNeeded = measureTextStrW(text, sizePx);
    let overflows = !fitCheckOff && (x < 0 || x + wNeeded > fbW);

    if (overflows) {
      let h = 2166136261;                 // FNV-1a over the text
      for (let q = text; q[0]; q = ptrAdd(q, 1)) { h = u32(h ^ q[0]); h = u32(Math.imul(h, 16777619)); }
      h = u32(h ^ (u32((x * 131 + fbW))));           // same string, different x = worth seeing
      /* static: drawTextStr__seen */
      /* static: drawTextStr__seenN */
      const seenMax = i32((Math.trunc(192 /*sizeof(seen)*/ / 4 /*sizeof(seen[0])*/)));
      let known = false;
      for (let i = 0; i < drawTextStr__seenN; i++) if (drawTextStr__seen[i] == h) { known = true; break; }
      // Once the table is full it stays quiet. It used to go on logging every
      // new one it could no longer remember - so, every frame.
      if (!known && drawTextStr__seenN < seenMax) {
        drawTextStr__seen[drawTextStr__seenN++] = h;
        let l = new Uint8Array(128);
        snprintf(l, l.length, S("[FIT] %dpx at x=%d on %dpx (size %d): '%s'"),
                 wNeeded, x, fbW, sizePx, text);
        pxlog(jstr(l));
        if (drawTextStr__seenN == seenMax) pxlog("[FIT] 48 different overflows logged - no more this boot");
      }
    }

    // The visual half of the same check. debugMode used to outline only the
    // pixel-DIGIT font - three call sites, covering the clock numerals and the
    // battery figure - and never a single drawTextStr, which is 120 call sites
    // and where every overflow this OS has ever had actually lived.
    //
    // GREEN = fits, RED = running off the edge. The log tells you WHAT; this
    // tells you WHERE, without reading anything.
    if (debugMode) {
      fbOutline(fb, fbW, fbH, x, y - 7 * scale, wNeeded, 7 * scale,
                overflows ? COL_RED : COL_FIT_OK);
    }
  }
// #endif

  let top = y - 7 * scale;
  let cx = x;
  let p = text;
  while (p[0]) {
    let c = nextFoldedChar(ref(() => p, v => p = v));
    if (c < 32 || c > 126) c = ch('?');
    let glyph = FONT5x7[c - 32];
    for (let col = 0; col < 5; col++) {
      let bits = glyph[col];
      for (let row = 0; row < 7; row++)
        if (bits & (1 << row))
          fbRect(fb, fbW, fbH, cx + col * scale, top + row * scale, scale, scale, color);
    }
    cx += 6 * scale; // 5 columns + 1 gap
  }
}

// ---- 5x7 icons that are not characters ----
// Same data format as FONT5x7: one byte per column, bit 0 = top row. These are
// shapes, not text, so they cannot live in the font table - the call log needs
// arrows and the font only covers printable ASCII 32..126.
//
// The painting loop below is copied from drawTextStr() rather than shared with
// it. drawTextStr() runs for every string on every frame and every screen
// depends on it; eight duplicated lines are cheaper than the risk of touching
// it, and the font's data format is fixed so the copy cannot drift.
//
// All four share a vertical centre on row 3, which is why the arrows are drawn
// as 5x3 in rows 2-4 and the X as 5x5 in rows 1-5. Plain '^' and 'v' from the
// font could not be used: '^' is 3 rows anchored at the top and 'v' is 5 rows
// anchored at the bottom, so as a pair they never line up.
const ICON_CALL_OUT = new Uint8Array([0x10,0x08,0x04,0x08,0x10]);  // arrow up
const ICON_CALL_IN = new Uint8Array([0x04,0x08,0x10,0x08,0x04]);  // arrow down
const ICON_CALL_MISSED = new Uint8Array([0x1C,0x0C,0x14,0x10,0x0C]);  // bounce: came in, deflected away
const ICON_CALL_REJECT = new Uint8Array([0x22,0x14,0x08,0x14,0x22]);  // X
// Factory reset's "Done". A 1px stroke like the font's own: short arm down to
// the vertex on row 5, long arm up to row 2. Drawn alone at scale 8, so it does
// not need the shared row-3 centre the call log icons keep.
const ICON_CHECK = new Uint8Array([0x10,0x20,0x10,0x08,0x04]);

function drawGlyph5x7(fb, fbW, fbH, x, y,
                  cols, sizePx, color) {
  let scale = Math.trunc((sizePx + 4) / 8); if (scale < 1) scale = 1;
  let top = y - 7 * scale;
  for (let col = 0; col < 5; col++) {
    let bits = cols[col];
    for (let row = 0; row < 7; row++)
      if (bits & (1 << row))
        fbRect(fb, fbW, fbH, x + col * scale, top + row * scale, scale, scale, color);
  }
}

// Shorten `src` so it fits maxPx at sizePx, ending on a WORD boundary with an
// ellipsis. Cutting mid-word ("Nem fogadott hi...") reads as broken; stopping
// at a space ("Nem fogadott...") reads as deliberate. Falls back to a hard cut
// only when the very first word is itself too wide.
function truncateToFit(dst, dstLen, src, maxPx, sizePx) {
  strncpy(dst, src, u32(dstLen - 1)); dst[dstLen - 1] = 0;
  if (measureTextStrW(dst, sizePx) <= maxPx) return;

  let ell = S("...");
  // + one letter-gap: the "..." sits a gap after the kept text, and
  // measureTextStrW() counts the gap at neither end. Without it the result
  // could come out 2px (at size 15) wider than maxPx.
  let scale = Math.trunc((sizePx + 4) / 8); if (scale < 1) scale = 1;
  let ellW = measureTextStrW(ell, sizePx) + scale;
  let budget = maxPx - ellW;
  if (budget < 0) budget = 0;

  let cut = 0, lastSpace = -1;
  for (let i = 0; dst[i]; i++) {
    let save = dst[i + 1]; dst[i + 1] = 0;
    let w = measureTextStrW(dst, sizePx);
    dst[i + 1] = save;
    if (w > budget) {
      // The letter that did not fit is a SPACE: the whole word before it did
      // fit, so the cut lands right here. Missing this went back one word too
      // far - "yeah,..." where "yeah, soldering..." fits.
      if (dst[i] == ch(' ')) lastSpace = i;
      break;
    }
    cut = i + 1;
    if (dst[i] == ch(' ')) lastSpace = i;
  }
  if (lastSpace > 0) cut = lastSpace;      // prefer the word boundary
  if (u32(cut) > u32(dstLen - 4)) cut = i32(dstLen) - 4;
  dst[cut] = 0;
  strcat(dst, ell);
}

// How long ago, in words. Used by the message list and the call log.
//
// The old inline version only ever printed HH:MM, with a comment claiming the
// device "doesn't track yesterday without a real calendar day comparison". It
// does - localtime_r() and a real epoch are both right here. Comparing
// CALENDAR DAYS rather than elapsed seconds is the bit that matters: a message
// at 23:50 is "Yesterday" at 00:10, not "22 minutes ago".
//
// Widest output is "Yesterday" at 106px (scale 2), so every case fits.
const relativeTimeStr__DAYSHORT = [S("Sun"),S("Mon"),S("Tue"),S("Wed"),S("Thu"),S("Fri"),S("Sat")];
const relativeTimeStr__MONSHORT = [S("Jan"),S("Feb"),S("Mar"),S("Apr"),S("May"),S("Jun"),
                                     S("Jul"),S("Aug"),S("Sep"),S("Oct"),S("Nov"),S("Dec")];
function relativeTimeStr(out, outLen, epoch) {
  out[0] = 0;
  if (epoch == 0) return;

  let then = epoch, now = time(null);
  let t = new tm(), n = new tm();
  localtime_r(ref(() => then, v => then = v, 'i64'), t);
  localtime_r(ref(() => now, v => now = v, 'i64'),  n);
  if (now <= 0) {                       // clock never synced - all we can trust
    snprintf(out, outLen, S("%02d:%02d"), t.tm_hour, t.tm_min);
    return;
  }

  // days between the two CALENDAR dates, not elapsed/86400
  let td = clone(t), nd = clone(n);
  td.tm_hour = td.tm_min = td.tm_sec = 0;
  nd.tm_hour = nd.tm_min = nd.tm_sec = 0;
  let dayDiff = (Math.trunc((mktime(nd) - mktime(td)) / 86400));

  /* static: relativeTimeStr__DAYSHORT */
  /* static: relativeTimeStr__MONSHORT */
  if (dayDiff <= 0)      snprintf(out, outLen, S("%02d:%02d"), t.tm_hour, t.tm_min);
  else if (dayDiff == 1) snprintf(out, outLen, S("Yesterday"));
  else if (dayDiff < 7)  snprintf(out, outLen, S("%s"), relativeTimeStr__DAYSHORT[t.tm_wday]);
  else if (t.tm_year == n.tm_year)
                         snprintf(out, outLen, S("%s %d"), relativeTimeStr__MONSHORT[t.tm_mon], t.tm_mday);
  else                   snprintf(out, outLen, S("%d/%d/%02d"),
                                  t.tm_mon + 1, t.tm_mday, (t.tm_year + 1900) % 100);
}

// ==================== TEXT WRAPPING ====================
// One place that knows how to break a string into lines. It used to be inline
// in the chat view with a hardcoded "7 pixels per character", which is why long
// messages ran off the edge - font 13 is twelve pixels per character.
//
// THREE TIERS of break opportunity, the same order browsers use:
//   1. spaces            - always preferred
//   2. after punctuation - / . - ? & = _ : ,   the meaningful seams inside a
//                          URL or a hyphenated word. Break AFTER the separator
//                          so a line never STARTS with stray punctuation.
//   3. anywhere          - LAST RESORT, only when a single run is wider than a
//                          whole line and there is genuinely nothing else to do
//
// Tier 3 never touches ordinary prose. "www.telekom.hu/lakossagi" comes out as
// "www.telekom." / "hu/lakossagi" purely from tier 2.
const CHAT_LINE_LEN = 48;

const CHAT_MAX_LINES = 24;  // a 160-char SMS is ~20 lines at 12 chars/line,
                               // and MSG_BODY_LEN caps bodies at 160, so this
                               // cannot truncate a real message

function isBreakAfter(c) {
  return c == ch('/') || c == ch('.') || c == ch('-') || c == ch('?') || c == ch('&') ||
         c == ch('=') || c == ch('_') || c == ch(':') || c == ch(',');
}

// Returns the line count. Pass out = NULL to count without storing - that is
// how the layout pass measures a thread's height without building every line.
function wrapText(body, availPx, sizePx,
             out, maxLines) {
  let count = 0;
  let cur = new Uint8Array(48); let cl = 0; cur[0] = 0;

  // emit the current line and start a new one
  const WRAP_FLUSH = () => {          // (a #define in the C)
      if (cl > 0) {
        if (out && count < maxLines) {
          strncpy(out[count], cur, CHAT_LINE_LEN - 1);
          out[count][CHAT_LINE_LEN - 1] = 0;
        }
        count++; cl = 0; cur[0] = 0;
      }
    };

  // append a run to the current line, no fitting checks
  const WRAP_APPEND = (src, len) => {  // (a #define in the C)
      let n_ = (len);
      if (cl + n_ > CHAT_LINE_LEN - 1) n_ = CHAT_LINE_LEN - 1 - cl;
      if (n_ > 0) { memcpy(ptrAdd(cur, cl), (src), n_); cl += n_; cur[cl] = 0; }
    };

  // A word longer than the word buffer (47 letters - a long web address) used
  // to lose everything past its 47th letter: only 47 were copied, then the
  // whole word was skipped. Now the rest comes round as the next piece, glued
  // on with no space, and carries on the line where the last piece stopped.
  // Words up to 47 letters wrap exactly as before.
  let glued = false;              // the next piece carries on the same word
  let p = body;
  while (p[0] && count < maxLines) {
    while (p[0] == ch(' ')) p = ptrAdd(p, 1);
    if (!p[0]) break;

    let wl = 0; while (p[wl] && p[wl] != ch(' ')) wl++;
    let word = new Uint8Array(48);
    let wn = wl < CHAT_LINE_LEN - 1 ? wl : CHAT_LINE_LEN - 1;
    memcpy(word, p, u32(wn)); word[wn] = 0;
    p = ptrAdd(p, wn);                         // was p += wl
    let cont = glued;               // this piece carries on the one before it
    glued = (wn < wl);

    // tier 1: does it fit on the line we are building?
    let test = new Uint8Array(96);
    if (cl > 0) snprintf(test, test.length, cont ? S("%s%s") : S("%s %s"), cur, word);
    else        snprintf(test, test.length, S("%s"), word);
    if (measureTextStrW(test, sizePx) <= availPx) {
      if (cl > 0 && !cont) WRAP_APPEND(S(" "), 1);
      WRAP_APPEND(word, wn);
      continue;
    }

    // it does not fit here. On a line of its own?
    if (!cont && measureTextStrW(word, sizePx) <= availPx) {
      WRAP_FLUSH();
      WRAP_APPEND(word, wn);
      continue;
    }

    // tier 2: chop at separators, greedily. A carried-on piece does not start
    // a new line: it fills up the one its word is already on.
    if (!cont) WRAP_FLUSH();
    let seg = 0;
    for (let i = 0; i < wn && count < maxLines; i++) {
      let lastChar = (i == wn - 1);
      if (!isBreakAfter(word[i]) && !lastChar) continue;

      let segLen = i - seg + 1;
      let piece = new Uint8Array(48);
      let pn = segLen < CHAT_LINE_LEN - 1 ? segLen : CHAT_LINE_LEN - 1;
      memcpy(piece, ptrAdd(word, seg), u32(pn)); piece[pn] = 0;
      seg = i + 1;

      snprintf(test, test.length, S("%s%s"), cur, piece);
      if (measureTextStrW(test, sizePx) <= availPx) { WRAP_APPEND(piece, pn); continue; }

      WRAP_FLUSH();
      if (measureTextStrW(piece, sizePx) <= availPx) { WRAP_APPEND(piece, pn); continue; }

      // tier 3: this run is wider than a whole line. Split it character by
      // character - the only remaining option.
      for (let c = 0; c < pn && count < maxLines; c++) {
        let probe = new Uint8Array(48);
        let n_ = cl < CHAT_LINE_LEN - 2 ? cl : CHAT_LINE_LEN - 2;
        memcpy(probe, cur, u32(n_)); probe[n_] = piece[c]; probe[n_ + 1] = 0;
        if (measureTextStrW(probe, sizePx) > availPx && cl > 0) WRAP_FLUSH();
        WRAP_APPEND(ptrAdd(piece, c), 1);
      }
    }
  }
  WRAP_FLUSH();
  // #undef WRAP_FLUSH
  // #undef WRAP_APPEND
  return count;
}

// Word-wraps text to fit within maxW pixels at the given font size, drawing
// one line per row starting at (x,y) and stepping down lineH pixels per line.
// Same wrapping approach as the chat bubbles below, factored out so any
// screen can wrap a hint/status line instead of letting it run off-screen.
function drawTextWrapped(fb, fbW, fbH, x, y, maxW,
                      text, sizePx, color, lineH) {
  let cur = new Uint8Array(64); let cl = 0; cur[0] = 0;
  let p = text;
  let line = 0;
  while (p[0]) {
    let wlen = 0; while (p[wlen] && p[wlen] != ch(' ')) wlen++;
    let word = new Uint8Array(48); let wl = wlen < 47 ? wlen : 47;
    strncpy(word, p, u32(wl)); word[wl] = 0;

    let test = new Uint8Array(64);
    if (cl > 0) snprintf(test, test.length, S("%s %s"), cur, word);
    else        snprintf(test, test.length, S("%s"), word);

    if (measureTextStrW(test, sizePx) > maxW && cl > 0) {
      drawTextStr(fb, fbW, fbH, x, y + line * lineH, cur, sizePx, color);
      line++;
      snprintf(test, test.length, S("%s"), word);   // word starts the next line
    }
    strncpy(cur, test, u32(cur.length - 1)); cur[cur.length - 1] = 0;
    cl = i32(strlen(cur));

    p = ptrAdd(p, wlen); while (p[0] == ch(' ')) p = ptrAdd(p, 1);
  }
  if (cl > 0) drawTextStr(fb, fbW, fbH, x, y + line * lineH, cur, sizePx, color);
}

// ==================== LAYOUT + DIGIT DRAWING (port of the Layout system) ====================
// (struct Bounds is defined at the top of the file.)

function measureDigitStringW(str, ps) {
  let w = 0; let n = i32(strlen(str));
  for (let i = 0; i < n; i++) {
    let g = digitGlyph(str[i]);
    if (!g) continue;
    w += g.w * ps;
    if (i < n - 1) w += ps;
  }
  return w;
}

function centerX(screenW, elemW) { return Math.trunc((screenW - elemW) / 2); }
function alignRight(screenW, elemW, margin) { return screenW - elemW - margin; }

function drawPixelDigit(fb, fbW, fbH, x, y, digit, ps, color) {
  let g = digitGlyph(digit);
  let b = mk(Bounds, x, y);
  if (!g) return clone(b);
  for (let row = 0; row < 5; row++)
    for (let col = 0; col < g.w; col++)
      if (g.rows[row] & (1 << col))
        fbRect(fb, fbW, fbH, x + col * ps, y + row * ps, ps, ps, color);
  b.width = g.w * ps; b.height = 5 * ps;
  if (debugMode) fbOutline(fb, fbW, fbH, b.x, b.y, b.width, b.height, COL_FIT_OK);
  return clone(b);
}

function drawDigitString(fb, fbW, fbH, x, y, str, ps, color) {
  let startX = x, curX = x, maxH = 0;
  for (let p = str; p[0]; p = ptrAdd(p, 1)) {
    let g = drawPixelDigit(fb, fbW, fbH, curX, y, p[0], ps, color);
    curX += g.width + ps;
    if (g.height > maxH) maxH = g.height;
  }
  let total = mk(Bounds, startX, y, curX - startX - ps, maxH);
  if (debugMode) fbOutline(fb, fbW, fbH, total.x, total.y, total.width, total.height, COL_YEL);
  return clone(total);
}

// activeBars (0-4) lit in `color`; the rest stay grey. noSim greys ALL bars
// and draws a small X right after them.
function drawSignalBars(fb, fbW, fbH, x, y, ps, color, activeBars, noSim) {
  for (let bar = 0; bar < 4; bar++) {
    let barX = x + bar * (ps + ps);
    let barColor = (!noSim && bar < activeBars) ? color : COL_GRAY6;
    for (let row = 0; row < 5; row++)
      if (row >= 3 - bar)   // bar heights 2,3,4,5 — same shapes as the JS tables
        fbRect(fb, fbW, fbH, barX, y + row * ps, ps, ps, barColor);
  }
  let barsW = 4 * ps + 3 * ps;
  if (noSim) {
    let xx = x + barsW + ps;
    let xs = ps > 1 ? ps - 1 : 1;
    for (let i = 0; i < 5; i++) {
      fbRect(fb, fbW, fbH, xx + i * xs,       y + i * xs, xs, xs, COL_RED);
      fbRect(fb, fbW, fbH, xx + (4 - i) * xs, y + i * xs, xs, xs, COL_RED);
    }
  }
  let b = mk(Bounds, x, y, barsW + (noSim ? ps * 6 : 0), 5 * ps);
  if (debugMode) fbOutline(fb, fbW, fbH, b.x, b.y, b.width, b.height, COL_BLUE);
  return clone(b);
}

// Rough CSQ (0-31) -> bar count. 99/0/negative = unknown, shown as 0 bars.
function csqToBars(csq) {
  if (csq <= 0 || csq >= 99) return 0;
  if (csq < 10) return 1;
  if (csq < 15) return 2;
  if (csq < 20) return 3;
  return 4;
}

// ---- Status bar icons ----
// Same data format as ICON_CALL_* and FONT5x7: one byte per column, bit 0 = the
// top row. Drawn at size 16, which is scale 2 = 10x14 real pixels.
const ICON_WIFI = new Uint8Array([0x02,0x0A,0x2A,0x0A,0x02]);  // dot, then widening arcs above it
const ICON_VIBRATE = new Uint8Array([0x14,0x2A,0x00,0x14,0x2A]);  // two buzz patterns, empty centre column
const ICON_SILENT = new Uint8Array([0x04,0x14,0x10,0x34,0x04]);  // eyes, mouth, and a drip off the right corner
const ICON_ALARM = new Uint8Array([0x10,0x1E,0x3E,0x1E,0x10]);  // a bell: flat top, wide rim, the clapper under it
const ICON_MUSIC = new Uint8Array([0x30,0x3E,0x02,0x30,0x3E]);  // two notes on a beam: a song is loaded (Music, 11 Nov)

// Owned by pptransfer. True only while its access point is up and accepting
// joins, false the instant it comes down - including on the 5-minute no-joiner
// timeout and on every one of the three exits.
//
// Deliberately NOT WiFi.status(). The phone's own wifi connection is not news:
// it would light this icon for hours at a stretch and the user would learn to
// stop seeing it, which is exactly how a status bar goes dead. Tied to
// pptransfer it means one specific thing - OTHER DEVICES CAN JOIN ME RIGHT NOW
// - which is a state worth catching at a glance and, more to the point, worth
// noticing you left running.
//
// Set by ppStart() and cleared by ppStop() (11 Nov) - every way pptransfer
// ends goes through ppStop().
let ppTransferJoinable = false;

// Decides WHICH icons are showing and packs them. Shared by both status bars so
// the two can never drift apart on what a state means - only on how big it is
// drawn, which is what the size arguments are for. Returns the x it got to.
//
// Nothing here owns a fixed x. Icons come and go with the state they report, so
// each one showing takes the next free slot; the ORDER is fixed even though the
// positions are not, so WiFi is always left of the ringer icon and the two never
// swap. The alternative - fixed slots, each icon owning an x forever with a gap
// when absent - would make a lone icon identifiable by position alone, which
// packing cannot do. To switch, compute x from the loop index instead of
// stepping it at the bottom.
//
// Only exceptional states draw anything. Audible shows nothing, which is why the
// bar is bare most of the time. Vibrate and silent can never both appear:
// ringVolume is a single number, so the else-if is the whole guarantee.
function drawStatusIcons(fb, fbW, fbH, x, baseY,
                    sizePx, iconW, gap, limitX) {
  const icons = new Array(5).fill(null);
  let n = 0;
  if (ppTransferJoinable)              icons[n++] = ICON_WIFI;
  if (alarmsAnyOn())                   icons[n++] = ICON_ALARM;   // an alarm is set (8 Nov)
  if (musicLoaded())                   icons[n++] = ICON_MUSIC;   // a song is loaded, playing or paused (11 Nov)
  if      (settings.ringVolume == 0)   icons[n++] = ICON_VIBRATE;
  else if (settings.ringVolume <  0)   icons[n++] = ICON_SILENT;

  for (let i = 0; i < n; i++) {
    // Never draw into the battery figure. If a bar ever gets crowded enough for
    // this to fire, the icon is dropped rather than overlapped - the same thing
    // truncateToFit() does to text: stop cleanly, do not smear.
    if (x + iconW > limitX) break;
    drawGlyph5x7(fb, fbW, fbH, x, baseY, icons[i], sizePx, COL_THEME);
    x += iconW + gap;
  }
  return x;
}

function drawStatus(fb, screenW) {
  fbRect(fb, screenW, IN_H, 0, 0, screenW, 36, COL_BAR);

  let bars = (simReady && networkRegistered()) ? csqToBars(modemSignalCSQ) : 0;
  let sb = drawSignalBars(fb, screenW, IN_H, 10, 8, 4, COL_THEME, bars, !simReady);

  let bstr = new Uint8Array(8); snprintf(bstr, bstr.length, S("%d%%"), getBatteryPercent());
  let bw = measureDigitStringW(bstr, 4);
  let batX = alignRight(screenW, bw, 10);
  drawDigitString(fb, screenW, IN_H, batX, 8, bstr, 4, COL_THEME);

  // ---- Icons ----
  // Sized to match the battery figure, which is 5 pixel-digit rows at ps=4 =
  // 20px tall. These glyphs light rows 1..5, so scale 4 gives the same 20px of
  // ink and the two read as equals. Scale 2 was 10px of ink against the
  // battery's 20 and looked like a footnote beside it. Compare ink to ink.
  //
  // First slot is taken from the Bounds the signal bars returned, so the no-SIM
  // cross pushes the icons right on its own without anyone computing its width.
  drawStatusIcons(fb, screenW, IN_H,
                  sb.x + sb.width + 8,   // x
                  32,                    // baseline: 28px box centred in a 36px bar, top=4
                  28,                    // -> scale 4 -> 20 wide, 28 tall
                  20, 8,                 // icon width, gap
                  batX - 6);             // stop short of the battery
}

// ==================== CLOCK ====================
function nowTime(t) {
  if (!getLocalTime(t, 10)) {          // before first NTP sync, show zeros
    memset(t, 0, 44 /*sizeof struct tm*/);
  }
}

// ==================== DIALER LOGIC ====================
// Ported from your emulator's dialer. JS timers become millis() deadlines.

function startDialerBlink() {
  dialerCursorVisible = true;
  dialerBlinkNext = u32(millis() + 1000);
  dialerUnhideAt = 0;
  renderInner();
}

// After any input: hide the cursor for 250ms, then resume the 1s blink.
function resetDialerBlink() {
  dialerCursorVisible = false;
  dialerBlinkNext = 0;
  dialerUnhideAt = u32(millis() + 250);
  renderInner();
}

function enterDialer() {
  state = ST_DIALER;
  dialerLen = 0;
  dialerCursor = 0;
  dialerDigits[0] = 0;
  dialerExitAt = 0;
  dialerStarTime = 0;
  startDialerBlink();
  pxlog("Dialer opened");
}

function exitDialer() {
  dialerBlinkNext = 0;
  dialerUnhideAt = 0;
  dialerExitAt = 0;
  state = ST_HOME;
  renderInner();
  pxlog("Dialer closed");
}

// A call typed into the dialer, from the green key, OK, or Options > Call.
// When it ends the phone goes to the home screen with the number cleared - the
// digits have done their job (the owner, 8 Nov). If the call cannot start (no
// network, or the modem refuses it) nothing changes and the digits stay, so it
// can be tried again.
function dialerCall() {
  if (dialerLen <= 0) return;
  if (!callDial(dialerDigits)) return;
  preCallState = ST_HOME;
  dialerLen = 0; dialerCursor = 0; dialerDigits[0] = 0;
  dialerBlinkNext = 0; dialerUnhideAt = 0; dialerExitAt = 0;
}

function insertDialerDigit(c) {
  if (dialerLen >= DIALER_MAX) return;
  for (let i = dialerLen; i > dialerCursor; i--) dialerDigits[i] = dialerDigits[i - 1];
  dialerDigits[dialerCursor] = c;
  dialerLen++;
  dialerCursor++;
  dialerDigits[dialerLen] = 0;
  dialerExitAt = 0;
  resetDialerBlink();
}

function deleteDialerDigit() {
  if (dialerCursor > 0) {
    for (let i = dialerCursor - 1; i < dialerLen - 1; i++) dialerDigits[i] = dialerDigits[i + 1];
    dialerLen--;
    dialerCursor--;
    dialerDigits[dialerLen] = 0;
    resetDialerBlink();
  }
  if (dialerLen == 0) dialerExitAt = u32(millis() + 500);   // empty -> leave shortly
}

function dialerUnit() { return dialerLen >= 14 ? DIGIT_MEDIUM : DIGIT_LARGE; }
function dialerPerLine() { return dialerUnit() == DIGIT_LARGE ? 7 : 13; }

function moveDialerCursor(dir) {
  let per = dialerPerLine();
  if      (!strcmp(dir,S("LEFT"))  && dialerCursor > 0)                    { dialerCursor--;      resetDialerBlink(); }
  else if (!strcmp(dir,S("RIGHT")) && dialerCursor < dialerLen)            { dialerCursor++;      resetDialerBlink(); }
  else if (!strcmp(dir,S("UP"))    && dialerCursor >= per)                 { dialerCursor -= per; resetDialerBlink(); }
  else if (!strcmp(dir,S("DOWN"))  && dialerCursor + per <= dialerLen)     { dialerCursor += per; resetDialerBlink(); }
}

// ==================== STORAGE LAYER ====================
// One place that knows how to read and write things. Contacts, Messages and
// Call logs will all go through here rather than each inventing its own way.
//
// Files live on LittleFS in flash. LittleFS is used instead of FAT because the
// battery is removable: it's designed to survive losing power mid-write.

let PATH_SETTINGS = S("/settings.dat");
let PATH_CONTACTS = S("/contacts.dat");
let PATH_MESSAGES = S("/messages.dat");
let PATH_CALLLOG = S("/calllog.dat");
let PATH_NOTES = S("/notes.dat");
let PATH_CALENDAR = S("/calendar.dat");
let PATH_ALARMS = S("/alarms.dat");
let PATH_TUNES = S("/tunes.dat");      // your own ringtones (12 Nov)
let PATH_GAMES = S("/games.dat");      // the games' records and choices (12 Nov)
// (fsReady, settings, contacts and contactCount are declared at the top of the file)

// Puts a finished temp file in place of path (11 Nov). Renamed straight over
// the old file: littlefs replaces it in one step, so a power cut leaves the old
// file or the new one, never neither - the way Notes, the Calendar and Alarms
// already save. Removing the old file first - what this used to do - left a
// moment with no file at all; that stays only as the fallback, and
// fileTakeBackTemp() picks up a temp file a cut in that moment left alone.
function fileReplace(tmp, path) {
  if (LittleFS.rename(tmp, path)) return true;
  LittleFS.remove(path);
  return LittleFS.rename(tmp, path);
}

// Every loader asks this first (11 Nov). Only the temp file there: a save was
// cut off between removing the old file and renaming the new one (the fallback
// above, or a save made the old way). The old file is only ever removed once
// the temp is written and checked, so the temp is the newer save: it goes in
// place. Both there: a save was cut off before its rename - the old file
// stands, and the temp (maybe half written) goes.
function fileTakeBackTemp(path) {
  if (!fsReady) return;
  let tmp = jstr(path) + ".tmp";
  if (!LittleFS.exists(tmp)) return;
  if (LittleFS.exists(path)) { LittleFS.remove(tmp); return; }
  LittleFS.rename(tmp, jstr(path));
  pxlog("FS: put back the last save of " + jstr(path) + " from its temp file");
}

// Write via a temp file then rename, so a power cut can't leave a half-written
// file where the real one used to be. A cut leaves the old version or the new
// one, never neither (fileReplace(), 11 Nov).
function saveFileAtomic(path, data, len) {
  if (!fsReady) return false;
  let tmp = jstr(path) + ".tmp";
  let f = LittleFS.open(tmp, S("w"));
  if (!f.valid()) { pxlog("FS: cannot open temp file"); return false; }
  let written = f.write(data, len);
  f.close();
  if (written != len) { LittleFS.remove(tmp); pxlog("FS: short write"); return false; }
  if (!fileReplace(cstr(tmp), path)) { pxlog("FS: rename failed"); return false; }
  return true;
}

function loadFile(path, buf, maxLen) {
  fileTakeBackTemp(path);     // a save cut off half way (11 Nov)
  if (!fsReady || !LittleFS.exists(path)) return 0;
  let f = LittleFS.open(path, S("r"));
  if (!f.valid()) return 0;
  let n = f.read(buf, maxLen);
  f.close();
  return n;
}

// ---- settings ----
function settingsDefaults() {
  settings.magic     = SETTINGS_MAGIC;
  settings.version   = SETTINGS_VERSION;
  settings.bootCount = 0;
  settings.debugMode = 0;
  settings.textToneIx = 0;          // the text tone
  settings.activeRingtoneIx = 0;
  settings.ringVolume = 6;
  settings.themeIx = 3;        // 3 = TERMINAL, matching SmartClock's default accent
  settings.customR = 0x00;     // Custom starts on the OS's original pure green, so
  settings.customG = 0xFF;     // the first visit to the editor shows something sane
  settings.customB = 0x00;
  settings.keyTones      = KT_DEFAULT_LEVEL;   // keypad tones on, low (11 Nov)
  settings.vibrateOnRing = 0;
  settings.brightness    = 80;
  settings.keyTonesWhere = 0;    // everywhere
  settings.dimAfterS     = 15;   // was not configurable at all before
  settings.sleepAfterS   = 30;   // matches the 30000ms literal it replaces
  settings.autoTime      = 1;
  settings.alarmToneIx   = 0;    // Casio (9 Nov)
  settings.musicVolume   = MUSIC_VOL_DEFAULT;   // Music (11 Nov)
  settings.musicFlags    = 0;    // Shuffle off, Repeat off
}

function settingsSave() {
  return saveFileAtomic(PATH_SETTINGS, settings, 32 /*sizeof(settings)*/);
}

function settingsLoad() {
  let n = loadFile(PATH_SETTINGS, settings, 32 /*sizeof(settings)*/);
  if (n != 32 /*sizeof(settings)*/ || settings.magic != SETTINGS_MAGIC
      || settings.version != SETTINGS_VERSION) {
    pxlog("Settings: fresh start");
    settingsDefaults();
  }
}

// ==================== THEME ====================
// Names and hexes are SmartClock's, taken verbatim so that a theme means the
// same colour on both devices. That only holds if nobody "improves" a hex here
// - see the BLE sync note in §4 of the register.
//
// These are NOT the same list as the per-contact palette even though they look
// like it. A contact colour is only ever text on black, so a dim one is just
// dim. A theme colour is ALSO the fill behind the selected row in every list,
// with text drawn on top - so it has to survive both jobs.
//
// darkInk says which colour that text is. Every entry is currently true (black)
// by DECISION, not by measurement: by contrast ratio CRIMSON, TERMINAL, OCEAN
// and ARCANE would all read better with white, and they are staying black until
// someone looks at them on glass and disagrees. Flipping one is one word.
// Measured contrast, against black / against white:
//
//   CRIMSON   3.6 / 5.9        TERMINAL  4.1 / 5.1
//   EMBER     7.2 / 2.9        OCEAN     3.7 / 5.6
//   GOLD     13.9 / 1.5        ARCANE    4.3 / 4.9
//
// ⚠️ TERMINAL is the default and is HALF the luminance of the pure green this
// OS was designed in, so everything is dimmer than it used to be. That is a
// deliberate trade for matching SmartClock. Reverting is one digit in
// settingsDefaults().
//
// WHITE and RED were rejected as themes earlier for colliding with colours that
// already carry meaning - white is the screen-title colour at 28 sites, red is
// the warning colour at 27. CRIMSON is a dark red rather than pure red, which
// is why it is allowed where RED was not, but it does sit close to the missed
// call and error colour and is worth a look on glass.
class Theme {
  constructor() {
    this.name = null;
    this.r = 0;
    this.g = 0;
    this.b = 0;
    this.darkInk = false;
  }
}
Theme.$f = [['name', 'ptr', 0], ['r', 'u8', 4], ['g', 'u8', 5], ['b', 'u8', 6], ['darkInk', 'bool', 7]];
Theme.$size = 8;

const THEMES = [
  mk(Theme,  S("CRIMSON"),  0xCC, 0x00, 0x00, true ),
  mk(Theme,  S("EMBER"),    0xFF, 0x66, 0x00, true ),
  mk(Theme,  S("GOLD"),     0xFF, 0xCC, 0x00, true ),
  mk(Theme,  S("TERMINAL"), 0x00, 0x80, 0x00, true ),   // <- default
  mk(Theme,  S("OCEAN"),    0x00, 0x55, 0xFF, true ),
  mk(Theme,  S("ARCANE"),   0xB0, 0x41, 0xB7, true ),
];
const THEME_COUNT = 6;

// Picks readable ink for an ARBITRARY colour - which the table above cannot do
// for a colour the user invents at runtime with the RGB sliders. WCAG: black
// beats white exactly when linear relative luminance is at or above 0.179.
// Only ever runs on a keypress, never per frame, so the powf() calls are free.
function srgbLin(c) {
  let f = f32(f32(c) / 255.0);
  return (f <= f32(0.03928)) ? (f32(f / f32(12.92))) : powf(f32((f32(f + f32(0.055))) / f32(1.055)), f32(2.4));
}
function darkInkFor(r, g, b) {
  return (f32(f32(f32(f32(0.2126) * srgbLin(r)) + f32(f32(0.7152) * srgbLin(g))) + f32(f32(0.0722) * srgbLin(b)))) >= f32(0.179);
}

// Custom is a seventh ROW but not a seventh table entry - its colour lives in
// settings, not in THEMES[], because the user can change it.
const THEME_CUSTOM = THEME_COUNT;       // 6: the row after the presets
const THEME_ROWS = THEME_COUNT + 1;   // 7 rows in the picker

// One step per press. The panel is RGB565, so red and blue have only 32 real
// levels and a step under 8 would change the number on screen without changing
// a single pixel. Green has 64, but one step for all three keeps the meters
// reading the same length, which matters more here than the extra precision.
const RGB_STEP = 8;

// Sets BOTH colours together and records the choice. Deliberately does not
// save: the caller decides whether this is a live preview or a commitment.
function themeApply(ix) {
  if (ix < 0 || ix > THEME_CUSTOM) ix = 0;
  let r = 0, g = 0, b = 0; let dark = false;
  if (ix == THEME_CUSTOM) {
    r = settings.customR; g = settings.customG; b = settings.customB;
    dark = darkInkFor(r, g, b);   // the presets' hand-set flags cannot help here
  } else {
    let t = THEMES[ix];
    r = t.r; g = t.g; b = t.b; dark = t.darkInk;
  }
  COL_THEME     = u16(C565(r, g, b));
  COL_THEME_INK = dark ? u16(C565(0x00, 0x00, 0x00)) : u16(C565(0xFF, 0xFF, 0xFF));
  settings.themeIx = u8(ix);
}

// ---- settings tree: accessors and string helpers ----
// ⚠️ ALL FOUR live down here, not beside the tables, and for two different
// reasons that both bite at compile time:
//
//   setValueSet()  touches debugMode, declared below the tables.
//   setValueStr()  must NOT take a `const SetRow&`. Arduino auto-generates a
//                  prototype for every function and inserts them ABOVE the
//                  struct definitions, so any free function naming SetRow in
//                  its signature fails with "does not name a type". Passing
//                  kind and arg as plain uint8_t sidesteps it entirely.
//
// Locals inside a function body are fine - the renderer and the dispatcher both
// hold a `const SetRow&` without trouble. It is only signatures that break.
function setValueGet(f) {
  switch (f) {
    case SF_RINGVOL:  return settings.ringVolume;
    case SF_DEBUG:    return settings.debugMode ? 1 : 0;
    case SF_AUTOTIME: return settings.autoTime ? 1 : 0;
    case SF_DIM:      return settings.dimAfterS;
    case SF_SLEEP:    return settings.sleepAfterS;
    case SF_BRIGHT:   return settings.brightness;
    case SF_KEYTONES: return keyToneLevel();      // 0 = Off (11 Nov)
    case SF_KEYWHERE: return keyToneWhere();
  }
  return 0;
}

function setValueSet(f, v) {
  switch (f) {
    case SF_RINGVOL:  settings.ringVolume = i8(v); break;
    case SF_DEBUG:    settings.debugMode = u8(v ? 1 : 0); debugMode = (v != 0); break;
    case SF_AUTOTIME: settings.autoTime = u8(v ? 1 : 0); break;
    // Dim ALWAYS happens before sleep, so the two cannot be set independently -
    // they push each other rather than letting you build a state where the
    // screen is meant to sleep before it dims, which would just never dim.
    //
    //   dim 20, sleep 30 -> dim to 30 -> sleep goes to 40
    //   sleep 40, dim 30 -> sleep to 30 -> dim comes down to 25
    //   sleep to 20 -> dim comes down to 15
    case SF_DIM:
      settings.dimAfterS = u16(v);
      if (settings.dimAfterS >= settings.sleepAfterS)
        settings.sleepAfterS = u16(settings.dimAfterS + SLEEP_STEP);
      break;
    case SF_SLEEP:
      settings.sleepAfterS = u16(v);
      if (settings.dimAfterS >= settings.sleepAfterS)
        settings.dimAfterS = u16((settings.sleepAfterS > u16(DIM_STEP))
                           ? settings.sleepAfterS - DIM_STEP
                           : u16(DIM_STEP));
      break;
    case SF_BRIGHT:   settings.brightness = u8(v); break;
    case SF_KEYTONES: settings.keyTones = u8((v <= 0) ? KT_STORED_OFF : u8(v)); break;   // 11 Nov
    case SF_KEYWHERE: settings.keyTonesWhere = u8(v); break;
  }
  settingsSave();
}

// Kept here rather than beside the tables because they read simReady,
// modemSignalCSQ and networkRegistered(), none of which exist that far up.
let setInfoStr__buf = new Uint8Array(24);
function setInfoStr(id) {
  /* static: setInfoStr__buf */
  switch (id) {
    case IN_OPERATOR: return netOperator[0] ? netOperator : S("--");
    case IN_BAND:     return netBand[0]     ? netBand     : S("--");
    case IN_SIGNAL:
      if (!simReady) return S("--");
      snprintf(setInfoStr__buf, setInfoStr__buf.length, S("%d/31"), modemSignalCSQ);
      return setInfoStr__buf;
    case IN_REG:
      if (!simReady) return S("--");
      return networkRegistered() ? S("Registered") : S("Searching");
    case IN_VERSION:  return FW_BUILD;
    case IN_BOOTS:
      snprintf(setInfoStr__buf, setInfoStr__buf.length, S("%u"), settings.bootCount);
      return setInfoStr__buf;
    case IN_UPTIME:
      snprintf(setInfoStr__buf, setInfoStr__buf.length, S("%u min"), (Math.trunc(millis() / 60000)));
      return setInfoStr__buf;
  }
  return S("");
}

// The right-hand column. Empty means draw nothing there.
function setValueStr(out, n, kind, arg) {
  out[0] = 0;
  switch (kind) {
    case SK_TOGGLE:
      snprintf(out, n, S("%s"), setValueGet(arg) ? S("ON") : S("OFF"));
      break;
    case SK_RANGE: {
      let v = setValueGet(arg);
      // Ring volume is not a plain number at the bottom of its range: -1 and 0
      // are Silent and Vibrate, the same encoding the status bar icons read.
      if (arg == SF_RINGVOL) {
        if      (v < 0)  snprintf(out, n, S("Silent"));
        else if (v == 0) snprintf(out, n, S("Vibrate"));
        else             snprintf(out, n, S("%d"), v);
      } else if (arg == SF_DIM || arg == SF_SLEEP) {
        snprintf(out, n, S("%ds"), v);
      } else if (arg == SF_KEYTONES && v <= 0) {
        snprintf(out, n, S("Off"));                     // the keypad tones (11 Nov)
      } else if (arg == SF_KEYWHERE) {
        snprintf(out, n, S("%s"), (v == KT_WHERE_NOTEXT) ? S("Not in texts")
                             : (v == KT_WHERE_NUMBERS) ? S("Numbers only") : S("Everywhere"));
      } else {
        snprintf(out, n, S("%d"), v);
      }
      break;
    }
    case SK_INFO:   snprintf(out, n, S("%s"), setInfoStr(arg)); break;
    case SK_SOON:   snprintf(out, n, S("soon")); break;   // says why, where "--" only said "nothing"

    // The SIM PIN row: whether the card asks for its PIN at start (11 Nov).
    // Nothing while that is not known - no SIM, the card locked, no answer.
    case SK_ACTION:
      if (arg == AC_SIM_PIN && simReady && simPinLock >= 0)
        snprintf(out, n, S("%s"), simPinLock ? S("On") : S("Off"));
      break;

    // Rows that open a page or a screen draw nothing on the right. They used
    // to show a ">"; dropped on request, the rows read fine without it.
    case SK_PAGE:
    case SK_SCREEN: break;
    default: break;
  }
}

// A row drawn greyed, that does nothing when pressed: one with nothing behind
// it yet ("soon"), and Change PIN while the card does not ask for its PIN - off,
// or not known (11 Nov). The owner's pick: greyed, with no word after it.
function setRowGreyed(kind, arg) {
  if (kind == SK_SOON) return true;
  if (kind == SK_ACTION && arg == AC_SIM_CHANGE) return !(simReady && simPinLock == 1);
  return false;
}

// ---- contacts ----
// The file now carries a header. Without one, contactCount came from
// filesize / sizeof(Contact), so the moment the record grew - which it just did,
// by one colour byte - every existing record would reinterpret at the wrong
// stride. No error, no crash, just an address book turned to noise.
//
// On a mismatch the file is DISCARDED rather than migrated. That is correct for
// a breadboard with test data on it and wrong for anything with real contacts on
// it, so it has an expiry date: before a unit leaves this desk with somebody's
// numbers on it, this needs to become a read-widen-rewrite migration. See the
// order-of-work note in the register.
const CONTACTS_MAGIC = 0x50585043;  // "PXPC"
const CONTACTS_VERSION = 3;  // 3 = + each one's ringtone, and the ringtone songs after them (12 Nov);
                               // 2 = three numbers with labels; v1 and v2 files are widened on load

class ContactsHeader {
  constructor() {
    this.magic = 0;
    this.version = 0;
    this.count = 0;   // authoritative, instead of inferring it from the length
  }
}
ContactsHeader.$f = [['magic', 'u32', 0], ['version', 'u16', 4], ['count', 'u16', 6]];
ContactsHeader.$size = 8;

// Contact colours. 0 is "Default", which draws in whatever the theme is - so an
// untouched contact looks exactly as it did before colours existed, and the
// palette is opt-in rather than something applied to everybody at once.
//
// NOT the theme palette. These are only ever drawn as text on black, so a dim
// one is merely dim; nothing here is ever a fill with text on top of it.
const CONTACT_COLOUR_NAMES = [S("Default"), S("Red"), S("Orange"), S("Yellow"), S("Green"), S("Azure"), S("Violet"), S("White")];
const CONTACT_COLOUR_COUNT = 8;

// Shown on the detail screen, in the number chooser and in the label popup.
// Longest is 6 characters, which the chooser's 18-character budget relies on.
const NUM_LABELS = [S("Mobile"), S("Home"), S("Work"), S("Other")];

function contactColour(ix) {
  switch (ix) {
    case 1: return u16(C565(0xFF, 0x00, 0x00));
    case 2: return u16(C565(0xFF, 0x7F, 0x00));
    case 3: return u16(C565(0xFF, 0xFF, 0x00));
    case 4: return u16(C565(0x00, 0xFF, 0x00));
    case 5: return u16(C565(0x00, 0xB0, 0xFF));
    case 6: return u16(C565(0x94, 0x00, 0xD3));
    case 7: return u16(C565(0xFF, 0xFF, 0xFF));
    default: return COL_THEME;
  }
}

function contactsSave() {
  if (!fsReady) return false;
  let h = new ContactsHeader();
  h.magic = CONTACTS_MAGIC; h.version = CONTACTS_VERSION;
  h.count = u16(contactCount);

  // Same write-to-temp-then-rename dance as saveFileAtomic(), open-coded only
  // because the payload is now two pieces and that helper takes one buffer.
  let tmp = jstr(PATH_CONTACTS) + ".tmp";
  let f = LittleFS.open(tmp, S("w"));
  if (!f.valid()) { pxlog("Contacts: cannot open temp file"); return false; }
  let need = u32(8 /*sizeof(h)*/ + u32(Math.imul(u32(contactCount), 101 /*sizeof Contact*/)));
  let wrote = f.write(h, 8 /*sizeof(h)*/);
  if (contactCount > 0)
    wrote = u32(wrote + (f.write(recPtr(contacts, 0), u32(Math.imul(u32(contactCount), 101 /*sizeof Contact*/)))));
  // Then the songs kept as ringtones (12 Nov): how many slots, and each path.
  let ns = u16(ringSongCount);
  need = u32(need + (u32(2 /*sizeof(ns)*/ + u32(Math.imul(ns, RING_SONG_PATH)))));
  wrote = u32(wrote + (f.write(view(ref(() => ns, v => ns = u16(v), 'u16'), Uint8Array), 2 /*sizeof(ns)*/)));
  if (ns > 0) wrote = u32(wrote + (f.write(ringSongs, u32(Math.imul(ns, RING_SONG_PATH)))));
  f.close();
  if (wrote != need) { LittleFS.remove(tmp); pxlog("Contacts: short write"); return false; }
  // Straight over the old file: never a moment with no contacts file (11 Nov).
  if (!fileReplace(cstr(tmp), PATH_CONTACTS)) { pxlog("Contacts: rename failed"); return false; }
  return true;
}

// ---- A-Z order (the owner, 8 Nov: "contacts in abc order") ----
// The array itself is kept sorted, so everything that walks it - the list, its
// scrollbar, the up/down keys - is in order with no second index to keep in
// step. A new contact goes straight into its place (contactsAdd), a renamed one
// moves (Edit name), and every load sorts the whole list once, which also
// sorts contacts saved before this existed.

// Compares two names the way they are drawn: accents folded by nextFoldedChar(),
// so an accented first letter sorts with its plain letter - right where the
// screen shows it - and capitals the same as small letters. Digits and signs
// come before A, and "Anna" before "Anna B" before "Annabel". Only names that
// still tie are told apart by their bytes (plain before accented, capital
// before small), so the order never depends on which one was saved first.
function contactNameCmp(a, b) {
  let p = a;
  let q = b;
  while (p[0] && q[0]) {
    let x = tolower(nextFoldedChar(ref(() => p, v => p = v)));
    let y = tolower(nextFoldedChar(ref(() => q, v => q = v)));
    if (x != y) return x - y;
  }
  if (p[0]) return 1;            // b ran out first: the shorter name goes first
  if (q[0]) return -1;
  return strcmp(a, b);
}

// Slides contact idx up or down to where its name belongs - all the others are
// already in order - and returns where it landed. For a new contact (it arrives
// at the end) and a renamed one.
function contactsPlace(idx) {
  if (idx < 0 || idx >= contactCount) return idx;
  let t = clone(contacts[idx]);
  let i = idx;
  while (i > 0 && contactNameCmp(contacts[i - 1].name, t.name) > 0) {
    assign(contacts[i], contacts[i - 1]);
    i--;
  }
  if (i == idx) {
    while (i + 1 < contactCount && contactNameCmp(contacts[i + 1].name, t.name) <= 0) {
      assign(contacts[i], contacts[i + 1]);
      i++;
    }
  }
  assign(contacts[i], t);
  return i;
}

// The whole list into A-Z order, after every load. Insertion sort: equal names
// keep their saved order, it needs no extra memory, and 250 is the most it
// ever has to sort.
function contactsSortAll() {
  for (let k = 1; k < contactCount; k++) {
    let t = clone(contacts[k]);
    let i = k;
    while (i > 0 && contactNameCmp(contacts[i - 1].name, t.name) > 0) {
      assign(contacts[i], contacts[i - 1]);
      i--;
    }
    assign(contacts[i], t);
  }
}

function contactsLoad() {
  contactCount = 0;
  ringSongCount = 0;                   // the ringtone songs come with them (12 Nov)
  memset(ringSongs, 0, 4096 /*sizeof(ringSongs)*/);
  fileTakeBackTemp(PATH_CONTACTS);     // a save cut off half way (11 Nov)
  if (!fsReady || !LittleFS.exists(PATH_CONTACTS)) return;
  let f = LittleFS.open(PATH_CONTACTS, S("r"));
  if (!f.valid()) return;

  let h = new ContactsHeader();
  let got = i32(f.read(h, 8 /*sizeof(h)*/));
  // A v1 file - one number a contact - is WIDENED rather than thrown away, so
  // contacts survive this change and so do backups made before it (§1.2t).
  let v1 = (got == i32(8 /*sizeof(h)*/) && h.magic == CONTACTS_MAGIC && h.version == 1);
  if (v1) {
    class ContactV1 {
  constructor() {
    this.name = new Uint8Array(24);
    this.number = new Uint8Array(24);
    this.colour = 0;
  }
}
ContactV1.$f = [['name', ['u8', 24], 0], ['number', ['u8', 24], 24], ['colour', 'u8', 48]];
ContactV1.$size = 49;
    let n = h.count;
    if (n > CONTACTS_MAX) n = CONTACTS_MAX;
    let old = new ContactV1();
    while (contactCount < n && f.read(old, 49 /*sizeof(old)*/) == 49 /*sizeof(old)*/) {
      let c = contacts[contactCount];
      memset(c, 0, 101 /*sizeof(c)*/);              // slots 1 and 2 start empty
      memcpy(c.name, old.name, CONTACT_NAME_LEN);
      memcpy(c.number[0], old.number, CONTACT_NUM_LEN);
      c.name[CONTACT_NAME_LEN - 1] = 0;
      c.number[0][CONTACT_NUM_LEN - 1] = 0;
      c.label[0] = NL_MOBILE;
      c.colour = u8((old.colour < CONTACT_COLOUR_COUNT) ? old.colour : 0);
      contactCount++;
    }
    f.close();
    pxlog("Contacts: widened " + String(contactCount) + " from v1");
    contactsSortAll();                       // A-Z, like every load
    contactsSave();                          // written as v3 (12 Nov), so this happens once
    return;
  }
  // A v2 file - no ringtone byte (12 Nov) - is WIDENED too: each record read
  // into its place, the ringtone Default. Written as v3 straight after.
  let v2 = (got == i32(8 /*sizeof(h)*/) && h.magic == CONTACTS_MAGIC && h.version == 2);
  if (v2) {
    const v2Size = u32(101 /*sizeof Contact*/ - 1);     // the old record: all but the ringtone
    let n = h.count;
    if (n > CONTACTS_MAX) n = CONTACTS_MAX;
    while (contactCount < n) {
      let c = contacts[contactCount];
      memset(c, 0, 101 /*sizeof(c)*/);
      if (f.read(c, v2Size) != v2Size) break;
      contactCount++;
    }
    f.close();
    pxlog("Contacts: widened " + String(contactCount) + " from v2");
    contactsSortAll();
    contactsSave();
    return;
  }
  if (got != i32(8 /*sizeof(h)*/) || h.magic != CONTACTS_MAGIC || h.version != CONTACTS_VERSION) {
    f.close();
    pxlog("Contacts: fresh start");
    contactCount = 0;
    contactsSave();     // stamp a valid empty file so this happens exactly once
    return;
  }

  let n = h.count;
  if (n > CONTACTS_MAX) n = CONTACTS_MAX;
  let want = u32(Math.imul(u32(n), 101 /*sizeof Contact*/));
  let read = (n > 0) ? f.read(recPtr(contacts, 0), want) : 0;
  contactCount = i32(Math.trunc(read / 101 /*sizeof Contact*/));   // trust what actually arrived, not the header
  // The songs kept as ringtones, after the contacts (12 Nov). A file cut short
  // keeps the slots that came whole.
  let ns = 0;
  if (read == want && f.read(view(ref(() => ns, v => ns = u16(v), 'u16'), Uint8Array), 2 /*sizeof(ns)*/) == 2 /*sizeof(ns)*/) {
    if (ns > RING_SONGS_MAX) ns = RING_SONGS_MAX;
    for (let i = 0; i < ns; i++) {
      if (f.read(ringSongs[i], RING_SONG_PATH) != RING_SONG_PATH) { ringSongs[i][0] = 0; break; }
      ringSongs[i][RING_SONG_PATH - 1] = 0;
      ringSongCount = i + 1;
    }
  }
  f.close();
  contactsSortAll();                       // A-Z - also a list saved before it was kept sorted
}

// Where contactsAdd() put the newest contact - its A-Z place, so not always
// the end - or -1 if it could not add one.
let contactLastAdded = -1;

function contactsAdd(name, number) {
  contactLastAdded = -1;
  if (contactCount >= CONTACTS_MAX) return false;
  let c = contacts[contactCount];
  memset(c, 0, 101 /*sizeof(c)*/);   // this slot may still hold a deleted contact's numbers
  strncpy(c.name,      name,   u32(CONTACT_NAME_LEN - 1));
  strncpy(c.number[0], number, u32(CONTACT_NUM_LEN - 1));
  c.label[0] = NL_MOBILE;     // the label popup that follows can change it
  c.colour   = 0;             // Default: follows the theme until changed
  contactCount++;
  contactLastAdded = contactsPlace(contactCount - 1);   // into its A-Z place
  return contactsSave();
}

// How many numbers a contact has. Slots fill from 0 with no gaps, so this is
// simply the first empty one.
function contactNumCount(idx) {
  if (idx < 0 || idx >= contactCount) return 0;
  let n = 0;
  while (n < CONTACT_NUMS && ((contacts[idx].number)[n])[0]) n++;
  return n;
}

// The default label for a number being added: the first of Mobile, Home, Work
// this contact does not have yet, else Other.
function contactFreeLabel(idx) {
  let n = contactNumCount(idx);
  for (let l = NL_MOBILE; l <= NL_WORK; l = u8(l + 1)) {
    let used = false;
    for (let k = 0; k < n; k++) if ((contacts[idx].label)[k] == l) used = true;
    if (!used) return l;
  }
  return NL_OTHER;
}

function contactsDelete(idx) {
  if (idx < 0 || idx >= contactCount) return false;
  for (let i = idx; i < contactCount - 1; i++) assign(contacts[i], contacts[i + 1]);
  contactCount--;
  return contactsSave();
}

// ---- messages ----
// Append-only on disk. LittleFS already wear-levels blocks internally, but
// contactsSave()'s "rewrite the whole array" approach means every single
// incoming text rewrites the entire message history to flash - fine for a
// few hundred contacts added rarely, wasteful for texts that can arrive
// often. Appending writes just the ONE new record each time; only the rare
// delete operations still rewrite the full file, which is the standard
// tradeoff for log-shaped data (frequent appends, occasional prunes).
//
// Separate from simFlash: that one only ever draws on ST_HOME, but a storage-
// full warning needs to be seen wherever the person actually is (compose
// screen, chat, thread list) - so this gets its own flag, checked from those
// screens directly, and stays up longer since it matters more than routine
// SIM chatter.
let msgStorageFlash = cbuf(48, "");
let msgStorageFlashUntil = 0;
function msgSetStorageFlash(text) {
  strncpy(msgStorageFlash, text, u32(msgStorageFlash.length - 1));
  msgStorageFlash[msgStorageFlash.length - 1] = 0;
  msgStorageFlashUntil = u32(millis() + 4000);
}

// Since appends never shrink the file on their own, it needs a ceiling.
// MSG_RESERVE_BYTES is free space kept untouched for settings.dat/contacts.dat
// and LittleFS's own bookkeeping, so messages can never starve the rest of
// the phone even if the log grows for years. Checked before every single
// append, not just occasionally, so the very first write that would cross
// the line is the one that gets refused - never a partial/torn record.
const MSG_RESERVE_BYTES = (256 * 1024);  // ~256KB headroom kept free, always

function messagesSpaceOK() {
  if (!fsReady) return false;
  let total = u32(LittleFS.totalBytes());
  let used = u32(LittleFS.usedBytes());
  let free_ = (total > used) ? (u32(total - used)) : 0;
  return free_ > (u32(u32(MSG_RESERVE_BYTES) + 192 /*sizeof Message*/));
}

function messagesAppendOne(m) {
  if (!fsReady) return false;
  if (!messagesSpaceOK()) {
    pxlog("[SMS] Storage full - message NOT saved. Free up space (delete old messages/photos).");
    msgSetStorageFlash(S("Storage full! Delete old messages"));
    return false;
  }
  let f = LittleFS.open(PATH_MESSAGES, S("a"));   // "a" = append, creates if missing
  if (!f.valid()) { pxlog("FS: cannot open messages for append"); return false; }
  let written = f.write(m, 192 /*sizeof Message*/);
  f.close();
  if (written != 192 /*sizeof Message*/) { pxlog("FS: short append"); return false; }
  return true;
}

// Full rewrite - only used by delete, which is rare. Same atomic temp+rename
// pattern as contactsSave(), so a power cut mid-delete can't corrupt the file.
function messagesRewriteAll() {
  return saveFileAtomic(PATH_MESSAGES, messages,
                        u32(Math.imul(u32(messageCount), 192 /*sizeof Message*/)));
}

// Reads messages.dat into RAM. If the file (which only ever grows via
// append) holds more records than MESSAGES_MAX, loadFile()'s straight
// from-the-start read would keep the OLDEST records and silently hide
// the newest ones - the opposite of what anyone wants from a message log.
// So this seeks past the older records first and reads only the newest
// MESSAGES_MAX - same "oldest drops off" behaviour messagesAdd() uses
// once the in-memory log fills up.
function messagesLoad() {
  messageCount = 0;
  if (192 /*sizeof Message*/ != 192)
    pxlog("WARNING: Message record is not 192 bytes - saved messages will read wrong");
  fileTakeBackTemp(PATH_MESSAGES);     // a delete's rewrite cut off half way (11 Nov)
  if (!fsReady || !LittleFS.exists(PATH_MESSAGES)) return;
  let f = LittleFS.open(PATH_MESSAGES, S("r"));
  if (!f.valid()) return;

  let total = f.size();
  let totalRecords = Math.trunc(total / 192 /*sizeof Message*/);
  let skipRecords = (totalRecords > MESSAGES_MAX) ? u32(totalRecords - MESSAGES_MAX) : 0;
  if (skipRecords > 0) {
    f.seek(u32(Math.imul(skipRecords, 192 /*sizeof Message*/)));
    pxlog("Messages: file exceeds RAM cap, loading newest only");
  }

  let toRead = u32(Math.imul((u32(totalRecords - skipRecords)), 192 /*sizeof Message*/));
  let n = f.read(recPtr(messages, 0), toRead);
  f.close();
  messageCount = i32(Math.trunc(n / 192 /*sizeof Message*/));
  if (messageCount > MESSAGES_MAX) messageCount = MESSAGES_MAX;   // defensive, shouldn't trigger
}

// Appends one message, oldest-drops from RAM if the in-memory log is full,
// then appends just this one record to flash. direction/number/body straight
// in; epoch stamped from the RTC once NTP has synced (falls back to 0, same
// "before first sync" behaviour as nowTime()).
function messagesAdd(number, body, direction, status) {
  if (messageCount >= MESSAGES_MAX) {
    // drop the single oldest record from RAM only - the flash file keeps
    // growing via append and gets trimmed on next boot by messagesLoad().
    // A rare full-rewrite-and-truncate here would defeat the point of
    // appending, so this cap is a RAM/display limit, not a flash one.
    for (let i = 0; i < messageCount - 1; i++) assign(messages[i], messages[i + 1]);
    messageCount--;
  }
  let m = messages[messageCount];
  strncpy(m.number, number, u32(MSG_NUMBER_LEN - 1));
  m.number[MSG_NUMBER_LEN - 1] = 0;
  strncpy(m.body, body, u32(MSG_BODY_LEN - 1));
  m.body[MSG_BODY_LEN - 1] = 0;
  m.direction = direction;
  m.status    = status;       // every time: this slot may hold an older record's byte
  let t = new tm(); nowTime(t);
  let tt = mktime(t);           // 0 if the clock never synced - acceptable,
  m.epoch = (tt > 0) ? u32(tt) : 0;   // matches nowTime()'s own "zeros" fallback
  messageCount++;
  return messagesAppendOne(m);
}

function messagesDelete(idx) {
  if (idx < 0 || idx >= messageCount) return false;
  for (let i = idx; i < messageCount - 1; i++) assign(messages[i], messages[i + 1]);
  messageCount--;
  return messagesRewriteAll();   // rare op, full rewrite is fine here
}

// Deletes every message in a thread (number match) at once - used when a
// contact is deleted along with their conversation, or "Delete thread".
function messagesDeleteThread(number) {
  let removed = 0;
  let w = 0;
  for (let r = 0; r < messageCount; r++) {
    if (strcmp(messages[r].number, number) == 0) { removed++; continue; }
    if (w != r) assign(messages[w], messages[r]);
    w++;
  }
  messageCount = w;
  if (removed > 0) messagesRewriteAll();   // rare op, full rewrite is fine here
  return removed;
}

// ---- call log ----
// Same append-only shape as messages, same reasoning: appends are cheap and
// frequent, full rewrites are rare and reserved for delete. Reuses
// MSG_RESERVE_BYTES rather than inventing a second reserve - both logs are
// competing for the same flash headroom, so one shared floor is correct;
// two independent reserves could let messages+calls together starve
// settings/contacts even though each individually looked fine.
function callLogSpaceOK() {
  if (!fsReady) return false;
  let total = u32(LittleFS.totalBytes());
  let used = u32(LittleFS.usedBytes());
  let free_ = (total > used) ? (u32(total - used)) : 0;
  return free_ > (u32(u32(MSG_RESERVE_BYTES) + 36 /*sizeof CallLogEntry*/));
}

function callLogAppendOne(c) {
  if (!fsReady) return false;
  if (!callLogSpaceOK()) {
    pxlog("[Call] Storage full - call log entry NOT saved.");
    msgSetStorageFlash(S("Storage full! Delete old messages"));
    return false;
  }
  let f = LittleFS.open(PATH_CALLLOG, S("a"));
  if (!f.valid()) { pxlog("FS: cannot open calllog for append"); return false; }
  let written = f.write(c, 36 /*sizeof CallLogEntry*/);
  f.close();
  if (written != 36 /*sizeof CallLogEntry*/) { pxlog("FS: short append"); return false; }
  return true;
}

function callLogRewriteAll() {
  return saveFileAtomic(PATH_CALLLOG, callLog,
                        u32(Math.imul(u32(callLogCount), 36 /*sizeof CallLogEntry*/)));
}

// Same "seek past older records, keep newest CALLLOG_MAX" logic as
// messagesLoad() - the file only ever grows via append, so a straight
// from-the-start read would silently hide the newest calls behind a RAM cap.
function callLogLoad() {
  callLogCount = 0;
  fileTakeBackTemp(PATH_CALLLOG);      // a delete's rewrite cut off half way (11 Nov)
  if (!fsReady || !LittleFS.exists(PATH_CALLLOG)) return;
  let f = LittleFS.open(PATH_CALLLOG, S("r"));
  if (!f.valid()) return;

  let total = f.size();
  let totalRecords = Math.trunc(total / 36 /*sizeof CallLogEntry*/);
  let skipRecords = (totalRecords > CALLLOG_MAX) ? u32(totalRecords - CALLLOG_MAX) : 0;
  if (skipRecords > 0) {
    f.seek(u32(Math.imul(skipRecords, 36 /*sizeof CallLogEntry*/)));
    pxlog("Call log: file exceeds RAM cap, loading newest only");
  }

  let toRead = u32(Math.imul((u32(totalRecords - skipRecords)), 36 /*sizeof CallLogEntry*/));
  let n = f.read(recPtr(callLog, 0), toRead);
  f.close();
  callLogCount = i32(Math.trunc(n / 36 /*sizeof CallLogEntry*/));
  if (callLogCount > CALLLOG_MAX) callLogCount = CALLLOG_MAX;   // defensive, shouldn't trigger
}

// Appends one call record, oldest-drops from RAM if full, then appends just
// this one record to flash - same shape as messagesAdd(). epoch stamped from
// the RTC (0 if the clock never synced, same fallback nowTime() itself uses).
function callLogAdd(number, type, durationSec) {
  let hadCalls = (callLogCount > 0);
  if (callLogCount >= CALLLOG_MAX) {
    for (let i = 0; i < callLogCount - 1; i++) assign(callLog[i], callLog[i + 1]);
    callLogCount--;
    if (callLogDetailIx >= 0) callLogDetailIx--;   // everything moved down one; -1 if it was the one dropped
  }
  let c = callLog[callLogCount];
  strncpy(c.number, number, u32(CALLLOG_NUMBER_LEN - 1));
  c.number[CALLLOG_NUMBER_LEN - 1] = 0;
  c.type = type;
  let t = new tm(); nowTime(t);
  let tt = mktime(t);
  c.epoch = (tt > 0) ? u32(tt) : 0;
  c.durationSec = durationSec;
  callLogCount++;
  // The list shows the newest call on top, so every other row just moved down
  // one. Move the highlight with them: it stays on the same call. It used to
  // keep its row, so after calling back from the list it sat on the call above
  // (4.7, 8 Nov). The details screen keeps its call by itself (callLogDetailIx).
  if (hadCalls && callLogIdx < callLogCount - 1) callLogIdx++;
  if (callLogIdx >= callLogTop + 8) callLogTop = callLogIdx - 7;
  return callLogAppendOne(c);
}

function callLogDelete(idx) {
  if (idx < 0 || idx >= callLogCount) return false;
  for (let i = idx; i < callLogCount - 1; i++) assign(callLog[i], callLog[i + 1]);
  callLogCount--;
  return callLogRewriteAll();   // rare op, full rewrite is fine here
}

// Puts the list's highlight on callLog[ix] (stored oldest-first, shown
// newest-first) and scrolls the 8-row window to it. Used coming back from the
// details screen, so Back lands on the call you were looking at.
function callLogShowEntry(ix) {
  if (ix < 0 || ix >= callLogCount) return;   // gone: the list keeps its place
  callLogIdx = callLogCount - 1 - ix;
  if (callLogIdx < callLogTop) callLogTop = callLogIdx;
  if (callLogIdx >= callLogTop + 8) callLogTop = callLogIdx - 7;
}

// Groups messages[] into one row per distinct number, newest message first
// overall (so the most recently active conversation sits at the top - same
// idea as any phone's message list). O(n^2) against MESSAGES_MAX=300, which
// is trivial on this chip; not worth a hash map for a list this small.
function threadsScan() {
  threadCount = 0;
  threadIdx = 0; threadTop = 0;
  for (let i = 0; i < messageCount && threadCount < THREADS_MAX; i++) {
    let num = messages[i].number;
    let found = -1;
    for (let t = 0; t < threadCount; t++) {
      if (strcmp(threadNumbers[t], num) == 0) { found = t; break; }
    }
    if (found >= 0) {
      threadLastMsg[found] = i;                  // later messages[] index = more recent
    } else {
      strncpy(threadNumbers[threadCount], num, u32(MSG_NUMBER_LEN - 1));
      threadNumbers[threadCount][MSG_NUMBER_LEN - 1] = 0;
      threadLastMsg[threadCount] = i;
      threadCount++;
    }
  }
  // sort newest-first by each thread's latest message index (simple insertion
  // sort - same style as galleryScan()'s name sort, list is always small)
  for (let i = 1; i < threadCount; i++) {
    let nm = new Uint8Array(24); let lm = 0;
    strncpy(nm, threadNumbers[i], MSG_NUMBER_LEN); lm = threadLastMsg[i];
    let j = i - 1;
    while (j >= 0 && threadLastMsg[j] < lm) {
      strncpy(threadNumbers[j + 1], threadNumbers[j], MSG_NUMBER_LEN);
      threadLastMsg[j + 1] = threadLastMsg[j];
      j--;
    }
    strncpy(threadNumbers[j + 1], nm, MSG_NUMBER_LEN);
    threadLastMsg[j + 1] = lm;
  }
}

// Looks up a contact name for a number, for display. Returns the number
// itself (unknown-sender case) if there's no match - caller just prints
// whatever comes back, same as the mockup's "+3670..." row.
function contactNameForNumber(number) {
  let i = contactIndexForNumber(number);
  return (i >= 0) ? contacts[i].name : number;
}

function contactExistsForNumber(number) {
  return contactIndexForNumber(number) >= 0;
}

// Which contact owns this number - ANY of its numbers - or -1. Both lookups
// above go through here, so a second or third number is recognised everywhere
// a first one is: messages, the chat title, the call log, incoming calls.
function contactIndexForNumber(number) {
  if (!number || !number[0]) return -1;
  for (let i = 0; i < contactCount; i++)
    for (let k = 0; k < CONTACT_NUMS && ((contacts[i].number)[k])[0]; k++)
      if (strcmp((contacts[i].number)[k], number) == 0) return i;
  return -1;
}

// ==================== NOTES: storage ====================
// The file: a header, then each note as its 40-byte title, the length of its
// text (2 bytes) and the text itself - so a short note is a short write. As
// fixed 1 KB records a full notebook would be 104 KB, about 1.5 s to rewrite at
// LittleFS speed (~70 KB/s) on every save. Written whole to a temp file, which
// then replaces the old one - see notesSave().
const NOTES_MAGIC = 0x5058504E;  // "PXPN"
const NOTES_VERSION = 1;
const NOTE_MAX_LINES = (NOTE_BODY_LEN - 1);  // the open note, wrapped. Every line holds
                                     // at least one letter, so a note can never need more
                                     // lines than it has letters - 1000 always holds all of
                                     // it (48 KB, PSRAM). Odd texts really do need ~135.

class NotesHeader {
  constructor() {
    this.magic = 0;
    this.version = 0;
    this.count = 0;
  }
}
NotesHeader.$f = [['magic', 'u32', 0], ['version', 'u16', 4], ['count', 'u16', 6]];
NotesHeader.$size = 8;

// typedef char WrapLine[CHAT_LINE_LEN];   // one line, as wrapText() writes them
let noteLines = null;          // NOTE_MAX_LINES of them, PSRAM too

// Nothing but spaces (or line breaks), or nothing? The app would not save that
// either ("isNotBlank").
function noteBlank(s) {
  while (s[0] == ch(' ') || s[0] == ch('\n')) s = ptrAdd(s, 1);
  return s[0] == 0;
}

// Into a note field: the spaces (and line breaks, 11 Nov) at either end left
// off, cut to fit, and the rest of the field cleared, so the file never
// carries an older text's tail.
function noteSetText(dst, dstLen, src) {
  while (src[0] == ch(' ') || src[0] == ch('\n')) src = ptrAdd(src, 1);
  let n = i32(strlen(src));
  while (n > 0 && (src[n - 1] == ch(' ') || src[n - 1] == ch('\n'))) n--;
  if (n > dstLen - 1) n = dstLen - 1;
  memset(dst, 0, u32(dstLen));
  memcpy(dst, src, u32(n));
}

// A note's text into lines, one line break at a time (11 Nov): wrapText()
// knows spaces, not line ends - the File explorer's text view does the same.
// An empty line stays one. The break is put back after each piece, so the note
// itself is untouched. A text with no break wraps exactly as before.
function noteWrapBody(body, out, maxLines) {
  if (!strchr(body, ch('\n'))) return wrapText(body, 216, 13, out, maxLines);
  let count = 0;
  let p = body;
  while (count < maxLines) {
    let nl = strchr(p, ch('\n'));
    if (nl) nl[0] = 0;
    let got = wrapText(p, 216, 13, ptrAdd(out, count), maxLines - count);
    if (nl) nl[0] = ch('\n');
    if (got == 0) { out[count][0] = 0; got = 1; }   // an empty line
    count += got;
    if (!nl) break;
    p = ptrAdd(nl, 1);
  }
  return (count > maxLines) ? maxLines : count;
}

function notesSave() {
  if (!fsReady || !noteList) return false;
  let h = new NotesHeader();
  h.magic = NOTES_MAGIC; h.version = NOTES_VERSION; h.count = u16(noteCount);
  let need = 8 /*sizeof(h)*/;
  for (let i = 0; i < noteCount; i++) need = u32(need + (u32(u32(NOTE_TITLE_LEN + 2) + strlen(noteList[i].body))));
  // A big notebook takes a moment: say so first, like "Sending...", so a
  // frozen screen explains itself. 16 KB is about a quarter of a second.
  let slow = (need > 16384);
  if (slow) { busyText = S("Saving..."); renderInner(true); }
  let tmp = jstr(PATH_NOTES) + ".tmp";
  let f = LittleFS.open(tmp, S("w"));
  let ok = false;
  if (f.valid()) {
    let wrote = f.write(h, 8 /*sizeof(h)*/);
    for (let i = 0; i < noteCount; i++) {
      let len = u16(strlen(noteList[i].body));
      wrote = u32(wrote + f.write(noteList[i].title, NOTE_TITLE_LEN));
      wrote = u32(wrote + (f.write(view(ref(() => len, v => len = u16(v), 'u16'), Uint8Array), 2)));
      if (len > 0) wrote = u32(wrote + f.write(noteList[i].body, len));
    }
    f.close();
    ok = (wrote == need);
    if (!ok) LittleFS.remove(tmp);
  }
  if (ok) {
    // Renamed straight over the old file: littlefs replaces it in one step, so
    // a power cut leaves the old notes or the new ones, never neither. Removing
    // the old file first - what contacts do - leaves a moment with no file at
    // all. That stays only as the fallback, and notesLoad() picks up a temp
    // file left alone by a cut in that moment.
    ok = LittleFS.rename(tmp, jstr(PATH_NOTES));
    if (!ok) {
      LittleFS.remove(PATH_NOTES);
      ok = LittleFS.rename(tmp, jstr(PATH_NOTES));
    }
  }
  if (slow) busyText = null;
  if (!ok) { pxlog("Notes: save failed"); uiFlashShow(S("Not saved"), COL_RED); }
  return ok;
}

// Also gets the notes their memory, the first time. A file this firmware does
// not know leaves the list empty; a cut-off file keeps every note that
// arrived whole.
function notesLoad() {
  noteCount = 0;
  if (!noteList) {
    noteList  = arrOf(NoteRec, NOTES_MAX);
    noteLines = arr2(Uint8Array, u32(NOTE_MAX_LINES), 48);
    if (!noteList || !noteLines) {
      free(noteList); free(noteLines);
      noteList = null; noteLines = null;
      pxlog("Notes: no memory for them");
      return;
    }
  }
  if (!fsReady) return;
  // Only the temp file there: notesSave() was cut off between removing the
  // old file and renaming the new one. The temp is the newer save - put it in
  // place. (A temp cut off mid-write still loads every note that is whole.)
  let tmp = jstr(PATH_NOTES) + ".tmp";
  if (!LittleFS.exists(PATH_NOTES) && LittleFS.exists(tmp)) {
    LittleFS.rename(tmp, jstr(PATH_NOTES));
    pxlog("Notes: put back the last save from its temp file");
  }
  if (!LittleFS.exists(PATH_NOTES)) return;
  let f = LittleFS.open(PATH_NOTES, S("r"));
  if (!f.valid()) return;
  let h = new NotesHeader();
  if (f.read(h, 8 /*sizeof(h)*/) != 8 /*sizeof(h)*/
      || h.magic != NOTES_MAGIC || h.version != NOTES_VERSION) {
    f.close();
    pxlog("Notes: not a notes file this firmware knows - starting empty");
    return;
  }
  let n = (h.count > NOTES_MAX) ? NOTES_MAX : h.count;
  while (noteCount < n) {
    let r = noteList[noteCount];
    let len = 0;
    memset(r, 0, 1041 /*sizeof(r)*/);
    if (f.read(r.title, NOTE_TITLE_LEN) != NOTE_TITLE_LEN) break;
    if (f.read(view(ref(() => len, v => len = u16(v), 'u16'), Uint8Array), 2) != 2 || len > NOTE_BODY_LEN - 1) break;
    if (len > 0 && f.read(r.body, len) != len) break;
    r.title[NOTE_TITLE_LEN - 1] = 0;
    noteCount++;                       // only a note that arrived whole counts
  }
  f.close();
}

// A new note goes to the end of the list, as in the app. Its place, or -1.
function notesAdd(title, body) {
  if (!noteList || noteCount >= NOTES_MAX) return -1;
  noteSetText(noteList[noteCount].title, NOTE_TITLE_LEN, title);
  noteSetText(noteList[noteCount].body,  NOTE_BODY_LEN,  body);
  noteCount++;
  notesSave();
  return noteCount - 1;
}

function notesDelete(idx) {
  if (!noteList || idx < 0 || idx >= noteCount) return false;
  memmove(recPtr(noteList, idx), recPtr(noteList, idx + 1), u32(Math.imul(u32((noteCount - idx - 1)), 1041 /*sizeof NoteRec*/)));
  noteCount--;
  memset(recPtr(noteList, noteCount), 0, 1041 /*sizeof NoteRec*/);
  return notesSave();
}

// ==================== CALENDAR: storage ====================
// /calendar.dat: a header, then every special date (month, day, the name's
// length, the name), then every reminder (year low and high byte, month, day,
// length, text) - each only as long as it is, like the notes. At most about
// 17 KB. Written whole to a temp file that then replaces the old one, the
// notes' way (see notesSave()).
const CAL_MAGIC = 0x50585043;  // "PXPC"
const CAL_VERSION = 1;

class CalHeader {
  constructor() {
    this.magic = 0;
    this.version = 0;
    this.specs = 0;
    this.rems = 0;
    this.spare = 0;
  }
}
CalHeader.$f = [['magic', 'u32', 0], ['version', 'u16', 4], ['specs', 'u16', 6], ['rems', 'u16', 8], ['spare', 'u16', 10]];
CalHeader.$size = 12;

function calSave() {
  if (!fsReady || !calRems || !calSpecs) return false;
  let h = new CalHeader();
  h.magic = CAL_MAGIC; h.version = CAL_VERSION;
  h.specs = u16(calSpecCount); h.rems = u16(calRemCount); h.spare = 0;
  let need = 12 /*sizeof(h)*/;
  for (let i = 0; i < calSpecCount; i++) need = u32(need + (u32(3 + strlen(calSpecs[i].name))));
  for (let i = 0; i < calRemCount; i++)  need = u32(need + (u32(5 + strlen(calRems[i].text))));
  let slow = (need > 16384);    // like the notes: say so before a long write
  if (slow) { busyText = S("Saving..."); renderInner(true); }
  let tmp = jstr(PATH_CALENDAR) + ".tmp";
  let f = LittleFS.open(tmp, S("w"));
  let ok = false;
  if (f.valid()) {
    let wrote = f.write(h, 12 /*sizeof(h)*/);
    for (let i = 0; i < calSpecCount; i++) {
      let len = u8(strlen(calSpecs[i].name));
      let rec = new Uint8Array([ calSpecs[i].m, calSpecs[i].d, len ]);
      wrote = u32(wrote + f.write(rec, 3));
      if (len > 0) wrote = u32(wrote + f.write(calSpecs[i].name, len));
    }
    for (let i = 0; i < calRemCount; i++) {
      let len = u8(strlen(calRems[i].text));
      let rec = new Uint8Array([ u8((calRems[i].y & 0xFF)), u8((calRems[i].y >> 8)),
                         calRems[i].m, calRems[i].d, len ]);
      wrote = u32(wrote + f.write(rec, 5));
      if (len > 0) wrote = u32(wrote + f.write(calRems[i].text, len));
    }
    f.close();
    ok = (wrote == need);
    if (!ok) LittleFS.remove(tmp);
  }
  if (ok) {
    ok = LittleFS.rename(tmp, jstr(PATH_CALENDAR));        // straight over the old one
    if (!ok) {
      LittleFS.remove(PATH_CALENDAR);
      ok = LittleFS.rename(tmp, jstr(PATH_CALENDAR));
    }
  }
  if (slow) busyText = null;
  if (!ok) { pxlog("Calendar: save failed"); uiFlashShow(S("Not saved"), COL_RED); }
  return ok;
}

// Also gets the calendar its memory, the first time. A file this firmware
// does not know leaves it empty; a cut-off file keeps every entry that
// arrived whole (the special dates come first in the file).
function calLoad() {
  calRemCount = 0; calSpecCount = 0;
  if (!calRems) {
    calRems  = arrOf(CalRem, CAL_REMS_MAX);
    calSpecs = arrOf(CalSpec, CAL_SPECS_MAX);
    if (!calRems || !calSpecs) {
      free(calRems); free(calSpecs);
      calRems = null; calSpecs = null;
      pxlog("Calendar: no memory for it");
      return;
    }
  }
  if (!fsReady) return;
  let tmp = jstr(PATH_CALENDAR) + ".tmp";
  if (!LittleFS.exists(PATH_CALENDAR) && LittleFS.exists(tmp)) {   // see notesLoad()
    LittleFS.rename(tmp, jstr(PATH_CALENDAR));
    pxlog("Calendar: put back the last save from its temp file");
  }
  if (!LittleFS.exists(PATH_CALENDAR)) return;
  let f = LittleFS.open(PATH_CALENDAR, S("r"));
  if (!f.valid()) return;
  let h = new CalHeader();
  if (f.read(h, 12 /*sizeof(h)*/) != 12 /*sizeof(h)*/ || h.magic != CAL_MAGIC
      || h.version != CAL_VERSION || h.specs > CAL_SPECS_MAX || h.rems > CAL_REMS_MAX) {
    f.close();
    pxlog("Calendar: not a calendar file this firmware knows - starting empty");
    return;
  }
  let whole = true;
  while (whole && calSpecCount < h.specs) {
    let s = calSpecs[calSpecCount];
    let rec = new Uint8Array(3);
    memset(s, 0, 42 /*sizeof(s)*/);
    if (f.read(rec, 3) != 3 || rec[0] < 1 || rec[0] > 12 || rec[1] < 1 || rec[1] > 31
        || rec[2] > CAL_SPEC_LEN - 1
        || (rec[2] > 0 && f.read(s.name, rec[2]) != rec[2])) { whole = false; break; }
    s.m = rec[0]; s.d = rec[1];
    calSpecCount++;
  }
  while (whole && calRemCount < h.rems) {
    let r = calRems[calRemCount];
    let rec = new Uint8Array(5);
    memset(r, 0, 66 /*sizeof(r)*/);
    if (f.read(rec, 5) != 5 || rec[2] < 1 || rec[2] > 12 || rec[3] < 1 || rec[3] > 31
        || rec[4] > CAL_REM_LEN - 1
        || (rec[4] > 0 && f.read(r.text, rec[4]) != rec[4])) { whole = false; break; }
    r.y = u16((rec[0] | (rec[1] << 8))); r.m = rec[2]; r.d = rec[3];
    calRemCount++;
  }
  f.close();
}

// A new reminder for y-m-d goes to the end, as in the app. Its place, or -1.
function calAddRem(y, m, d, text) {
  if (!calRems || calRemCount >= CAL_REMS_MAX) return -1;
  let r = calRems[calRemCount];
  r.y = u16(y); r.m = u8(m); r.d = u8(d);
  noteSetText(r.text, CAL_REM_LEN, text);       // trimmed and cut to fit, like a note
  calRemCount++;
  calSave();
  return calRemCount - 1;
}

// A new special date for every year's m-d. Its place, or -1.
function calAddSpec(m, d, name) {
  if (!calSpecs || calSpecCount >= CAL_SPECS_MAX) return -1;
  let s = calSpecs[calSpecCount];
  s.m = u8(m); s.d = u8(d);
  noteSetText(s.name, CAL_SPEC_LEN, name);
  calSpecCount++;
  calSave();
  return calSpecCount - 1;
}

// kind: 0 = a reminder, 1 = a special date.
function calDeleteEntry(kind, idx) {
  if (kind == 1) {
    if (!calSpecs || idx < 0 || idx >= calSpecCount) return false;
    memmove(recPtr(calSpecs, idx), recPtr(calSpecs, idx + 1), u32(Math.imul(u32((calSpecCount - idx - 1)), 42 /*sizeof CalSpec*/)));
    calSpecCount--;
    memset(recPtr(calSpecs, calSpecCount), 0, 42 /*sizeof CalSpec*/);
  } else {
    if (!calRems || idx < 0 || idx >= calRemCount) return false;
    memmove(recPtr(calRems, idx), recPtr(calRems, idx + 1), u32(Math.imul(u32((calRemCount - idx - 1)), 66 /*sizeof CalRem*/)));
    calRemCount--;
    memset(recPtr(calRems, calRemCount), 0, 66 /*sizeof CalRem*/);
  }
  return calSave();
}

// ==================== ALARMS: storage ====================
// /alarms.dat: a header, then every alarm in 39 bytes - hour, minute, day, on,
// the one-time moment (4 bytes, low byte first) and the 31-byte label. Under
// 1.2 KB. Written whole to a temp file that then replaces the old one, the
// notes' way (see notesSave()).
const ALARM_MAGIC = 0x50585041;  // "PXPA"
const ALARM_VERSION = 1;
const ALARM_REC_BYTES = (8 + ALARM_LABEL_LEN);

class AlarmHeader {
  constructor() {
    this.magic = 0;
    this.version = 0;
    this.count = 0;
  }
}
AlarmHeader.$f = [['magic', 'u32', 0], ['version', 'u16', 4], ['count', 'u16', 6]];
AlarmHeader.$size = 8;

function alarmsSave() {
  if (!fsReady) return false;
  let h = new AlarmHeader();
  h.magic = ALARM_MAGIC; h.version = ALARM_VERSION; h.count = u16(alarmCount);
  let tmp = jstr(PATH_ALARMS) + ".tmp";
  let f = LittleFS.open(tmp, S("w"));
  let ok = false;
  if (f.valid()) {
    let need = u32(8 /*sizeof(h)*/ + u32(Math.imul(u32(alarmCount), u32(ALARM_REC_BYTES))));
    let wrote = f.write(h, 8 /*sizeof(h)*/);
    for (let i = 0; i < alarmCount; i++) {
      let rec = new Uint8Array(39);
      memset(rec, 0, rec.length);
      rec[0] = alarmList[i].hour; rec[1] = alarmList[i].minute;
      rec[2] = alarmList[i].day;  rec[3] = alarmList[i].on;
      let at = alarmList[i].at;
      rec[4] = u32(at & 0xFF); rec[5] = u32((at >>> 8) & 0xFF); rec[6] = u32((at >>> 16) & 0xFF); rec[7] = u32((at >>> 24) & 0xFF);
      memcpy(ptrAdd(rec, 8), alarmList[i].label, u32(ALARM_LABEL_LEN - 1));
      wrote = u32(wrote + f.write(rec, rec.length));
    }
    f.close();
    ok = (wrote == need);
    if (!ok) LittleFS.remove(tmp);
  }
  if (ok) {
    ok = LittleFS.rename(tmp, jstr(PATH_ALARMS));          // straight over the old one
    if (!ok) {
      LittleFS.remove(PATH_ALARMS);
      ok = LittleFS.rename(tmp, jstr(PATH_ALARMS));
    }
  }
  if (!ok) { pxlog("Alarms: save failed"); uiFlashShow(S("Not saved"), COL_RED); }
  return ok;
}

// The list order: the clock's - hour, minute, then the day (one-time first,
// then Monday .. Sunday), like the app's list. A number per alarm, so the sort
// compares plain longs.
function alarmKey(i) {
  return alarmList[i].hour * 1000 + alarmList[i].minute * 10 + alarmList[i].day;
}

// Puts the list back in that order. Returns where alarm `follow` went, so the
// highlight can go with it (-1 stays -1).
function alarmsSort(follow) {
  for (let i = 1; i < alarmCount; i++) {
    for (let j = i; j > 0 && alarmKey(j) < alarmKey(j - 1); j--) {
      let t = clone(alarmList[j]); assign(alarmList[j], alarmList[j - 1]); assign(alarmList[j - 1], t);
      if (follow == j) follow = j - 1;
      else if (follow == j - 1) follow = j;
    }
  }
  return follow;
}

// A file this firmware does not know leaves the list empty; a cut-off file
// keeps every alarm that arrived whole; a record that makes no sense is skipped.
function alarmsLoad() {
  alarmCount = 0;
  if (!fsReady) return;
  let tmp = jstr(PATH_ALARMS) + ".tmp";
  if (!LittleFS.exists(PATH_ALARMS) && LittleFS.exists(tmp)) {   // see notesLoad()
    LittleFS.rename(tmp, jstr(PATH_ALARMS));
    pxlog("Alarms: put back the last save from its temp file");
  }
  if (!LittleFS.exists(PATH_ALARMS)) return;
  let f = LittleFS.open(PATH_ALARMS, S("r"));
  if (!f.valid()) return;
  let h = new AlarmHeader();
  if (f.read(h, 8 /*sizeof(h)*/) != 8 /*sizeof(h)*/ || h.magic != ALARM_MAGIC
      || h.version != ALARM_VERSION || h.count > ALARMS_MAX) {
    f.close();
    pxlog("Alarms: not an alarm file this firmware knows - starting empty");
    return;
  }
  for (let r = 0; r < h.count; r++) {
    let rec = new Uint8Array(39);
    if (f.read(rec, rec.length) != rec.length) break;
    if (rec[0] > 23 || rec[1] > 59 || rec[2] > 7) continue;
    let a = alarmList[alarmCount];
    memset(a, 0, 40 /*sizeof(a)*/);
    a.hour = rec[0]; a.minute = rec[1]; a.day = rec[2]; a.on = u8(rec[3] ? 1 : 0);
    a.at = u32(u32(u32(rec[4] | (u32(rec[5] << 8))) | (u32(rec[6] << 16))) | (u32(rec[7] << 24)));
    memcpy(a.label, ptrAdd(rec, 8), u32(ALARM_LABEL_LEN - 1));
    a.label[ALARM_LABEL_LEN - 1] = 0;
    alarmCount++;
  }
  f.close();
  alarmsSort(-1);
}

// A new alarm, switched on, in its place in the list. Returns that place, or
// -1 when the list is full. Saves.
function alarmsAdd(hour, minute, day, label, at) {
  if (alarmCount >= ALARMS_MAX) return -1;
  let a = alarmList[alarmCount];
  memset(a, 0, 40 /*sizeof(a)*/);
  a.hour = u8(hour); a.minute = u8(minute); a.day = u8(day); a.on = 1; a.at = at;
  noteSetText(a.label, ALARM_LABEL_LEN, label);    // trimmed and cut to fit, like a note
  alarmCount++;
  let at2 = alarmsSort(alarmCount - 1);
  alarmsSave();
  return at2;
}

// True when it was there to remove (a failed save says "Not saved" itself).
function alarmsDelete(idx) {
  if (idx < 0 || idx >= alarmCount) return false;
  memmove(recPtr(alarmList, idx), recPtr(alarmList, idx + 1), u32(Math.imul(u32((alarmCount - idx - 1)), 40 /*sizeof AlarmRec*/)));
  alarmCount--;
  memset(recPtr(alarmList, alarmCount), 0, 40 /*sizeof AlarmRec*/);
  alarmsSave();
  return true;
}

function storageBegin() {
  // true = format automatically if the partition has never been used
  if (!LittleFS.begin(true)) {
    fsReady = false;
    Serial.println(S("[ERR] LittleFS mount FAILED - is partitions.csv being used?"));
    return;
  }
  fsReady = true;
  Serial.printf(S("[HW] Storage OK: %u KB used of %u KB\n"),
                u32((Math.trunc(LittleFS.usedBytes() / 1024))),
                u32((Math.trunc(LittleFS.totalBytes() / 1024))));

  settingsLoad();
  settings.bootCount = u32(settings.bootCount + 1);          // every boot bumps this and writes it back
  // Debug boxes always start OFF - the screen and Settings > About agree.
  // This used to copy the saved ON into debugMode, and then osInit() set it
  // false a moment later, so About said ON over a screen with no boxes.
  settings.debugMode = 0;
  settingsSave();
  debugMode = false;
  themeApply(settings.themeIx);  // before the boot screen draws its first pixel

  contactsLoad();
  if (contactCount == 0) {       // first ever run: seed a few so there's something to see
    contactsAdd(S("Mom"),  S("+36701234567"));
    contactsAdd(S("Anna"), S("+36209876543"));
    contactsAdd(S("Pizza Place"), S("+3612345678"));
    Serial.println(S("[HW] Seeded 3 starter contacts"));
  }
  Serial.printf(S("[HW] Boot #%u, %d contacts loaded\n"),
                settings.bootCount, contactCount);

  messagesLoad();
  Serial.printf(S("[HW] %d messages loaded\n"), messageCount);

  callLogLoad();
  Serial.printf(S("[HW] %d call log entries loaded\n"), callLogCount);

  notesLoad();
  Serial.printf(S("[HW] %d notes loaded\n"), noteCount);

  calLoad();
  Serial.printf(S("[HW] Calendar: %d reminders, %d special dates loaded\n"), calRemCount, calSpecCount);

  alarmsLoad();
  Serial.printf(S("[HW] %d alarms loaded\n"), alarmCount);

  tunesLoad();                   // your own ringtones (12 Nov)
  Serial.printf(S("[HW] %d ringtones of your own loaded\n"), ownCount());

  gamesLoad();                   // the games' records (12 Nov) - it logs them itself
}

// ==================== SD CARD ====================
// Removable, so nothing may be there. Every caller must cope with sdReady being
// false - that's the "please insert SD card" behaviour, same as a real camera.

function sdUnmount() {
  if (sdReady) { SD.end(); sdReady = false; }
  sdSizeMB = 0; sdUsedMB = 0;
}

function sdMount() {
  sdSPI.begin(SD_SCK, SD_MISO, SD_MOSI, SD_CS);
  if (!SD.begin(SD_CS, sdSPI, SD_SPEED)) return false;
  if (SD.cardType() == CARD_NONE) { SD.end(); return false; }
  sdReady  = true;
  sdCardPresent = true;
  sdSizeMB = u32((Math.trunc(SD.cardSize() / (1024 * 1024))));
  sdUsedMB = u32((Math.trunc(SD.usedBytes() / (1024 * 1024))));
  if (!SD.exists(S("/DCIM"))) SD.mkdir(S("/DCIM"));   // photos, camera convention
  if (!SD.exists(S("/MUSIC"))) SD.mkdir(S("/MUSIC"));
  if (!SD.exists(S("/VOICE"))) SD.mkdir(S("/VOICE"));  // voice memos
  return true;
}

// Writes a file, reads it back, compares. Proves the wiring end to end rather
// than just proving the card answered.
function sdSelfTest() {
  if (!sdReady) return false;
  let path = S("/pxp_test.txt");
  let mark = S("PxP Flip SD write test");
  let f = SD.open(path, FILE_WRITE);
  if (!f.valid()) { Serial.println(S("[ERR] SD: open for write failed")); return false; }
  f.println(mark);
  f.close();

  f = SD.open(path, FILE_READ);
  if (!f.valid()) { Serial.println(S("[ERR] SD: open for read failed")); return false; }
  let back = f.readStringUntil(ch('\n'));
  f.close();
  SD.remove(path);

  back = strTrim(back);
  let ok = (back == jstr(mark));
  Serial.printf(S("[HW] SD self-test: %s\n"), ok ? S("PASS (wrote and read back)") : S("FAIL (data mismatch)"));
  return ok;
}

function sdBegin() {
  if (sdMount()) {
    Serial.printf(S("[HW] SD card OK: %u MB card, %u MB used\n"),
                  sdSizeMB, sdUsedMB);
    sdSelfTest();
  } else {
    Serial.println(S("[HW] No SD card on first try - running diagnostic"));
    sdDiagnose();          // releases the SPI bus when it finishes
    // Second attempt at the SD spec's slow init speed. Long breadboard wires
    // often work at 400 kHz when they fail at 4 MHz.
    delay(50);
    sdSPI.begin(SD_SCK, SD_MISO, SD_MOSI, SD_CS);
    if (SD.begin(SD_CS, sdSPI, 400000) && SD.cardType() != CARD_NONE) {
      sdReady  = true;
      sdSizeMB = u32((Math.trunc(SD.cardSize() / (1024 * 1024))));
      sdUsedMB = u32((Math.trunc(SD.usedBytes() / (1024 * 1024))));
      Serial.printf(S("[HW] SD card OK at 400 kHz: %u MB (wires too long for 4 MHz)\n"),
                    sdSizeMB);
      sdSelfTest();
    }
  }
}

// Called from the loop so a card inserted later gets picked up.
function sdPoll(now) {
  if (sdReady || now < sdRetryAt) return;
  sdRetryAt = u32(now + 5000);
  if (sdMount()) {
    pxlog("SD card inserted");
    Serial.printf(S("[HW] SD card OK: %u MB\n"), sdSizeMB);
    sdSelfTest();
  }
}

// Build a child's full path. Needed because File::name() returns the FULL path
// on ESP32 core 2.x but only the BASENAME on 3.x - this copes with either.
function sdChildPath(parent, e) {
  let n = jstr(e.name());
  if (n.startsWith("/")) return n;
  let p = jstr(parent);
  if (!p.endsWith("/")) p += "/";
  return p + n;
}

let sdDeleted = 0;
let sdFailed = 0;

// Deletes everything under a directory.
// The subtlety: you must NOT delete entries while the directory is still open
// for reading. The reader keeps an internal position, and removing entries under
// it makes it skip things or stop early - which is why the old version silently
// did almost nothing. So: read a batch of names, CLOSE the directory, then
// delete. Repeat until the directory comes back empty.
function sdWipeDir(path, depth) {
  if (depth > 8) return;                 // stop runaway recursion
  const BATCH = 16;
  while (true) {
    let names = new Array(16).fill("");
    let isDir = new Uint8Array(16);
    let n = 0;

    let dir = SD.open(path);
    if (!dir.valid() || !dir.isDirectory()) { if (dir.valid()) dir.close(); return; }
    let e = dir.openNextFile();
    while (e.valid() && n < BATCH) {
      names[n] = sdChildPath(path, e);
      isDir[n] = e.isDirectory();
      n++;
      e.close();
      e = dir.openNextFile();
    }
    if (e.valid()) e.close();
    dir.close();                          // closed BEFORE anything is removed
    if (n == 0) return;                   // nothing left here

    let okThisPass = 0;
    for (let i = 0; i < n; i++) {
      let ok = false;
      if (isDir[i]) {
        sdWipeDir(cstr(names[i]), depth + 1);
        ok = SD.rmdir(cstr(names[i]));
      } else {
        ok = SD.remove(cstr(names[i]));
      }
      if (ok) { sdDeleted++; okThisPass++; }
      else {
        sdFailed++;
        if (sdFailed <= 5) pxlog("  can't delete " + names[i]);
      }
    }
    if (okThisPass == 0) return;          // making no progress: give up, don't loop forever
  }
}

// Erases the card and rebuilds the folder layout. Reports what actually
// happened instead of assuming it worked.
function sdFormat() {
  musicStop();              // nothing may read the card while it is erased (Music, 11 Nov)
  if (!sdReady) return false;
  let beforeMB = u32((Math.trunc(SD.usedBytes() / (1024 * 1024))));
  sdDeleted = 0;
  sdFailed  = 0;
  pxlog("Erasing card, this can take a while...");

  sdWipeDir(S("/"), 0);
  SD.mkdir(S("/DCIM"));
  SD.mkdir(S("/MUSIC"));
  SD.mkdir(S("/VOICE"));

  sdUsedMB = u32((Math.trunc(SD.usedBytes() / (1024 * 1024))));
  let l = new Uint8Array(96);
  snprintf(l, l.length, S("Deleted %d items, %d failed. Used %u MB -> %u MB"),
           sdDeleted, sdFailed, beforeMB, sdUsedMB);
  pxlog(jstr(l));
  if (sdFailed > 0) pxlog("Some items could not be removed (see above)");
  return sdFailed == 0;
}

// One byte in/out by hand-wiggling the pins. Deliberately NOT using the SPI
// driver: the SD library has already claimed the bus by the time we get here,
// and a second driver poking the same bus is what made this crash mid-boot.
// Bit-banging can't conflict with anything. It's slow (~125 kHz) but this is a
// diagnostic, not a data path. SPI mode 0: set MOSI low, sample MISO on rising.
function sdBitBangByte(out) {
  let in_ = 0;
  for (let i = 7; i >= 0; i--) {
    digitalWrite(SD_MOSI, (out >> i) & 1);
    delayMicroseconds(2);
    digitalWrite(SD_SCK, HIGH);
    delayMicroseconds(2);
    in_ = u8((in_ << 1) | (digitalRead(SD_MISO) & 1));
    digitalWrite(SD_SCK, LOW);
    delayMicroseconds(2);
  }
  return in_;
}

// Makes an UNMOUNTABLE card usable: SD.begin's last argument tells the driver
// "if you can't mount this, format it". That's what rescues an exFAT card, which
// the ESP cannot read at all - it uses FatFs, which only knows FAT16/FAT32.
// Deliberately NOT done automatically at boot: a transient mount failure would
// then wipe your photos. It only ever runs when you pick it from the menu.
function sdForceFormat() {
  pxlog("Formatting card to FAT32, please wait...");
  // Try several bus speeds. Too slow can time the driver out, too fast is noisy
  // on long breadboard wires - the workable window is narrow and card-specific.
  const speeds = new Uint32Array([400000, 1000000, 4000000, 10000000]);
  for (let i = 0; i < 4; i++) {
    SD.end();
    sdSPI.end();
    delay(100);
    sdSPI.begin(SD_SCK, SD_MISO, SD_MOSI, SD_CS);

    let l = new Uint8Array(72);
    snprintf(l, l.length, S("  trying %u kHz..."), (Math.trunc(speeds[i] / 1000)));
    pxlog(jstr(l));

    // last argument true = "if you can't mount it, build a fresh filesystem"
    let ok = SD.begin(SD_CS, sdSPI, speeds[i], S("/sd"), 5, true);
    let ct = u8(SD.cardType());
    snprintf(l, l.length, S("    begin=%s cardType=%d"), ok ? S("ok") : S("fail"), ct);
    pxlog(jstr(l));

    if (ok && ct != CARD_NONE) {
      sdReady = true;
      sdCardPresent = true;
      sdSizeMB = u32((Math.trunc(SD.cardSize() / (1024 * 1024))));
      sdUsedMB = u32((Math.trunc(SD.usedBytes() / (1024 * 1024))));
      SD.mkdir(S("/DCIM"));
      SD.mkdir(S("/MUSIC"));
      SD.mkdir(S("/VOICE"));
      snprintf(l, l.length, S("Card ready: %u MB FAT32 at %u kHz"),
               sdSizeMB, (Math.trunc(speeds[i] / 1000)));
      pxlog(jstr(l));
      return true;
    }
  }
  pxlog("Format failed at every speed.");
  pxlog("  cardType 0 at EVERY speed = the card never powered up enough to be");
  pxlog("  identified. Not noise (noise gets better when you slow down) and");
  pxlog("  not the format (nothing ever read the filesystem).");
  pxlog("  This module's datasheet: VCC must be 4.5-5.5V. 3.3V is too low.");
  return false;
}

// ---- A GENUINE format, not a file delete. ----
// The Arduino SD library can't do this: it never exposes the card handle, and
// its format-on-mount only fires when mounting FAILS. So we drop to the ESP-IDF
// layer, mount the card ourselves to get that handle, and call the real format.
// This rebuilds the filesystem from scratch, so it doesn't care whether files
// could be listed - which is exactly why deleting files got us nowhere.
// #include "esp_idf_version.h"
// #if ESP_IDF_VERSION >= ESP_IDF_VERSION_VAL(5, 0, 0)
  // #include "esp_vfs_fat.h"
  // #include "driver/sdspi_host.h"
  // #include "driver/spi_common.h"
  // #include "sdmmc_cmd.h"
  const PXP_TRUE_FORMAT = 1;
// #else
  // #define PXP_TRUE_FORMAT 0
// #endif

function sdTrueFormat() {
  musicStop();              // nothing may read the card while it is formatted (Music, 11 Nov)
// #if PXP_TRUE_FORMAT
  pxlog("FULL FORMAT - takes minutes, do not unplug");

  SD.end();              // hand the bus back from the Arduino layer completely
  sdSPI.end();
  sdReady = false;
  delay(200);

  let host = SDSPI_HOST_DEFAULT();
  host.slot = SPI2_HOST;
  host.max_freq_khz = 4000;          // gentle: these are breadboard wires

  let bus = mk(spi_bus_config_t);
  bus.mosi_io_num     = SD_MOSI;
  bus.miso_io_num     = SD_MISO;
  bus.sclk_io_num     = SD_SCK;
  bus.quadwp_io_num   = -1;
  bus.quadhd_io_num   = -1;
  bus.max_transfer_sz = 4092;

  let err = spi_bus_initialize(SPI2_HOST, bus, SPI_DMA_CH_AUTO);
  if (err != ESP_OK && err != ESP_ERR_INVALID_STATE) {
    pxlog("SPI bus init failed: " + jstr(esp_err_to_name(err)));
    delay(100); sdSPI.begin(SD_SCK, SD_MISO, SD_MOSI, SD_CS); sdMount(); return false;
  }

  let slot = SDSPI_DEVICE_CONFIG_DEFAULT();
  slot.gpio_cs = SD_CS;
  slot.host_id = SPI2_HOST;

  let mcfg = mk(esp_vfs_fat_mount_config_t);
  mcfg.format_if_mount_failed = true;      // also rescues an unreadable card
  mcfg.max_files              = 5;
  mcfg.allocation_unit_size   = u32(16 * 1024); // Espressif's own default

  let card = null;
  err = esp_vfs_fat_sdspi_mount(S("/sdfmt"), host, slot, mcfg, ref(() => card, v => card = v));
  if (err != ESP_OK || card == null) {
    pxlog("Mount for format failed: " + jstr(esp_err_to_name(err)));
    spi_bus_free(SPI2_HOST);
    delay(100); sdSPI.begin(SD_SCK, SD_MISO, SD_MOSI, SD_CS); sdMount(); return false;
  }

  pxlog("Card mounted, formatting now...");
  err = esp_vfs_fat_sdcard_format(S("/sdfmt"), card);
  let ok = (err == ESP_OK);
  pxlog(ok ? "Format finished OK" : "Format failed: " + jstr(esp_err_to_name(err)));

  esp_vfs_fat_sdcard_unmount(S("/sdfmt"), card);
  spi_bus_free(SPI2_HOST);
  delay(300);

  // Hand it back to the Arduino layer so the rest of the OS keeps working.
  sdSPI.begin(SD_SCK, SD_MISO, SD_MOSI, SD_CS);
  if (sdMount()) {
    let l = new Uint8Array(80);
    snprintf(l, l.length, S("Card ready: %u MB total, %u MB used"),
             sdSizeMB, sdUsedMB);
    pxlog(jstr(l));
  } else {
    pxlog("Formatted but could not remount - reboot the phone");
  }
  return ok;
// #else
  // pxlog("Full format needs ESP32 core 3.x - erasing files instead");
  // return sdFormat();
// #endif
}

// ==================== 4G MODEM (BK-A7670, UART AT commands) ====================
// PWRKEY and SLEEP are unconnected on purpose: this breakout ties PWRKEY to
// GND onboard (R104), so it self-powers-on the instant VCC arrives. VCC/GND
// run off a bench 5V supply for now (2A peak need - not the ESP32 or the
// battery rail; a proper 5V boost converter is a later hardware step).
const MODEM_RX = 46;  // modem TXD -> here (ESP32 receives)
const MODEM_TX = 45;  // modem RXD <- here (ESP32 transmits)
const MODEM_BAUD = 115200;

// Leave "" unless your SIM actually has a PIN. WARNING: 3 wrong PIN attempts
// permanently locks the SIM until you enter the PUK code (printed on the card
// it came on). So this is only ever tried ONCE per boot — it will NOT keep
// retrying a wrong PIN every 3 seconds and burn through your attempts.
let MODEM_PIN = S("");
let pinAttempted = false;

let modemSerial = new HardwareSerial(1);
let modemPresent = false;   // responded to plain "AT" at least once
// simReady and modemSignalCSQ now live near the top with camReady,
// since drawStatus() (defined earlier in the file) needs to see them.
let modemRegState = -1;     // raw AT+CREG? <stat> value, -1 = unknown
let modemNextPoll = 0;
let modemMisses = 0;      // consecutive "AT" probes with no reply
const MODEM_POLL_EVERY = 3000;  // ms between status polls - AT round trips aren't free

// The presence probe is the ONLY AT command that runs when there may be nothing
// to talk to, and modemSendAT() blocks until a reply arrives or the timeout
// expires. With no modem attached nothing ever arrives, so it burned the full
// 800ms default every 3000ms - 27% of the time frozen, forever.
//
// Two limits fix it. A live modem answers plain "AT" in tens of milliseconds,
// so the generous default (meant for commands like COPS that trigger a network
// scan) is pointless here. And retrying at full rate makes sense while a modem
// is booting, not after twenty failures.
//
// Every OTHER AT call only runs once the modem has already answered, i.e. when
// it is alive and fast, so none of them needed changing.
//
// The proper fix is a non-blocking modem layer - see the register. This is the
// ten-line version that takes the worst case from 27% to 0.7%.
const MODEM_AT_PROBE_MS = 200;  // "are you there" only
const MODEM_MISS_BACKOFF = 5;  // misses before slowing down
const MODEM_POLL_SLOW = 30000;  // ms between polls once we have given up hope

// ---- SMS ----
// Text mode (AT+CMGF=1) rather than PDU mode: readable, no hex/GSM-7 encoding
// to get wrong. AT+CNMI=2,2,0,0,0 tells the modem to PUSH new messages to us
// unsolicited as "+CMT: ...\r\n<body>\r\n" the instant one arrives, rather than
// making us poll AT+CMGL and hope we didn't miss one between polls.
let smsReady = false;   // AT+CMGF and AT+CNMI both confirmed set this boot

function modemBegin() {
  modemSerial.begin(MODEM_BAUD, SERIAL_8N1, MODEM_RX, MODEM_TX);
  pxlog("[Modem] UART opened on RX=46 TX=45 @115200");
}

// ---- SIM PIN/PUK entry ----
// Industry pattern, same as any AT-command modem: try the PIN, and only after
// the modem itself reports SIM PUK do we ask for the PUK. We never guess a PUK
// attempt count locally — the SIM enforces that, we just relay what it says.
//
// IMPORTANT: simPinAttempts only counts tries THIS SESSION. It resets to 0 on
// every reboot, but the SIM's own onboard counter does NOT — that lives on the
// card itself and only moves on an actual wrong/right PIN, never on a power
// cycle. So this variable must never be shown to the user as "N tries left";
// it would be confidently wrong the moment a wrong attempt happened in an
// earlier session. It's kept only to decide when to stop auto-prompting.
let simPinAttempts = 0;      // this session only, resets on reboot
let simPendingPuk = cbuf(16, "");
let simFlash = cbuf(40, "");
let simFlashUntil = 0;

// Set by simTextCommit() when it has already put a screen up of its own (a
// retry field, or the "New PIN" second step). textEditCommit() checks it and
// leaves that screen alone instead of resetting to ST_HOME underneath it.
let simTookScreen = false;

// Settings > Security (11 Nov): what the PIN field turns the SIM PIN to - 0 off,
// 1 on - and Change PIN's codes, kept between its steps and wiped after.
let simLockWant = 0;
let simOldPin = cbuf(12, "");
let simNewPin = cbuf(12, "");

// GSM 02.17 section 5.6: a SIM PIN is 4 to 8 digits, a PUK is always 8.
// Enforced in the editor, so a wrong length can never reach the modem and
// "PIN too short" never has to be a message anyone reads.
// Settings > Security's own PIN fields (11 Nov): the SIM PIN on or off, and
// Change PIN's three steps. PIN fields like the start-up ones, but these can be
// left.
function simSettingsField(owner) {
  return owner == TXT_SIM_LOCK || owner == TXT_SIM_OLDPIN
      || owner == TXT_SIM_CHGNEW || owner == TXT_SIM_CHGAGAIN;
}

function simCodeMin(owner) {
  if (owner == TXT_SIM_PUK) return 8;
  if (owner == TXT_SIM_PIN || owner == TXT_SIM_NEWPIN) return 4;
  if (simSettingsField(owner)) return 4;    // Settings > Security's (11 Nov)
  return 0;                                 // every other field: no minimum
}
function simCodeMax(owner) {
  if (owner == TXT_SIM_PUK) return 8;
  if (owner == TXT_SIM_PIN || owner == TXT_SIM_NEWPIN) return 8;
  if (simSettingsField(owner)) return 8;
  return TEXT_FIELD_MAX;                    // every other field: 160, as before Notes
}

// The most letters a field takes. TEXT_MAX is only the buffer, sized for the
// longest field; every field from before Notes keeps its 160 (an SMS is 160).
function textFieldMax(owner) {
  if (owner == TXT_NOTE_BODY)  return NOTE_BODY_LEN - 1;    // 1000
  if (owner == TXT_NOTE_TITLE) return NOTE_TITLE_LEN - 1;   // 39
  if (owner == TXT_CAL_REM)    return CAL_REM_LEN - 1;      // 60
  if (owner == TXT_CAL_SPEC)   return CAL_SPEC_LEN - 1;     // 39
  if (owner == TXT_ALARM_LABEL) return ALARM_LABEL_LEN - 1; // 30
  if (owner == TXT_FILES_RENAME || owner == TXT_FILES_NEWDIR) return 60;   // a file or folder's name
  if (owner == TXT_RT_NAME) return OWN_NAME_LEN - 1;          // your own ringtone's name: 16 (12 Nov)
  return simCodeMax(owner);                                 // 8 for a PIN or PUK, else 160
}

// The long fields: a message and a note's text. Smaller letters, more lines,
// a counter, and up/down move a line.
function textIsLongField() {
  return textOwner == TXT_MSG_BODY || textOwner == TXT_NOTE_BODY;
}

// ---- the editor's lines, words kept whole (the owner, 8 Nov) ----
// The editor used to cut its text every 18 letters wherever that fell - "ch /
// ip", lines starting with a space. Now a line breaks after the last space
// that lets it fit TEXT_LONG_PER_LINE letters; a space landing just past the
// edge hangs there, unseen; only a word longer than a whole line is cut, at
// the edge. Every field, short and long. Nothing is stored: each caller walks
// the lines from the start (a 1000-letter note is a few hundred steps).

// Where the next line starts after the one starting at s (textLen: no more).
function textLineEnd(s) {
  const W = TEXT_LONG_PER_LINE;
  // A line break (a note's text, 11 Nov) ends the line there; the next one
  // starts after it. A text without one breaks exactly as before.
  for (let i = s; i < textLen && i <= s + W; i++)
    if (textBuf[i] == ch('\n')) return i + 1;
  if (textLen - s <= W) return textLen;
  for (let i = s + W; i > s; i--)
    if (textBuf[i] == ch(' ')) return i + 1;
  return s + W;
}

// How many lines the text takes, and the cursor's line and column. A space
// hanging off the end of the text - or a line break ending it (11 Nov) - puts
// the cursor on a new, empty line, where the next letter will go.
function textLayout(cursorLine, cursorCol) {
  let n = 0, s = 0;
  cursorLine[0] = 0; cursorCol[0] = textCursor;
  while (true) {
    let e = textLineEnd(s);
    let last = (e >= textLen);
    let hangsOff = last && (e - s > TEXT_LONG_PER_LINE || (e > s && textBuf[e - 1] == ch('\n')));
    if (textCursor >= s && (textCursor < e || (last && !hangsOff))) {
      cursorLine[0] = n; cursorCol[0] = textCursor - s;
    }
    n++;
    if (last) {
      if (hangsOff) {
        if (textCursor == textLen) { cursorLine[0] = n; cursorCol[0] = 0; }
        n++;
      }
      return n;
    }
    s = e;
  }
}

// Where line n starts (textLen for the empty line after a hanging space).
function textLineStart(n) {
  let s = 0;
  for (let k = 0; k < n && s < textLen; k++) s = textLineEnd(s);
  return s;
}

function networkRegistered() { return modemRegState == 1 || modemRegState == 5; } // home / roaming

function simSetFlash(msg) {
  strncpy(simFlash, msg, u32(simFlash.length - 1));
  simFlash[simFlash.length - 1] = 0;
  simFlashUntil = u32(millis() + 2500);
  pxlog("[SIM] " + jstr(msg));
}

function simPromptPin() { textEditOpen(S("Enter PIN"), S(""), TXT_SIM_PIN, true, true); }
function simPromptPuk() { textEditOpen(S("Enter PUK"), S(""), TXT_SIM_PUK, true, true); }

// "Wrong PIN - 2 left": the tries the SIM itself still allows, read with
// AT+SPIC (A7670 manual 6.2.8: "+SPIC: <pin1>,<puk1>,<pin2>,<puk2>"). The count
// lives ON THE CARD, so it stays right across a restart or in another phone,
// and reading it spends no try. simPinAttempts (this boot only) is never
// shown, for exactly that reason. which: 0 = the PIN, 1 = the PUK. If the SIM
// does not answer, the message stays plain - never a guess.
function simFlashWrong(what, which) {
  let left = -1;
  let r = modemSendAT("AT+SPIC", 1000);
  let p = r.indexOf("+SPIC:", );
  if (p >= 0) {
    let a = p + 6;
    if (which == 1) { let c = r.indexOf(String.fromCharCode(ch(',')), u32(a)); a = (c >= 0) ? c + 1 : -1; }
    if (a >= 0) {
      let f = r.substring(u32(a));
      f = strTrim(f);
      if (f.length > 0 && charAt(f, 0) >= ch('0') && charAt(f, 0) <= ch('9')) left = strToInt(f);
    }
  }
  let m = new Uint8Array(40);
  if (left >= 0) snprintf(m, m.length, S("%s - %d left"), what, left);
  else           snprintf(m, m.length, S("%s"), what);
  simSetFlash(m);
}

// ==================== Settings > Security: the SIM PIN (11 Nov) ====================
// "SIM PIN" turns the card's PIN request on or off; "Change PIN" changes the PIN.
// The A76XX manual: AT+CLCK="SC",<mode>,"<PIN>" - mode 0 off, 1 on, 2 asks
// ("+CLCK: 0" / "+CLCK: 1") - and AT+CPWD="SC","<old>","<new>". Both want the
// PIN, and a wrong one costs one of the card's tries, the same tries as at
// start; either may take up to 9 s. The fields are the start-up PIN screen, but
// these can be left: Back on an empty one goes one step back, the red key out.

// Wipes the codes Change PIN keeps between its steps.
function simPinWipe() {
  memset(simOldPin, 0, simOldPin.length);
  memset(simNewPin, 0, simNewPin.length);
}

// Back to the Security page from its PIN fields - done, left, or the card gone.
// What was typed is wiped too.
function simBackToSecurity() {
  simPinWipe();
  symbolPickerOpen = false;
  memset(textBuf, 0, textBuf.length);
  textLen = 0;
  textCursor = 0;
  textOwner = TXT_NONE;
  state = ST_SETPAGE;
  renderInner();
}

// Back on an empty field: one step back (the owner's rule for Back). Change
// PIN's new PIN goes back to the current one and "New PIN again" to the new
// one, each still typed in; a first field goes back to the page. False for
// every other field.
function simSettingsBack(owner) {
  if (owner == TXT_SIM_CHGNEW)   { textEditOpen(S("Current PIN"), simOldPin, TXT_SIM_OLDPIN, true, true); return true; }
  if (owner == TXT_SIM_CHGAGAIN) { textEditOpen(S("New PIN"), simNewPin, TXT_SIM_CHGNEW, true, true);      return true; }
  if (owner == TXT_SIM_LOCK || owner == TXT_SIM_OLDPIN) { simBackToSecurity(); return true; }
  return false;
}

// The small line under a field's title saying what it is for, or nullptr.
function simFieldHint(owner) {
  if (owner == TXT_SIM_LOCK)   return simLockWant ? S("to turn the SIM PIN on") : S("to turn the SIM PIN off");
  if (owner == TXT_SIM_CHGNEW) return S("4 to 8 digits");
  return null;
}

// Asks the card whether it wants its PIN at start: simPinLock 1 or 0 - or -1
// with no modem, a card that is not ready, or no answer. Spends no try. The
// modem says the command back first (its echo is on), so only "+CLCK:" is read.
function simPinLockRead() {
  simPinLock = -1;
  if (!modemPresent || !simReady) return;
  let r = modemSendAT("AT+CLCK=\"SC\",2", 3000);
  let p = r.indexOf("+CLCK:", );
  if (p < 0) return;
  let f = r.substring(u32(p + 6));
  f = strTrim(f);
  if (f.length > 0 && (charAt(f, 0) == ch('0') || charAt(f, 0) == ch('1'))) simPinLock = charAt(f, 0) - ch('0');
}

// OK on "SIM PIN": its PIN, to turn it off - or on.
function simLockStart() {
  if (simPinLock < 0) simPinLockRead();          // not known yet: ask once more
  if (simPinLock < 0) { uiFlashShow(S("SIM not answering"), COL_RED); return; }
  simLockWant = simPinLock ? 0 : 1;
  uiFlashUntil = 0;                              // nothing left over from before on the field
  simFlashUntil = 0;
  textEditOpen(S("Enter PIN"), S(""), TXT_SIM_LOCK, true, true);
}

// OK on "Change PIN" (greyed while the PIN is off): step 1 of 3.
function simChangeStart() {
  simPinWipe();
  uiFlashUntil = 0;
  simFlashUntil = 0;
  textEditOpen(S("Current PIN"), S(""), TXT_SIM_OLDPIN, true, true);
}

// The card did not take a PIN. Blocked - a third wrong one: straight to the
// start-up PUK field, as when that happens at start. Gone, or no longer ready:
// back to the page. Otherwise a wrong PIN, with the tries the card still
// allows. True when it put up the PUK field or the page; false: the caller
// asks for the PIN again.
function simSettingsRefused() {
  let cpin = modemSendAT("AT+CPIN?", 1000);
  if (cpin.indexOf("+CPIN: SIM PUK", ) >= 0) {
    simPinWipe();
    simState = SIM_NEEDS_PUK;
    simReady = false;
    simPinLock = -1;
    simSetFlash(S("SIM blocked"));
    simPromptPuk();
    return true;
  }
  if (cpin.indexOf("+CPIN: READY", ) < 0) {
    simPinLock = -1;
    uiFlashShow(S("SIM not ready"), COL_RED);
    simBackToSecurity();
    return true;
  }
  simFlashWrong(S("Wrong PIN"), 0);
  return false;
}

// OK on one of these fields; false for every other field. Each way out puts up
// a screen of its own - the page, a field, the PUK field - so simTookScreen.
function simSettingsCommit(owner, value) {
  if (!simSettingsField(owner)) return false;
  simTookScreen = true;
  if (owner == TXT_SIM_OLDPIN) {                 // step 1: kept until the card has it
    strncpy(simOldPin, value, u32(simOldPin.length - 1));
    simOldPin[simOldPin.length - 1] = 0;
    textEditOpen(S("New PIN"), S(""), TXT_SIM_CHGNEW, true, true);
    return true;
  }
  if (owner == TXT_SIM_CHGNEW) {                 // step 2
    strncpy(simNewPin, value, u32(simNewPin.length - 1));
    simNewPin[simNewPin.length - 1] = 0;
    textEditOpen(S("New PIN again"), S(""), TXT_SIM_CHGAGAIN, true, true);
    return true;
  }
  if (owner == TXT_SIM_CHGAGAIN && strcmp(value, simNewPin) != 0) {
    // Not the same: the new one again, from its start - which of the two was
    // mistyped cannot be known.
    memset(simNewPin, 0, simNewPin.length);
    simSetFlash(S("PINs don't match"));
    textEditOpen(S("New PIN"), S(""), TXT_SIM_CHGNEW, true, true);
    return true;
  }
  // To the card: the SIM PIN off or on, or the PIN changed.
  let lock = (owner == TXT_SIM_LOCK);
  let cmd = new Uint8Array(48);
  if (lock) snprintf(cmd, cmd.length, S("AT+CLCK=\"SC\",%d,\"%s\""), simLockWant, value);
  else      snprintf(cmd, cmd.length, S("AT+CPWD=\"SC\",\"%s\",\"%s\""), simOldPin, simNewPin);
  busyText = lock ? S("Checking PIN...") : S("Changing PIN...");
  renderInner(true);
  let r = modemSendAT(jstr(cmd), 9000);
  busyText = null;
  memset(cmd, 0, cmd.length);
  if (r.indexOf("OK", ) >= 0 && r.indexOf("ERROR", ) < 0) {
    if (lock) simPinLock = simLockWant;
    let done = lock ? (simLockWant ? S("SIM PIN on") : S("SIM PIN off")) : S("PIN changed");
    pxlog("[SIM] " + jstr(done));
    uiFlashShow(done, COL_THEME);
    simBackToSecurity();
  } else if (!simSettingsRefused()) {
    // A wrong PIN: that field again. Change PIN starts over at its step 1 -
    // the current PIN was the one the card did not take.
    simPinWipe();
    if (lock) textEditOpen(S("Enter PIN"), S(""), TXT_SIM_LOCK, true, true);
    else      textEditOpen(S("Current PIN"), S(""), TXT_SIM_OLDPIN, true, true);
  }
  return true;
}

// Called from textEditCommit(). Returns true if it handled the field.
function simTextCommit(owner, value) {
  if (simSettingsCommit(owner, value)) return true;   // Settings > Security's fields (11 Nov)
  if (owner == TXT_SIM_PIN) {
    // Length is enforced by the editor, so a short PIN cannot arrive here.
    simPinAttempts++;
    modemSendAT("AT+CPIN=\"" + jstr(value) + "\"", 3000);
    delay(300);                                   // let the SIM settle before re-checking
    let cpin = modemSendAT("AT+CPIN?");
    if (cpin.indexOf("+CPIN: READY", ) >= 0) {
      simState = SIM_READY_ST; simReady = true; simPinAttempts = 0;
      simFlashUntil = 0;            // no stale "Wrong PIN" left on the way out
      pxlog("[SIM] PIN accepted");  // log only - success needs no flash
    } else if (cpin.indexOf("+CPIN: SIM PUK", ) >= 0) {
      simState = SIM_NEEDS_PUK;
      simSetFlash(S("SIM blocked"));
      simPromptPuk();               // straight to the PUK field. The old popup's
      simTookScreen = true;         // "Not now" was a one-tap route to an open phone
    } else {
      // Straight back to an empty field. Dropping to the home screen reads as
      // having been let in, and leaves no way to try again.
      simFlashWrong(S("Wrong PIN"), 0);
      simPromptPin();
      simTookScreen = true;
    }
    return true;
  }
  if (owner == TXT_SIM_PUK) {
    strncpy(simPendingPuk, value, u32(simPendingPuk.length - 1));
    simPendingPuk[simPendingPuk.length - 1] = 0;
    textEditOpen(S("New PIN"), S(""), TXT_SIM_NEWPIN, true, true);
    simTookScreen = true;           // step 1 of 2 - do not close what just opened
    return true;
  }
  if (owner == TXT_SIM_NEWPIN) {
    modemSendAT("AT+CPIN=\"" + jstr(simPendingPuk) + "\",\"" + jstr(value) + "\"", 5000);
    delay(300);
    let cpin = modemSendAT("AT+CPIN?");
    memset(simPendingPuk, 0, simPendingPuk.length);
    if (cpin.indexOf("+CPIN: READY", ) >= 0) {
      simState = SIM_READY_ST; simReady = true; simPinAttempts = 0;
      simFlashUntil = 0;
      pxlog("[SIM] SIM unlocked, new PIN set");
    } else if (cpin.indexOf("+CPIN: SIM PUK", ) >= 0) {
      simFlashWrong(S("Wrong PUK"), 1);
      simPromptPuk();               // back to step 1, same reasoning as the PIN
      simTookScreen = true;
    } else {
      simSetFlash(S("Unlock failed"));
      simPromptPuk();
      simTookScreen = true;
    }
    return true;
  }
  return false;
}

// Sends one AT command, collects whatever comes back for up to timeoutMs.
// Blocking - same tradeoff sdBegin()/cameraBegin() already make at startup.
// Fine at 3s poll intervals; don't call this every loop() iteration.
// (default lives only on the forward declaration up top, per C++ rules)
function modemSendAT(cmd, timeoutMs = 800) {
  // Hand any complete lines already sitting in the buffer to their handlers
  // BEFORE clearing it. Blindly flushing here is how a RING that arrived a
  // moment ago used to get destroyed. (A RING landing during the read loop
  // below still lands in `resp` and is lost - but RING repeats every few
  // seconds, so that self-heals on the next one. Dispatching from inside the
  // response would be worse: an ATH reply contains "NO CARRIER", which would
  // log the call twice.)
  modemWatch();
  while (modemSerial.available()) modemSerial.read();   // clear stale bytes
  modemSerial.print(cmd);
  modemSerial.print(S("\r\n"));
  let resp = "";
  let start = millis();
  while (u32(millis() - start) < timeoutMs) {
    while (modemSerial.available()) resp += String.fromCharCode(u8(modemSerial.read()));
    if (resp.indexOf("OK", ) >= 0 || resp.indexOf("ERROR", ) >= 0) break;
    delay(1);
  }
  return resp;
}

// ---- TEMPORARY DIAGNOSTIC: what network are we actually on? ----
// Two one-shot sweeps plus a per-call probe. Set to 0 once the answers are
// written down: every probe is a blocking AT round-trip, and one of them
// fires during a live call.
const PXP_RAT_PROBE = 1;

// #if PXP_RAT_PROBE
let ratSimSwept = false;   // fires when the modem first answers AT
let ratNetSwept = false;   // fires when we first register
let ratClockRecheckAt = 0;   // one more CCLK reading a minute after registering
// #endif

// Pull one response line out of an AT reply. Returns "no reply" when the
// prefix never turned up, so an unsupported command reads as data in the log
// rather than as silence we have to guess about.
function atLine(cmd, prefix, timeoutMs) {
  let r = modemSendAT(jstr(cmd), timeoutMs);
  let p = r.indexOf(jstr(prefix), );
  if (p < 0) return "no reply";
  let e = r.indexOf(String.fromCharCode(ch('\n')), u32(p));
  let s = (e > p) ? r.substring(u32(u32(p) + strlen(prefix)), u32(e))
                     : r.substring(u32(u32(p) + strlen(prefix)));
  s = strTrim(s);
  return s;
}

// AT+CPSI? first field is the radio: LTE = on 4G, GSM = on 2G. LTE while idle
// but GSM during a call means voice is 2G fallback (CSFB), which decides the
// modem choice for the PCB.
function logServingSystem(tag) {
// #if PXP_RAT_PROBE
  let l = new Uint8Array(160);
  snprintf(l, l.length, S("[RAT] %s: %s"), tag,
           cstr(atLine(S("AT+CPSI?"), S("+CPSI:"), 1500)));
  pxlog(jstr(l));
// #endif
}

// Fires the moment the modem answers AT - before registration, so it works on
// a PIN-locked card. AT+SPIC is READ-ONLY: it reports the card's own counters
// and does not spend a try.
function logSimSweep() {
// #if PXP_RAT_PROBE
  if (ratSimSwept) return;
  // The modem answers plain AT several seconds before it will answer anything
  // about the SIM. CPIN is mandatory on every module, so if IT has no reply we
  // are simply too early - back off and try again on the next poll, otherwise
  // SPIC gets blamed for the modem still waking up.
  let cpin = atLine(S("AT+CPIN?"), S("+CPIN:"), 1000);
  if (cpin == "no reply") return;
  ratSimSwept = true;
  let l = new Uint8Array(160);
  snprintf(l, l.length, S("[SWEEP] CPIN: %s"), cstr(cpin));
  pxlog(jstr(l));
  snprintf(l, l.length, S("[SWEEP] SPIC, tries left (PIN1,PUK1,PIN2,PUK2): %s"),
           cstr(atLine(S("AT+SPIC"), S("+SPIC:"), 1000)));
  pxlog(jstr(l));
// #endif
}

// Fires the first time registration reports home or roaming - the point where
// the serving system, the operator and network time are all real.
function logNetSweep() {
// #if PXP_RAT_PROBE
  if (ratNetSwept) return;
  ratNetSwept = true;
  let l = new Uint8Array(160);
  {
    // Was: format the reply into a log line and drop the parsed value on the
    // floor. The Network page needs it, so it is kept now.
    let cpsi = atLine(S("AT+CPSI?"), S("+CPSI:"), 1500);
    netParseCPSI(cpsi);
    snprintf(l, l.length, S("[SWEEP] CPSI, serving system: %s"), cstr(cpsi));
  }
  pxlog(jstr(l));
  snprintf(l, l.length, S("[SWEEP] CNSMOD, mode (1=GSM 3=EGPRS 4=WCDMA 8=LTE): %s"),
           cstr(atLine(S("AT+CNSMOD?"), S("+CNSMOD:"), 1000)));
  pxlog(jstr(l));
  snprintf(l, l.length, S("[SWEEP] COPS, operator: %s"),
           cstr(atLine(S("AT+COPS?"), S("+COPS:"), 3000)));
  pxlog(jstr(l));
  snprintf(l, l.length, S("[SWEEP] CTZU, auto time update on?: %s"),
           cstr(atLine(S("AT+CTZU?"), S("+CTZU:"), 1000)));
  pxlog(jstr(l));
  snprintf(l, l.length, S("[SWEEP] CCLK, modem clock: %s"),
           cstr(atLine(S("AT+CCLK?"), S("+CCLK:"), 1000)));
  pxlog(jstr(l));
  ratClockRecheckAt = u32(millis() + 60000);
// #endif
}

// Periodic status check: is a SIM in, are we registered, how strong is signal.
// Called from loop() on a timer, same pattern as sdPoll().
function modemPoll(now) {
  if (now < modemNextPoll) return;

  // Voice memo audio has a very small hardware buffer (~128ms). The AT
  // round-trips below can each block for up to 800ms, several of them back
  // to back - long enough to drain that buffer dry mid-recording or
  // mid-playback, which is why the I2S hardware ends up repeating its last
  // buffer (the "stuck looping" audio). Simplest fix: while audio is
  // actively running, just check back again shortly instead of issuing any
  // AT command - a few seconds' delay to the next signal check is invisible,
  // dropped/looping audio isn't.
  //
  // Same reasoning applies to an active/ringing call, only worse: this is
  // the one screen where UI responsiveness matters most (hang-up, mute, the
  // live MM:SS counter), so a multi-second freeze there is the last thing
  // to tolerate. Gated the same way, not left to chance.
  // A game being played too (12 Nov): its frames would stutter on every check.
  let audioBusy = (state == ST_VOICE_REC  && voiceRecState == VREC_RECORDING) ||
                    (state == ST_VOICE_PLAY && voicePlaying) ||
                    (state == ST_INCOMING_CALL) ||
                    (state == ST_INCALL) ||
                    gameRunning();
  if (audioBusy) { modemNextPoll = u32(now + 250); return; }

  modemNextPoll = u32(now + MODEM_POLL_EVERY);

  if (!modemPresent) {
    let r = modemSendAT("AT", MODEM_AT_PROBE_MS);
    modemPresent = r.indexOf("OK", ) >= 0;
    if (modemPresent) {
      modemMisses = 0;
      pxlog("[Modem] Responding to AT");
    } else {
      modemMisses++;
      // Log the first few, then go quiet and slow down. A modem-less bench
      // otherwise fills the console with one identical line every 3 seconds.
      if (modemMisses <= MODEM_MISS_BACKOFF) pxlog("[Modem] No response yet");
      else if (modemMisses == MODEM_MISS_BACKOFF + 1)
        pxlog("[Modem] Still no response - slowing to one probe every 30s");
      if (modemMisses > MODEM_MISS_BACKOFF) modemNextPoll = u32(now + MODEM_POLL_SLOW);
      return;                    // nothing else will answer until this does
    }
    // Accept network time (NITZ). 3GPP TS 27.007, not a SIMCom extension, so
    // this survives a change of module. Set before registration, because that
    // is when the network sends it. Some modules only apply it after a reboot.
    modemSendAT("AT+CTZU=1");
    logSimSweep();               // card try counters, before a PIN is entered
    // Fall through to AT+CPIN? in this same pass. Returning here cost a whole
    // 3s poll cycle, which is 3s of the home screen not knowing about the SIM.
  }

  let cpin = modemSendAT("AT+CPIN?");
  let newState = 0;
  if      (cpin.indexOf("+CPIN: READY", )   >= 0) newState = SIM_READY_ST;
  else if (cpin.indexOf("+CPIN: SIM PIN", ) >= 0) newState = SIM_NEEDS_PIN;
  else if (cpin.indexOf("+CPIN: SIM PUK", ) >= 0) newState = SIM_NEEDS_PUK;
  else                                            newState = SIM_NOT_PRESENT; // no card, or +CME ERROR

  if (newState != simState) {
    simState = newState;
    const names = [S("unknown"), S("no SIM detected"), S("needs PIN"), S("needs PUK (blocked!)"), S("ready")];
    let l = new Uint8Array(48); snprintf(l, l.length, S("[Modem] SIM: %s"), names[simState]);
    pxlog(jstr(l));

    // Repaint immediately so a stale HOME message never lingers until the
    // next 1s tick - e.g. "Insert SIM card" staying up after the SIM is
    // actually detected. The prompt itself now lives below, outside this
    // block, so a skipped one gets asked again on the next poll instead of
    // being lost for good.
    if (state == ST_HOME) renderInner();
  }
  simReady = (simState == SIM_READY_ST);

  // Re-ask on EVERY poll while the card is locked, not once when the state
  // changed. A prompt skipped because a popup or another field was open was
  // previously lost for good. This also grabs the screen back after the boot
  // window, where the home screen is open for seconds before AT+CPIN? answers.
  // A popup does not outrank a locked card, so any open popup is closed first.
  // ...and never while the phone is switched off. A powered-down phone must not
  // light its screen to ask for a PIN — same rule callWatch() already follows
  // for incoming calls. The re-ask fires every poll, so it will prompt within
  // 3s of the phone actually being turned on.
  if (powered && state != ST_OFF && strlen(MODEM_PIN) == 0 &&
      (simState == SIM_NEEDS_PIN || simState == SIM_NEEDS_PUK)) {
    let alreadyAsking = (state == ST_TEXTEDIT &&
                          (textOwner == TXT_SIM_PIN || textOwner == TXT_SIM_PUK
                           || textOwner == TXT_SIM_NEWPIN));
    if (!alreadyAsking) {
      optOpen = false;                              // no optClose() in this file
      if (simState == SIM_NEEDS_PIN) simPromptPin();
      else                           simPromptPuk();
    }
  }

  // One-shot PIN unlock, only if you filled in MODEM_PIN above.
  if (simState == SIM_NEEDS_PIN && !pinAttempted && strlen(MODEM_PIN) > 0) {
    pinAttempted = true;
    pxlog("[Modem] Attempting SIM PIN unlock...");
    let r = modemSendAT("AT+CPIN=\"" + jstr(MODEM_PIN) + "\"", 3000);
    pxlog(jstr(r.indexOf("OK", ) >= 0 ? S("[Modem] PIN accepted, will confirm on next poll")
                               : S("[Modem] PIN command failed - check MODEM_PIN")));
  }

  if (!simReady) { modemRegState = -1; modemSignalCSQ = 99; return; }

  let creg = modemSendAT("AT+CREG?");
  let c = creg.indexOf("+CREG:", );
  if (c >= 0) {
    let comma = creg.indexOf(String.fromCharCode(ch(',')), u32(c));
    if (comma >= 0) {
      let stat = strToInt(creg.substring(u32(comma + 1), u32(comma + 2)));
      if (stat != modemRegState) {
        modemRegState = stat;
        const names = [S("not registered"),S("home network"),S("searching"),S("denied"),S("unknown"),S("roaming")];
        let l = new Uint8Array(64); snprintf(l, l.length, S("[Modem] Registration: %s"),
                              (stat >= 0 && stat <= 5) ? names[stat] : S("?"));
        pxlog(jstr(l));
        if (stat == 1 || stat == 5) logNetSweep();   // home or roaming = real answers
      }
    }
  }

// #if PXP_RAT_PROBE
  // The CCLK read at registration said 1970 on Telekom (bench, 8 Nov): no
  // network time at that moment. A network can send it a little after the
  // modem joins, so read it once more a minute later before concluding that
  // it never does.
  if (ratClockRecheckAt && i32((u32(now - ratClockRecheckAt))) >= 0) {
    ratClockRecheckAt = 0;
    let l = new Uint8Array(96);
    snprintf(l, l.length, S("[SWEEP] CCLK, a minute later: %s"),
             cstr(atLine(S("AT+CCLK?"), S("+CCLK:"), 1000)));
    pxlog(jstr(l));
  }
// #endif

  let csq = modemSendAT("AT+CSQ");
  let q = csq.indexOf("+CSQ:", );
  if (q >= 0) {
    let v = strToInt(csq.substring(u32(q + 6)));
    if (v != modemSignalCSQ) {
      modemSignalCSQ = v;
      let l = new Uint8Array(48); snprintf(l, l.length, S("[Modem] Signal CSQ: %d/31"), v);
      pxlog(jstr(l));
    }
  }

  // SMS setup runs once, only after the SIM is confirmed ready - CMGF/CNMI
  // will just ERROR on a locked SIM, no point trying earlier.
  if (!smsReady) {
    let cmgf = modemSendAT("AT+CMGF=1");         // text mode, not PDU
    let cnmi = modemSendAT("AT+CNMI=2,2,0,0,0");  // push new SMS straight to UART
    smsReady = (cmgf.indexOf("OK", ) >= 0) && (cnmi.indexOf("OK", ) >= 0);
    pxlog(jstr(smsReady ? S("[SMS] Ready - text mode, live delivery on")
                   : S("[SMS] Setup failed, will retry next poll")));
  }

  // Call setup, same one-shot-after-SIM-ready pattern as SMS above.
  // AT+CLIP=1 turns on caller-ID notifications (+CLIP: "<number>",... arrives
  // alongside RING). AT+CVHU=0 lets ATA/ATH actually control call state -
  // without it, some firmware builds ignore ATH during an active call.
  if (!callReady) {
    let clip = modemSendAT("AT+CLIP=1");
    let cvhu = modemSendAT("AT+CVHU=0");
    callReady = (clip.indexOf("OK", ) >= 0) && (cvhu.indexOf("OK", ) >= 0);
    pxlog(jstr(callReady ? S("[Call] Ready - caller ID and hang-up control on")
                     : S("[Call] Setup failed, will retry next poll")));
    if (callReady) logServingSystem(S("idle"));   // baseline to compare against
  }
}

// ---- Sending ----
// AT+CMGS="<number>" then the body then a raw Ctrl+Z (0x1A) byte to send it -
// standard text-mode sequence. Blocking, same tradeoff as modemSendAT() itself;
// only ever called from a button press, never from loop()'s hot path.
function smsSend(number, body) {
  if (!smsReady) { pxlog("[SMS] Not ready yet"); return false; }

  while (modemSerial.available()) modemSerial.read();   // clear stale bytes, same as modemSendAT
  modemSerial.print(S("AT+CMGS=\""));
  modemSerial.print(number);
  modemSerial.print(S("\"\r\n"));

  // Wait for the '>' prompt before typing the body - the modem won't accept
  // it any earlier. Same delay(1)-in-every-iteration rule as modemSendAT():
  // a busy-wait with nothing yielding trips the watchdog on this chip.
  let resp = "";
  let start = millis();
  let gotPrompt = false;
  while (u32(millis() - start) < 3000) {
    while (modemSerial.available()) {
      let c = u8(modemSerial.read());
      resp += String.fromCharCode(c);
      if (c == ch('>')) { gotPrompt = true; }
    }
    if (gotPrompt) break;
    delay(1);
  }
  if (!gotPrompt) { pxlog("[SMS] Modem never gave the '>' prompt"); return false; }

  modemSerial.print(body);
  modemSerial.write(0x1A);            // Ctrl+Z = send

  // Sending is airtime-dependent, give it real time to answer.
  resp = "";
  start = millis();
  while (u32(millis() - start) < 10000) {
    while (modemSerial.available()) resp += String.fromCharCode(u8(modemSerial.read()));
    if (resp.indexOf("+CMGS:", ) >= 0 || resp.indexOf("ERROR", ) >= 0) break;
    delay(1);
  }
  let ok = resp.indexOf("+CMGS:", ) >= 0;
  pxlog(ok ? "[SMS] Sent" : "[SMS] Send failed: " + resp);
  return ok;
}

// ---- Receiving ----
// Non-blocking: reads whatever bytes are sitting in the UART right now and
// looks for a complete "+CMT: ..." header line followed by a body line. If
// the message is still arriving mid-poll, unread bytes just wait for next
// time - modemSerial is a real UART with its own buffer, nothing is lost.
//
// Deliberately checked BEFORE any modemSendAT() call in loop(), because
// modemSendAT() drains the input buffer first thing - if an incoming SMS
// notification landed there between polls, an AT+CSQ etc. would silently eat
// it. Reading here first means whichever runs first in a given loop() pass
// wins the bytes cleanly rather than racing.
let smsRxLine = "";
let smsRxHaveHeader = false;
let smsRxNumber = cbuf(24, "");

// Handles ONE complete line from the modem. Returns true if the line belonged
// to SMS, so the caller knows not to offer it to the call handler as well (an
// SMS body containing the word "RING" must never start a fake incoming call).
//
// This used to be smsWatch(), which read the UART itself. See modemWatch().
function smsHandleLine(line) {
  if (!smsReady) return false;

  if (!smsRxHaveHeader) {
    let h = line.indexOf("+CMT:", );
    if (h < 0) return false;          // not an SMS line - let the call handler see it
    // +CMT: "+3670...",,"25/08/19,12:34:56+08"
    let q1 = line.indexOf(String.fromCharCode(ch('"')), u32(h));
    let q2 = (q1 >= 0) ? line.indexOf(String.fromCharCode(ch('"')), u32(q1 + 1)) : -1;
    if (q1 >= 0 && q2 > q1) {
      toCharArray(line.substring(u32(q1 + 1), u32(q2)), smsRxNumber, MSG_NUMBER_LEN, );
      smsRxHaveHeader = true;
    }
    return true;
  }

  {
      let smsRxLine = line;   // the body line
        // this line is the message body
        messagesAdd(smsRxNumber, cstr(smsRxLine), u8(MSG_DIR_IN), MSG_ST_SENT);   // sets msgStorageFlash itself if storage's full
        let l = new Uint8Array(64);
        snprintf(l, l.length, S("[SMS] From %s: %s"), smsRxNumber, cstr(smsRxLine));
        pxlog(jstr(l));

        // Badge only counts texts the person hasn't actually seen - if
        // they're already sitting on ST_MESSAGES it lands directly in view
        // (handled just below), so it was never "unread" in the first place.
        if (state != ST_MESSAGES) unreadTextCount++;

        // Only interrupt with a flash/redraw if the phone is actually on -
        // matches "only receive while powered" from the spec. The modem itself
        // keeps listening regardless; this just controls what the USER sees.
        if (powered) {
          if (state == ST_MESSAGES) { threadsScan(); renderInner(); }
          else if (state == ST_CHAT && strcmp(chatNumber, smsRxNumber) == 0) {
            chatScrollTop = 9999;   // a message just landed in the thread you are reading
            renderInner();
          }
          // A text now makes a sound, and lights whichever screen faces you so
          // the badge can be seen - not during a call, which owns both screens.
          if (callState == CALL_IDLE) {
            if (!flipOpen) osVolumePress();   // the same 5 s outer-screen peek a side key gives
            else if (screenState != SCREEN_NORMAL) { startScreenTimers(); renderInner(); }
          }
          msgTonePlay();
        }

        smsRxHaveHeader = false;
        smsRxNumber[0] = 0;
  }
  return true;
}

// ---- Calls: incoming ----
// Same non-blocking, byte-at-a-time shape as smsWatch(), and deliberately
// called before any modemSendAT() in loop() for the identical reason: a
// RING/+CLIP/+CEND line landing in the same tick an AT+CSQ etc. fires would
// otherwise get silently drained and lost. This is a hard ordering
// requirement, not just a consequence of where the call happens to sit -
// worth stating outright since it's exactly the kind of thing that's easy
// to get right by accident and break months later when something nearby
// gets reordered.
//
// Missed call = the caller hung up before we answered: +CEND/NO CARRIER
// arrives while callState is still CALL_RINGING. No separate ring-timeout
// timer - that event already tells us definitively what happened.
let callRxLine = "";

function callFinalize(loggedType, durationSec) {
  callLogAdd(callNumber, loggedType, durationSec);   // sets msgStorageFlash itself if storage's full
  ringtoneStop();
  callState = CALL_IDLE;
  state = preCallState;
  callNumber[0] = 0;
  callMuted = false;
  callSpeaker = false;
  callOutgoing = false;
  callClccNext = 0;
  if (powered) {
    if (flipOpen) {
      renderInner();
    } else {
      renderOuter();
      // The RING handler force-lit the outer screen and cancelled its fade
      // timer so nothing blanked it mid-ring. The call is over now, so hand it
      // back to the normal 5s-then-fade behaviour instead of leaving it lit
      // forever.
      startOuterTimer();
    }
  }
}

// Shared by the in-screen Back button, flip-close, and Decline - every path
// that ends a call locally goes through here so the log always gets a
// correctly-typed entry and ATH is only ever sent once per call.
function callHangup() {
  if (callState == CALL_IDLE) return;
  modemSendAT("ATH");
  if (callState == CALL_RINGING) {
    // Declined on purpose - NOT a missed call. missedCallCount is reserved
    // for calls the person never got a chance to act on (see callWatch()'s
    // +CEND/NO CARRIER-while-ringing path); a deliberate decline shouldn't
    // inflate that badge, even though it's logged with its own CALL_REJECTED
    // type so the history still shows it happened.
    callFinalize(u8(CALL_REJECTED), 0);
    pxlog("[Call] Declined");
  } else if (callState == CALL_DIALING) {
    // Cancelled before they answered. Still a real outgoing call in the log,
    // just a zero-length one.
    callFinalize(u8(CALL_OUT), 0);
    pxlog("[Call] Cancelled");
  } else if (callState == CALL_ACTIVE) {
    let durationSec = (callStartMs != 0) ? Math.trunc((u32(millis() - callStartMs)) / 1000) : 0;
    callFinalize(u8(callOutgoing ? CALL_OUT : CALL_IN), durationSec);
    audioBlip();        // a CONNECTED call ended - declines and cancels get nothing
    pxlog("[Call] Ended (hung up)");
  }
}

function callAnswer() {
  if (callState != CALL_RINGING) return;
  modemSendAT("ATA");
  ringtoneStop();
  callState = CALL_ACTIVE;
  state = ST_INCALL;
  callStartMs = millis();
  // No callLogAdd() here - the log is append-only, so an entry opened now
  // and "finished" at hangup would mean two records for one call, not one
  // updated record. The single entry gets written once, at callFinalize(),
  // once the real duration is known.
  audioBlip();          // you picked up
  pxlog("[Call] Answered");
  renderInner();
  logServingSystem(S("in call (incoming)"));
}

// Place an outgoing call. The trailing ';' on ATD is what makes it a VOICE
// call - without it the modem tries to open a DATA call and it simply fails.
function callDial(number) {
  if (callState != CALL_IDLE) return false;
  if (!number || !number[0]) return false;

  if (!simReady || !networkRegistered()) {
    snprintf(callFlash, callFlash.length, S("No network"));
    callFlashUntil = u32(millis() + 2500);
    pxlog("[Call] Cannot dial - not registered");
    renderInner();
    return false;
  }

  preCallState  = state;
  callOutgoing  = true;
  callMuted     = false;
  callSpeaker   = false;
  callStartMs   = 0;            // stays 0 until the far end actually answers
  callClccNext  = u32(millis() + 2000);
  strncpy(callNumber, number, u32(CALLLOG_NUMBER_LEN - 1));
  callNumber[CALLLOG_NUMBER_LEN - 1] = 0;
  callState = CALL_DIALING;
  state = ST_INCALL;
  optOpen = false;
  startScreenTimers();
  renderInner();

  let r = modemSendAT("ATD" + jstr(callNumber) + ";", 2000);
  if (r.indexOf("ERROR", ) >= 0 || r.indexOf("NO DIALTONE", ) >= 0) {
    pxlog("[Call] Dial rejected by modem");
    callFinalize(u8(CALL_OUT), 0);
    snprintf(callFlash, callFlash.length, S("Call failed"));
    callFlashUntil = u32(millis() + 2500);
    renderInner();
    return false;
  }
  pxlog("[Call] Dialing " + jstr(callNumber));
  return true;
}

// Reads the <stat> field out of a "+CLCC: <id>,<dir>,<stat>,..." line.
// stat 0 = active (they picked up), 2 = dialing, 3 = alerting (ringing at
// their end). Polling this is the portable way to notice the answer: not
// every module emits a "VOICE CALL: BEGIN" URC, but AT+CLCC is standard.
function clccStat(resp) {
  let p = resp.indexOf("+CLCC:", );
  if (p < 0) return -1;
  let c1 = resp.indexOf(String.fromCharCode(ch(',')), u32(p));
  let c2 = (c1 >= 0) ? resp.indexOf(String.fromCharCode(ch(',')), u32(c1 + 1)) : -1;
  let c3 = (c2 >= 0) ? resp.indexOf(String.fromCharCode(ch(',')), u32(c2 + 1)) : -1;
  if (c2 < 0 || c3 < 0) return -1;
  return strToInt(resp.substring(u32(c2 + 1), u32(c3)));
}

// The far end picked up. Shared by the URC fast-path and the CLCC poll.
function callConnected() {
  if (callState != CALL_DIALING) return;
  callState = CALL_ACTIVE;
  callStartMs = millis();
  pxlog("[Call] Answered by them");
  renderInner();
  logServingSystem(S("in call (outgoing)"));
}

function callToggleMute() {
  if (callState != CALL_ACTIVE) return;
  callMuted = !callMuted;
  modemSendAT(jstr(callMuted ? S("AT+CMUT=1") : S("AT+CMUT=0")));
  renderInner();
}

function callToggleSpeaker() {
  if (callState != CALL_ACTIVE) return;
  callSpeaker = !callSpeaker;
  modemSendAT(jstr(callSpeaker ? S("AT+CSDVC=3") : S("AT+CSDVC=1")));
  renderInner();
}

// Either volume button silences a ringing call - the universal phone gesture.
// It only kills the SOUND: the call keeps ringing at the network level and the
// screen keeps showing "Incoming call", so Answer and Decline still work. The
// caller cannot tell you did it.
//
// Returns true if it actually silenced something, so the caller knows to
// swallow the press instead of letting it do its normal job (peek the outer
// screen / count towards the 3x debug-mode toggle).
function callSilenceRing() {
  // Returns true for the WHOLE ringing state, not just while sound is coming
  // out. That is deliberate: a volume press during a ring must never fall
  // through to the volume control. On silent or vibrate there is nothing to
  // silence, but the press still has to be swallowed.
  if (callState == CALL_IDLE) return false;
  if (ringtonePlaying) {
    ringtoneStop();
    pxlog("[Call] Ringer silenced");
  }
  return true;
}

// Handles ONE complete line from the modem. Used to be callWatch(), which read
// the UART itself - see modemWatch() for why that could never work.
function callHandleLine(callRxLine) {
  {
    {
      if (callRxLine.startsWith("RING")) {
        // A powered-off phone must not ring. The modem stays powered on this
        // breadboard even when the OS is "off", so RING still arrives - just
        // ignore it rather than jumping the UI out of ST_OFF.
        if (callState == CALL_IDLE && powered && state != ST_OFF) {
          // A ringing alarm gives way to the call: stopped, and the call
          // returns to wherever the phone was before the alarm (8 Nov).
          if (state == ST_ALARM_RING) alarmDismiss(S("a call came in"));
          preCallState = state;
          callState = CALL_RINGING;
          state = ST_INCOMING_CALL;
          callNumber[0] = 0;   // filled in by +CLIP if/when it arrives

          // An options popup floats above every screen AND swallows every
          // button (see osButtonPress). Left open, it would hide the incoming
          // call and eat Answer/Decline - so dismiss it.
          optOpen = false;

          ringtoneStart();
          let l = new Uint8Array(32); snprintf(l, l.length, S("[Call] Incoming"));
          pxlog(jstr(l));

          if (flipOpen) {
            // The inner screen may be dimmed or fully asleep (brightness 0)
            // when the call lands. loop() only holds the dim/sleep deadlines
            // OFF while ringing - it never turns the backlight back ON - so
            // without this the call screen was drawn into a black panel and
            // the first button press got eaten as "wake from sleep" instead
            // of answering.
            startScreenTimers();   // brightness 100, screenState = SCREEN_NORMAL
            renderInner();
          } else {
            // Flip closed: the outer screen has almost certainly already faded
            // to 0 (it only stays lit 5s after a flip-close). Light it and
            // cancel the fade timer so nothing blanks it mid-ring.
            clearOuterTimer();
            clearOuterFade();
            setOuterBrightness(100);
            renderOuter();
          }
        }
        // RING repeats every few seconds while ringing - only act on the first one
      } else if (callRxLine.startsWith("+CLIP:")) {
        // +CLIP: "+3670...",145,"","",,0  - just want the quoted number
        let q1 = callRxLine.indexOf(String.fromCharCode(ch('"')), );
        let q2 = (q1 >= 0) ? callRxLine.indexOf(String.fromCharCode(ch('"')), u32(q1 + 1)) : -1;
        if (q1 >= 0 && q2 > q1 && callState == CALL_RINGING) {
          toCharArray(callRxLine.substring(u32(q1 + 1), u32(q2)), callNumber, CALLLOG_NUMBER_LEN, );
          ringForCaller();     // the caller's own ringtone, if they have one (12 Nov)
          if (powered) { if (!flipOpen) renderOuter(); else renderInner(); }
        }
      } else if (callRxLine.indexOf("VOICE CALL: BEGIN", ) >= 0) {
        // Fast path where the module supports it; the CLCC poll in loop() is
        // the fallback for when it does not.
        callConnected();
      } else if (callRxLine.startsWith("BUSY") || callRxLine.startsWith("NO ANSWER")
                 || callRxLine.startsWith("NO DIALTONE")) {
        if (callState == CALL_DIALING) {
          pxlog("[Call] " + callRxLine);
          snprintf(callFlash, callFlash.length, S("%s"), cstr(callRxLine));
          callFlashUntil = u32(millis() + 2500);
          callFinalize(u8(CALL_OUT), 0);
        }
      } else if (callRxLine.startsWith("+CEND") || callRxLine.indexOf("NO CARRIER", ) >= 0) {
        if (callState == CALL_DIALING) {
          callFinalize(u8(CALL_OUT), 0);
          pxlog("[Call] Not answered");
        } else if (callState == CALL_RINGING) {
          missedCallCount++;
          callFinalize(u8(CALL_MISSED), 0);
          pxlog("[Call] Missed");
        } else if (callState == CALL_ACTIVE) {
          let durationSec = (callStartMs != 0) ? Math.trunc((u32(millis() - callStartMs)) / 1000) : 0;
          callFinalize(u8(callOutgoing ? CALL_OUT : CALL_IN), durationSec);
          audioBlip();    // they hung up on a connected call - same beep
          pxlog("[Call] Ended");
        }
        // any other state: unrelated line, ignore
      }
      // any other unsolicited line (URCs we don't care about) - drop it
    }
  }
}

// ==================== THE ONE MODEM UART READER ====================
//
// THIS IS WHY INCOMING CALLS DID NOTHING.
//
// smsWatch() and callWatch() each did `while (modemSerial.available())` and
// consumed bytes. loop() called smsWatch() first. There is only ONE serial
// buffer, so smsWatch() drained it completely every pass - RING and +CLIP
// included - found no "+CMT:" in them, and threw them away as "URCs we don't
// care about". callWatch() then ran against an empty buffer. Every single
// time. It never saw one byte of a RING for as long as the code has existed,
// which is exactly the symptom: the network rings the caller, the modem
// faithfully reports RING, and the phone shows nothing at all.
//
// The fix is structural, not a tweak: exactly one function owns the UART,
// assembles whole lines, and offers each line to both handlers.
let modemRxLine = "";

function modemWatch() {
  while (modemSerial.available()) {
    let c = u8(modemSerial.read());
    if (c == ch('\r')) continue;
    if (c != ch('\n')) {
      if (modemRxLine.length < 200) modemRxLine += String.fromCharCode(c);   // hard cap, never unbounded
      continue;
    }
    if (modemRxLine.length > 0) {
      // SMS gets first refusal because it is stateful (a +CMT: header claims
      // the NEXT line as its body). Anything it doesn't claim is offered to
      // the call handler.
      if (!smsHandleLine(modemRxLine)) callHandleLine(modemRxLine);
    }
    modemRxLine = "";
  }
}

// ==================== CAMERA ====================
// #include <Wire.h>
// #include "esp_camera.h"
// #include "img_converters.h"

// jpg2rgb565's last argument is an enum Espressif RENAMED in core 3.3.0:
// it was jpg_scale_t, it is now esp_jpeg_image_scale_t, and the header that
// declared the old one moved out of reach. Rather than hardcode either name,
// deduce the type from the function's own signature - then this compiles on
// any version. The underlying values are unchanged in both:
//   0 = full size, 1 = half, 2 = quarter, 3 = eighth
// template <typename R, typename A1, typename A2, typename A3, typename S>
// S pxpScaleOf(R (*)(A1, A2, A3, S));
// typedef decltype(pxpScaleOf(&jpg2rgb565)) PxpScale;

// The OV2640 only responds on I2C while a clock is running. So: scan with no
// XCLK generated. An answer at 0x30 proves the module clocks itself.
function cameraProbe() {
  pxlog("--- Camera probe ---");
  Wire.end();
  Wire.begin(CAM_SDA, CAM_SCL, 100000);
  delay(50);

  camSensorAddr = 0;
  for (let a = 1; a < 127; a = u8(a + 1)) {
    Wire.beginTransmission(a);
    if (Wire.endTransmission() == 0) {
      let l = new Uint8Array(48); snprintf(l, l.length, S("I2C device at 0x%02X"), a); pxlog(jstr(l));
      if (a == 0x30) camSensorAddr = a;      // OV2640 SCCB address
    }
  }
  if (camSensorAddr) {
    pxlog("OV2640 found - module has its OWN clock");
    pxlog("So DCLK is the pixel clock. Wiring is correct.");
    return true;
  }

  // Nothing answered. Feed it a 20 MHz clock on the spare pin and rescan.
  pxlog("Silent. Generating 20MHz on GPIO 14 and retrying...");
  ledcAttach(CAM_XCLK, 20000000, 1);
  delay(100);
  for (let a = 1; a < 127; a = u8(a + 1)) {
    Wire.beginTransmission(a);
    if (Wire.endTransmission() == 0 && a == 0x30) camSensorAddr = a;
  }
  ledcDetach(CAM_XCLK);
  if (camSensorAddr) {
    pxlog("Answers WITH an external clock.");
    pxlog("=> move the DCLK wire from GPIO 47 to GPIO 14");
    return false;
  }
  pxlog("No response either way. Check 3V3, GND, SDA=8, SCL=9");
  return false;
}

function cameraBegin() {
  let c = mk(camera_config_t);
  c.ledc_channel = LEDC_CHANNEL_0;
  c.ledc_timer   = LEDC_TIMER_0;
  c.pin_d0 = CAM_D0; c.pin_d1 = CAM_D1; c.pin_d2 = CAM_D2; c.pin_d3 = CAM_D3;
  c.pin_d4 = CAM_D4; c.pin_d5 = CAM_D5; c.pin_d6 = CAM_D6; c.pin_d7 = CAM_D7;
  c.pin_xclk  = CAM_XCLK;
  c.pin_pclk  = CAM_PCLK;
  c.pin_vsync = CAM_VSYNC;
  c.pin_href  = CAM_HREF;
// #if ESP_IDF_VERSION >= ESP_IDF_VERSION_VAL(5, 0, 0)
  c.pin_sccb_sda = CAM_SDA;
  c.pin_sccb_scl = CAM_SCL;
// #else
  // c.pin_sscb_sda = CAM_SDA;
  // c.pin_sscb_scl = CAM_SCL;
// #endif
  c.pin_pwdn  = -1;                 // tied to GND on the board
  c.pin_reset = -1;                 // tied to 3V3 on the board
  c.xclk_freq_hz = 20000000;
  c.pixel_format = PIXFORMAT_JPEG;
  c.frame_size   = CAM_PHOTO_SIZE;  // buffer must fit the LARGEST size we use
  c.jpeg_quality = 12;
  c.fb_count     = 1;
  c.fb_location  = CAMERA_FB_IN_PSRAM;
  c.grab_mode    = CAMERA_GRAB_WHEN_EMPTY;

  let e = esp_camera_init(c);
  if (e != ESP_OK) {
    let l = new Uint8Array(72); snprintf(l, l.length, S("Camera init failed: 0x%X"), e); pxlog(jstr(l));
    camReady = false;
    return false;
  }
  camReady = true;
  let sn = esp_camera_sensor_get();
  if (sn) sn.set_framesize(sn, CAM_PREVIEW_SIZE);   // drop to preview size now
  pxlog("Camera ready (preview QVGA, photos SVGA)");
  return true;
}

function camSetFlash(msg) {
  strncpy(camFlash, msg, u32(camFlash.length - 1));
  camFlash[camFlash.length - 1] = 0;
  camFlashUntil = u32(millis() + 1800);
  pxlog(jstr(msg));
}

// The highest NNNN among the files called <prefix>NNNN.* in dir, or 0 (none,
// or no card). New photos and memos are numbered after it, so they sort last.
function sdHighestNum(dir, prefix) {
  if (!sdReady) return 0;
  let d = SD.open(dir);
  if (!d.valid() || !d.isDirectory()) { if (d.valid()) d.close(); return 0; }
  let best = 0;
  let pl = strlen(prefix);
  let e = d.openNextFile();
  while (e.valid()) {
    if (!e.isDirectory()) {
      let nm = e.name();
      let sl = strrchr(nm, ch('/'));     // a full path on core 2.x, the name on 3.x
      if (sl) nm = ptrAdd(sl, 1);
      let up = new Uint8Array(32);
      strncpy(up, nm, u32(up.length - 1)); up[up.length - 1] = 0;
      for (let q = up; q[0]; q = ptrAdd(q, 1)) q[0] = u8(toupper(q[0]));
      if (strncmp(up, prefix, pl) == 0) {
        let k = atoi(ptrAdd(up, pl));
        if (k > best) best = k;
      }
    }
    e.close();
    e = d.openNextFile();
  }
  d.close();
  return best;
}

// The next PXP_nnnn.JPG: one past the highest on the card, so a new photo
// always sorts last. It used to take the first FREE number, which after a
// deletion or a restart put a new photo in among the old ones. The card is
// read once per boot; after that the number just counts on.
function nextPhotoPath(out, n) {
  if (camLastNum == 0) camLastNum = sdHighestNum(S("/DCIM"), S("PXP_"));
  for (let i = camLastNum + 1; i <= 9999; i++) {
    snprintf(out, n, S("/DCIM/PXP_%04d.JPG"), i);
    if (!SD.exists(out)) { camLastNum = i; return; }
  }
  snprintf(out, n, S("/DCIM/PXP_9999.JPG"));
}

function camPrevFree() {
  if (camPrev) { free(camPrev); camPrev = null; }
  camPrevW = camPrevH = 0;
}

// One preview frame: grab the JPEG the sensor produces, shrink it during decode
// so it fits the screen, and keep it as RGB565 ready to blit. Same decode path
// the gallery already uses.
function cameraPreviewTick() {
  if (!camReady) return false;
  let fb = esp_camera_fb_get();
  if (!fb) return false;

  let ok = false;
  let w = 0, h = 0;
  if (jpegSize(fb.buf, fb.len, ref(() => w, v => w = i32(v), 'i32'), ref(() => h, v => h = i32(v), 'i32'))) {
    let sc = 0; let div = 1;
    if      (w > 240 * 4) { sc = 3; div = 8; }
    else if (w > 240 * 2) { sc = 2; div = 4; }
    else if (w > 240)     { sc = 1; div = 2; }
    let ow = Math.trunc(w / div), oh = Math.trunc(h / div);

    if (camPrev && (ow != camPrevW || oh != camPrevH)) camPrevFree();
    if (!camPrev) {
      camPrev = view(ps_malloc(u32(Math.imul(u32(Math.imul(u32(ow), u32(oh))), 2))), Uint16Array);
      camPrevW = ow; camPrevH = oh;
      if (!camPrev) { camPrevW = camPrevH = 0; }
    }
    if (camPrev) ok = jpg2rgb565(fb.buf, fb.len, view(camPrev, Uint8Array), sc);
  }
  esp_camera_fb_return(fb);
  return ok;
}

// Shutter. Saves the sensor's JPEG bytes straight to the card - no re-encoding,
// so the saved photo is full sensor resolution even though the preview is small.
function cameraShutter() {
  if (!camReady) { camSetFlash(S("Camera not ready")); return false; }
  if (!sdReady)  { camSetFlash(S("Insert memory card")); return false; }

  // Go to full photo size, throw away the frames captured mid-change, then shoot.
  let sn = esp_camera_sensor_get();
  if (sn) {
    sn.set_framesize(sn, CAM_PHOTO_SIZE);
    for (let i = 0; i < 2; i++) {
      let junk = esp_camera_fb_get();
      if (junk) esp_camera_fb_return(junk);
    }
  }

  let fb = esp_camera_fb_get();
  if (!fb) {
    if (sn) sn.set_framesize(sn, CAM_PREVIEW_SIZE);
    camSetFlash(S("Capture failed"));
    return false;
  }

  let path = new Uint8Array(40);
  nextPhotoPath(path, path.length);
  let f = SD.open(path, FILE_WRITE);
  let ok = false;
  if (f.valid()) { ok = (f.write(fb.buf, fb.len) == fb.len); f.close(); }
  let len = fb.len;
  esp_camera_fb_return(fb);
  if (sn) sn.set_framesize(sn, CAM_PREVIEW_SIZE);   // back to the live size
  camPrevFree();                                      // preview size changed

  let msg = new Uint8Array(40);
  if (ok) {
    snprintf(msg, msg.length, S("Saved %s"), ptrAdd(path, 6));      // skip "/DCIM/"
    sdUsedMB = u32((Math.trunc(SD.usedBytes() / (1024 * 1024))));
  } else {
    snprintf(msg, msg.length, S("Save FAILED (%u bytes)"), len);
  }
  camSetFlash(msg);
  return ok;
}

// ==================== GALLERY ====================
// Pull width/height straight out of the JPEG header (the SOF marker), so we
// know how much to shrink it before decoding.
function jpegSize(d, len, w, h) {
  if (len < 4 || d[0] != 0xFF || d[1] != 0xD8) return false;
  let i = 2;
  while (u32(i + 9) < len) {
    if (d[i] != 0xFF) { i = u32(i + 1); continue; }
    let m = d[i + 1];
    if (m == 0xC0 || m == 0xC1 || m == 0xC2) {
      h[0] = (d[i + 5] << 8) | d[i + 6];
      w[0] = (d[i + 7] << 8) | d[i + 8];
      return (w[0] > 0 && h[0] > 0);
    }
    if (m == 0xD8 || m == 0x01 || (m >= 0xD0 && m <= 0xD7)) { i = u32(i + 2); continue; }
    if (m == 0xD9 || m == 0xDA) return false;        // reached image data
    let seg = (d[i + 2] << 8) | d[i + 3];
    if (seg < 2) return false;
    i = u32(i + u32(2 + seg));
  }
  return false;
}

function galleryScan() {
  galleryCount = 0;
  galleryIdx = 0; galleryTop = 0;
  if (!sdReady) return;
  let dir = SD.open(S("/DCIM"));
  if (!dir.valid() || !dir.isDirectory()) { if (dir.valid()) dir.close(); return; }
  let e = dir.openNextFile();
  while (e.valid() && galleryCount < GALLERY_MAX) {
    if (!e.isDirectory()) {
      let n = jstr(e.name());
      let sl = n.lastIndexOf(String.fromCharCode(ch('/')));
      if (sl >= 0) n = n.substring(u32(sl + 1));
      let up = n; up = strUpper(up);
      if (up.endsWith(".JPG") || up.endsWith(".JPEG")) {
        strncpy(galleryNames[galleryCount], cstr(n), 31);
        galleryNames[galleryCount][31] = 0;
        gallerySizes[galleryCount] = e.size();
        galleryCount++;
      }
    }
    e.close();
    e = dir.openNextFile();
  }
  if (e.valid()) e.close();
  dir.close();

  // The card hands files back in whatever order they sit in the directory, which
  // is why they showed up 3,1,2. Sort by name so they read 1,2,3.
  for (let i = 1; i < galleryCount; i++) {
    let nm = new Uint8Array(32); let sz = 0;
    strncpy(nm, galleryNames[i], 32); sz = gallerySizes[i];
    let j = i - 1;
    while (j >= 0 && strcmp(galleryNames[j], nm) > 0) {
      strncpy(galleryNames[j + 1], galleryNames[j], 32);
      gallerySizes[j + 1] = gallerySizes[j];
      j--;
    }
    strncpy(galleryNames[j + 1], nm, 32); gallerySizes[j + 1] = sz;
  }
  let l = new Uint8Array(48); snprintf(l, l.length, S("Gallery: %d photo(s)"), galleryCount); pxlog(jstr(l));
}

function galleryFree() {
  if (galleryImg) { free(galleryImg); galleryImg = null; }
  galleryImgW = galleryImgH = 0;
}

// Reads the file into PSRAM, shrinks it to fit the 240px screen, decodes to
// RGB565. Shrinking happens during decode, so a big photo never needs a big
// buffer.
function galleryLoad(idx) {
  galleryFree();
  photoFromFiles = false;          // the Gallery's own photo, not the File explorer's
  if (!sdReady || idx < 0 || idx >= galleryCount) return false;

  let path = new Uint8Array(48);
  snprintf(path, path.length, S("/DCIM/%s"), galleryNames[idx]);
  return photoLoad(path);
}

// Any photo on the card, by its path: the Gallery's, and the File explorer's
// (9 Nov) - that one can be in any folder.
function photoLoad(path) {
  galleryFree();
  if (!sdReady) return false;
  let f = SD.open(path, FILE_READ);
  if (!f.valid()) { pxlog("Cannot open photo"); return false; }
  let len = f.size();
  let jpg = ps_malloc(len);
  if (!jpg) { f.close(); pxlog("Photo too big for memory"); return false; }
  f.read(jpg, len);
  f.close();

  let w = 0, h = 0;
  if (!jpegSize(jpg, len, ref(() => w, v => w = i32(v), 'i32'), ref(() => h, v => h = i32(v), 'i32'))) { free(jpg); pxlog("Not a readable JPEG"); return false; }

  let sc = 0; let div = 1;          // 0 = full size
  if      (w > 240 * 4) { sc = 3; div = 8; }
  else if (w > 240 * 2) { sc = 2; div = 4; }
  else if (w > 240)     { sc = 1; div = 2; }
  let ow = Math.trunc(w / div), oh = Math.trunc(h / div);

  galleryImg = view(ps_malloc(u32(Math.imul(u32(Math.imul(u32(ow), u32(oh))), 2))), Uint16Array);
  if (!galleryImg) { free(jpg); pxlog("Out of memory for image"); return false; }

  let ok = jpg2rgb565(jpg, len, view(galleryImg, Uint8Array), sc);
  free(jpg);
  if (!ok) { galleryFree(); pxlog("Decode failed"); return false; }

  galleryImgW = ow; galleryImgH = oh;
  let nm = strrchr(path, ch('/'));
  let l = new Uint8Array(64);
  snprintf(l, l.length, S("%s  %dx%d shown as %dx%d"), nm ? ptrAdd(nm, 1) : path, w, h, ow, oh);
  pxlog(jstr(l));
  return true;
}

// ==================== VOICE MEMOS ====================
// First thing in this OS to actually switch on the mic/speaker I2S lines
// (previously just wired and left off, see FINDINGS §12). Two independent
// I2S peripherals: mic on I2S_NUM_0 (RX), speaker on I2S_NUM_1 (TX), so
// recording and playback never share one driver.

function audioMicBegin() {
  if (audioMicReady) return true;
  let cfg = mk(i2s_config_t);
  cfg.mode                 = (I2S_MODE_MASTER | I2S_MODE_RX);
  cfg.sample_rate           = AUDIO_SAMPLE_RATE;
  cfg.bits_per_sample       = I2S_BITS_PER_SAMPLE_16BIT;
  cfg.channel_format        = I2S_CHANNEL_FMT_ONLY_LEFT;  // mono mic, L/R pin tied low
  cfg.communication_format  = I2S_COMM_FORMAT_STAND_I2S;
  cfg.intr_alloc_flags      = ESP_INTR_FLAG_LEVEL1;
  // 8 x 512 = 4096 samples of headroom before the mic queue overflows,
  // matching the speaker. Costs 8KB of RAM, buys a lot of slack on a slow
  // SD write.
  cfg.dma_buf_count         = 8;
  cfg.dma_buf_len           = 512;
  let pins = mk(i2s_pin_config_t);
  pins.bck_io_num   = MIC_SCK;
  pins.ws_io_num    = MIC_WS;
  pins.data_out_num = I2S_PIN_NO_CHANGE;
  pins.data_in_num  = MIC_SD;

  if (i2s_driver_install(I2S_NUM_0, cfg, 0, null) != ESP_OK) { pxlog("Mic driver install failed"); return false; }
  if (i2s_set_pin(I2S_NUM_0, pins) != ESP_OK) { i2s_driver_uninstall(I2S_NUM_0); pxlog("Mic pin config failed"); return false; }
  i2s_zero_dma_buffer(I2S_NUM_0);
  audioMicReady = true;
  return true;
}

function audioMicEnd() {
  if (!audioMicReady) return;
  i2s_driver_uninstall(I2S_NUM_0);
  audioMicReady = false;
}

function audioSpkBegin() {
  if (audioSpkReady) return true;
  let cfg = mk(i2s_config_t);
  cfg.mode                 = (I2S_MODE_MASTER | I2S_MODE_TX);
  cfg.sample_rate           = AUDIO_SAMPLE_RATE;
  cfg.bits_per_sample       = I2S_BITS_PER_SAMPLE_16BIT;
  cfg.channel_format        = I2S_CHANNEL_FMT_ONLY_LEFT;  // matches how it was recorded
  cfg.communication_format  = I2S_COMM_FORMAT_STAND_I2S;
  cfg.intr_alloc_flags      = ESP_INTR_FLAG_LEVEL1;
  // 8 x 512 = 4096 samples = 256ms of audio buffered ahead (was 4 = 128ms).
  // Pure headroom: it costs 8KB of RAM and doubles how long the hardware can
  // keep playing while nothing is refilling it.
  cfg.dma_buf_count         = 8;
  cfg.dma_buf_len           = 512;
  let pins = mk(i2s_pin_config_t);
  pins.bck_io_num   = SPK_BCLK;
  pins.ws_io_num    = SPK_LRC;
  pins.data_out_num = SPK_DIN;
  pins.data_in_num  = I2S_PIN_NO_CHANGE;

  if (i2s_driver_install(I2S_NUM_1, cfg, 0, null) != ESP_OK) { pxlog("Speaker driver install failed"); return false; }
  if (i2s_set_pin(I2S_NUM_1, pins) != ESP_OK) { i2s_driver_uninstall(I2S_NUM_1); pxlog("Speaker pin config failed"); return false; }
  i2s_zero_dma_buffer(I2S_NUM_1);
  audioSpkRateNow = AUDIO_SAMPLE_RATE;   // a new driver runs at 16000 (Music changes it, 11 Nov)
  audioSpkReady = true;
  return true;
}

function audioSpkEnd() {
  // Never uninstall the driver while audioTask() is inside i2s_write().
  ringtonePlaying = false;
  for (let i = 0; i < 30 && audioTaskInWrite; i++) delay(10);
  if (!audioSpkReady) return;
  if (musicLoaded()) return;     // Music has a song loaded: the speaker stays on for it (11 Nov)
  i2s_driver_uninstall(I2S_NUM_1);
  audioSpkReady = false;
}

// ---- WAV file: 44-byte canonical PCM header ----
// Written as a placeholder when recording starts (sizes unknown yet), then
// patched in place once the take is saved and the real byte counts exist.
class WavHeader {
  constructor() {
    this.riff = new Uint8Array([ch('R'),ch('I'),ch('F'),ch('F')]);
    this.chunkSize = 0;
    this.wave = new Uint8Array([ch('W'),ch('A'),ch('V'),ch('E')]);
    this.fmt_ = new Uint8Array([ch('f'),ch('m'),ch('t'),ch(' ')]);
    this.fmtSize = 16;
    this.audioFmt = 1;   // PCM
    this.numCh = 1;
    this.sampleRate = AUDIO_SAMPLE_RATE;
    this.byteRate = u32(AUDIO_BYTES_PER_SEC);
    this.blockAlign = AUDIO_BYTES_PER_SAMPLE;
    this.bitsPerSmp = 16;
    this.data = new Uint8Array([ch('d'),ch('a'),ch('t'),ch('a')]);
    this.dataSize = 0;
  }
}
WavHeader.$f = [['riff', ['u8', 4], 0], ['chunkSize', 'u32', 4], ['wave', ['u8', 4], 8], ['fmt_', ['u8', 4], 12], ['fmtSize', 'u32', 16], ['audioFmt', 'u16', 20], ['numCh', 'u16', 22], ['sampleRate', 'u32', 24], ['byteRate', 'u32', 28], ['blockAlign', 'u16', 32], ['bitsPerSmp', 'u16', 34], ['data', ['u8', 4], 36], ['dataSize', 'u32', 40]];
WavHeader.$size = 44;

function wavWriteHeader(f, pcmBytes) {
  let h = new WavHeader();
  h.chunkSize = u32(36 + pcmBytes);
  h.dataSize  = pcmBytes;
  f.seek(0);
  f.write(h, 44 /*sizeof(h)*/);
}

// The next REC_nnnn.WAV: one past the highest on the card, the same rule as
// nextPhotoPath(). On 8 Nov a restart reset the counter and a new memo took
// the free number 2, between 1 and 3.
function nextVoicePath(out, n) {
  if (voiceLastNum == 0) voiceLastNum = sdHighestNum(S("/VOICE"), S("REC_"));
  for (let i = voiceLastNum + 1; i <= 9999; i++) {
    snprintf(out, n, S("/VOICE/REC_%04d.WAV"), i);
    if (!SD.exists(out)) { voiceLastNum = i; return; }
  }
  snprintf(out, n, S("/VOICE/REC_9999.WAV"));
}

function voiceRecSetFlash(msg) {
  strncpy(voiceRecFlash, msg, u32(voiceRecFlash.length - 1));
  voiceRecFlash[voiceRecFlash.length - 1] = 0;
  voiceRecFlashUntil = u32(millis() + 1800);
  pxlog(jstr(msg));
}

// mm:ss - used for both the recording timer and the playback counter.
function formatMMSS(totalSec, out, n) {
  snprintf(out, n, S("%u:%02u"), (Math.trunc(totalSec / 60)), (totalSec % 60));
}

function voiceDurationSec(idx) {
  if (idx < 0 || idx >= voiceCount || voiceSizes[idx] < 44) return 0;
  return Math.trunc((u32(voiceSizes[idx] - 44)) / u32(AUDIO_BYTES_PER_SEC));
}

function voiceScan() {
  voiceCount = 0;
  voiceIdx = 0; voiceTop = 0;
  if (!sdReady) return;
  let dir = SD.open(S("/VOICE"));
  if (!dir.valid() || !dir.isDirectory()) { if (dir.valid()) dir.close(); return; }
  let e = dir.openNextFile();
  while (e.valid() && voiceCount < VOICE_MAX) {
    if (!e.isDirectory()) {
      let n = jstr(e.name());
      let sl = n.lastIndexOf(String.fromCharCode(ch('/')));
      if (sl >= 0) n = n.substring(u32(sl + 1));
      let up = n; up = strUpper(up);
      if (up.endsWith(".WAV")) {
        strncpy(voiceNames[voiceCount], cstr(n), 31);
        voiceNames[voiceCount][31] = 0;
        voiceSizes[voiceCount] = e.size();
        voiceCount++;
      }
    }
    e.close();
    e = dir.openNextFile();
  }
  if (e.valid()) e.close();
  dir.close();

  // same insertion sort the gallery uses, so newest-numbered files read last
  for (let i = 1; i < voiceCount; i++) {
    let nm = new Uint8Array(32); let sz = 0;
    strncpy(nm, voiceNames[i], 32); sz = voiceSizes[i];
    let j = i - 1;
    while (j >= 0 && strcmp(voiceNames[j], nm) > 0) {
      strncpy(voiceNames[j + 1], voiceNames[j], 32);
      voiceSizes[j + 1] = voiceSizes[j];
      j--;
    }
    strncpy(voiceNames[j + 1], nm, 32); voiceSizes[j + 1] = sz;
  }
  let l = new Uint8Array(48); snprintf(l, l.length, S("Voice: %d recording(s)"), voiceCount); pxlog(jstr(l));
}

// ---- Recording ----
function voiceRecEnter() {
  voiceRecState = VREC_READY;
  voiceRecBytes = 0;
  voiceRecElapsedMs = 0;
  voiceRecPath[0] = 0;
  voiceRecFlashUntil = 0;
  state = ST_VOICE_REC;
}

// Leaves headroom rather than aiming at literally 0 bytes free - other parts
// of the OS (messages, contacts) also write to the card and shouldn't get
// starved because a recording ate every last byte.
const VOICE_FREE_MARGIN_BYTES = (256 * 1024);

function voiceRecStartCapture() {
  if (voiceRecState != VREC_READY || !sdReady) return;
  musicPause();              // or the mic would record the music (11 Nov)

  let freeBytes = (u32(sdSizeMB - sdUsedMB)) * 1024 * 1024;
  if (freeBytes <= VOICE_FREE_MARGIN_BYTES) { voiceRecSetFlash(S("Card full")); return; }
  voiceRecMaxBytes = ((u32(freeBytes - VOICE_FREE_MARGIN_BYTES)));

  nextVoicePath(voiceRecPath, voiceRecPath.length);
  voiceRecFile = SD.open(voiceRecPath, FILE_WRITE);
  if (!voiceRecFile.valid()) { voiceRecSetFlash(S("Could not create file")); return; }
  let placeholder = new WavHeader();                       // sizes filled in on save
  voiceRecFile.write(placeholder, 44 /*sizeof(placeholder)*/);

  if (!audioMicBegin()) {
    voiceRecFile.close();
    SD.remove(voiceRecPath);
    voiceRecSetFlash(S("Mic not available"));
    return;
  }

  // I2S MEMS mics settle for a handful of ms after the clocks start, and
  // whatever they output during that window tends to land as a pop at the
  // very start of the take. Give it a moment, then throw away anything it
  // queued during the settle so the pop never reaches the file - only needed
  // on a fresh start, not on resume (see voiceRecResume), since the mic
  // never gets turned off across a pause.
  delay(30);
  i2s_zero_dma_buffer(I2S_NUM_0);

  voiceRecBytes = 0;
  voiceRecStartMs = millis();
  voiceRecState = VREC_RECORDING;
}

// Resumes into the SAME open file after a pause. voiceRecStartCapture() is
// deliberately fresh-take-only (creates a new file each time), which is why
// pressing OK to resume after a pause used to silently do nothing - its
// VREC_READY-only guard rejected the VREC_PAUSED call. The mic driver is
// left running across a pause (voiceRecPause() doesn't call audioMicEnd()),
// so resuming just needs to restart the clock and go back to RECORDING.
function voiceRecResume() {
  if (voiceRecState != VREC_PAUSED) return;
  voiceRecStartMs = millis();
  voiceRecState = VREC_RECORDING;
}

function voiceRecPause() {
  if (voiceRecState != VREC_RECORDING) return;
  voiceRecElapsedMs = u32(voiceRecElapsedMs + (u32(millis() - voiceRecStartMs)));
  voiceRecState = VREC_PAUSED;
}

// Called every loop() while RECORDING - drains whatever the mic's DMA buffer
// has queued and appends it to the file. Non-blocking (0 tick timeout) so a
// quiet moment with nothing queued never stalls the rest of the OS.
let voiceRecTick__buf = new Int16Array(2048);
function voiceRecTick() {
  if (voiceRecState != VREC_RECORDING) return;
  // Sized to the full DMA capacity (dma_buf_count=4 * dma_buf_len=512 samples
  // = 2048 samples), not just one DMA buffer's worth. An occasional slow SD
  // write (common cause of the clicks/dropouts you were hearing) can leave
  // the mic's DMA queue backed up for a tick or two; draining the whole
  // backlog in one read instead of catching up 512 samples at a time gives
  // more headroom before it overflows and starts dropping samples.
  /* static: voiceRecTick__buf */
  let bytesRead = 0;
  i2s_read(I2S_NUM_0, voiceRecTick__buf, 4096 /*sizeof(buf)*/, ref(() => bytesRead, v => bytesRead = u32(v), 'u32'), 0);
  if (bytesRead == 0) return;

  if (u32(voiceRecBytes + bytesRead) > voiceRecMaxBytes) {
    bytesRead = (voiceRecMaxBytes > voiceRecBytes) ? (u32(voiceRecMaxBytes - voiceRecBytes)) : 0;
  }
  if (bytesRead > 0) {
    let written = voiceRecFile.write(view(voiceRecTick__buf, Uint8Array), bytesRead);
    voiceRecBytes = u32(voiceRecBytes + written);
  }
  if (voiceRecBytes >= voiceRecMaxBytes) {
    voiceRecPause();
    voiceRecSetFlash(S("Card full - stopped"));
  }
}

// Waits for audioTask() to finish the memo step it is in, if any. Call it
// AFTER stopping the memo (voicePlaying false, or voiceRecState no longer
// RECORDING): from then on the task starts no new step, and once this returns
// it is not inside one, so the file can be closed and the mic or speaker
// switched off. A step is a fraction of a second; 0.6 s is the most it waits.
function memoWaitIdle() {
  for (let i = 0; i < 60 && audioTaskInMemo; i++) delay(10);
}

function voiceRecSave() {
  if (voiceRecState == VREC_RECORDING) voiceRecPause();
  if (voiceRecState != VREC_PAUSED) return;
  memoWaitIdle();            // the audio task out of voiceRecTick() first
  wavWriteHeader(voiceRecFile, voiceRecBytes);
  voiceRecFile.close();
  audioMicEnd();
  sdUsedMB = u32((Math.trunc(SD.usedBytes() / (1024 * 1024))));
  pxlog("Saved " + jstr(voiceRecPath));
  voiceScan();
  // Land on the one just saved, found by its name and scrolled into view. It
  // is the last row now that numbers only go up, but looking it up means a
  // stray file on the card can never put the highlight on the wrong one.
  let base = strrchr(voiceRecPath, ch('/'));
  base = base ? ptrAdd(base, 1) : voiceRecPath;
  voiceIdx = voiceCount > 0 ? voiceCount - 1 : 0;
  for (let i = 0; i < voiceCount; i++)
    if (!strcmp(voiceNames[i], base)) { voiceIdx = i; break; }
  if (voiceIdx >= voiceTop + 8) voiceTop = voiceIdx - 7;
  state = ST_VOICE;
}

function voiceRecDiscard() {
  if (voiceRecState == VREC_RECORDING) voiceRecPause();
  memoWaitIdle();            // the same as Save
  if (voiceRecFile.valid()) voiceRecFile.close();
  if (voiceRecPath[0]) SD.remove(voiceRecPath);
  audioMicEnd();
  pxlog("Recording discarded");
  state = ST_VOICE;
}

// ---- Playback ----
function voicePlayEnter(idx) {
  if (idx < 0 || idx >= voiceCount) return;
  voiceIdx = idx;
  voiceFromFiles = false;    // the memo list's own (the File explorer sets it after)
  let path = new Uint8Array(48);
  snprintf(path, path.length, S("/VOICE/%s"), voiceNames[idx]);
  voicePlayOpen(path);
}

// A recording by its path, opened paused: the memo list's, and the File
// explorer's (9 Nov).
function voicePlayOpen(path) {
  voicePlayFile = SD.open(path, FILE_READ);
  if (!voicePlayFile.valid()) { pxlog("Cannot open recording"); return; }

  let fileBytes = voicePlayFile.size();
  voicePlayTotalBytes = (fileBytes > 44) ? (u32(fileBytes - 44)) : 0;   // trust actual size,
  voicePlayPosBytes = 0;                                            // not just the header
  voicePlayFile.seek(44);
  voicePlaying = false;      // opens paused - OK starts it, same convention as everywhere else
  state = ST_VOICE_PLAY;
}

function voicePlayExit() {
  voicePlaying = false;
  memoWaitIdle();            // out of voicePlayTick() before the file and speaker go
  if (voicePlayFile.valid()) voicePlayFile.close();
  audioSpkEnd();
  state = voiceFromFiles ? ST_FILES : ST_VOICE;   // back where it was opened (9 Nov)
  voiceFromFiles = false;
}

function voicePlayToggle() {
  if (!voicePlayFile.valid()) return;
  if (!voicePlaying) {
    if (voicePlayPosBytes >= voicePlayTotalBytes) {   // replay from the start
      voicePlayPosBytes = 0;
      voicePlayFile.seek(44);
    }
    musicPause();            // the memo takes the speaker: Music pauses (11 Nov)
    if (!audioSpkBegin()) { pxlog("Speaker not available"); return; }
    voicePlaying = true;
  } else {
    voicePlaying = false;
    memoWaitIdle();          // the audio task may be mid-write; let it finish first
    // The I2S clock keeps running even with nothing new queued, so it just
    // re-transmits whatever it last had - flush it here or pausing leaves
    // the tail end of the last chunk looping in the background.
    i2s_zero_dma_buffer(I2S_NUM_1);
  }
}

function voicePlaySeek(deltaSec) {
  if (!voicePlayFile.valid()) return;
  // Playback holds still while the position moves: voicePlayTick() reads the
  // same file and the same counter from the audio task.
  let was = voicePlaying;
  voicePlaying = false;
  memoWaitIdle();
  let deltaBytes = deltaSec * AUDIO_BYTES_PER_SEC;
  let np = i32(voicePlayPosBytes) + deltaBytes;
  if (np < 0) np = 0;
  if (u32(np) > voicePlayTotalBytes) np = i32(voicePlayTotalBytes);
  voicePlayPosBytes = u32(np);
  voicePlayFile.seek(u32(44 + voicePlayPosBytes));
  voicePlaying = was;
}

// ==================== VOLUME ====================
// Declared up here, not down with the audio task, because voicePlayTick()
// needs them and it is defined earlier in the file.
//
// Amplitude per volume level, deliberately NOT linear: loudness is perceived
// roughly logarithmically, so evenly-spaced amplitudes would make the top few
// bars sound almost identical and the bottom few inaudible.
//
// Index 0 is 0 on purpose - it IS silence, and both the ringtone generator and
// the confirmation blip clamp to it so that silent (-1) and vibrate (0) produce
// no sound at all. Voice memo playback clamps to 1 instead: pressing play is an
// explicit request to hear something, and silent mode governs the ringer, not
// media.
const RING_AMPLITUDE = new Int16Array([ 0, 260, 480, 850, 1400, 2200, 3300, 4700, 6300, 8000 ]);

const VOL_MIN = -1;   // silent
const VOL_MAX = 9;

// Called every loop() while playing - feeds the speaker from the file. Uses a
// bounded timeout (not 0, not portMAX_DELAY): i2s_write blocking on DMA space
// yields to the scheduler rather than busy-spinning, so this paces itself to
// real playback speed without hogging the loop the way a longer/unbounded
// wait could.
// PLAY_TAIL_MS of silence after a memo's last sample, from the audio task.
// i2s_write() waits for room, so when this returns the end of the recording
// has been heard and only silence is left in the DMA ring. Stops early if
// playback is stopped meanwhile: voicePlayExit() and Delete clear voicePlaying
// BEFORE audioSpkEnd(), and audioSpkEnd() waits on audioTaskInWrite.
const voicePlayTail__zeros = tarr(Int16Array, 256, [0]);
function voicePlayTail() {
  /* static: voicePlayTail__zeros */
  let left = PLAY_TAIL_SAMPLES;
  while (left > 0) {
    audioTaskInWrite = true;
    if (!voicePlaying || !audioSpkReady) { audioTaskInWrite = false; return; }
    let n = (left > 256) ? 256 : left;
    let written = 0;
    i2s_write(I2S_NUM_1, voicePlayTail__zeros, u32(Math.imul(n, 2 /*sizeof int16_t*/)), ref(() => written, v => written = u32(v), 'u32'), pdMS_TO_TICKS(200));
    audioTaskInWrite = false;
    left = u32(left - n);
  }
}

   // the media volume (13 Nov) - defined with Music, further down
let voicePlayTick__buf = new Int16Array(512);
function voicePlayTick() {
  if (!voicePlaying || !voicePlayFile.valid()) return;
  /* static: voicePlayTick__buf */
  let want = 1024 /*sizeof(buf)*/;
  if (u32(voicePlayPosBytes + want) > voicePlayTotalBytes) want = u32(voicePlayTotalBytes - voicePlayPosBytes);
  if (want == 0) {
    // Reached the end. First the silent tail, so the last quarter-second
    // still waiting in the DMA ring is heard - it used to be thrown away.
    // THEN the reset: the I2S TX peripheral doesn't stop on its own when
    // nothing new is queued - it keeps its clock running by re-transmitting
    // the last buffer it has, over and over, until told otherwise. That's
    // the "it loops when it ends" behaviour: treat end-of-playback as a
    // real reset and flush the queue so it actually goes silent.
    voicePlayTail();
    if (voicePlayPosBytes >= voicePlayTotalBytes) {   // not restarted during the tail
      voicePlaying = false;
      i2s_zero_dma_buffer(I2S_NUM_1);
    }
    return;
  }

  let n = voicePlayFile.read(view(voicePlayTick__buf, Uint8Array), want);
  if (n == 0) { voicePlaying = false; i2s_zero_dma_buffer(I2S_NUM_1); return; }  // same reset, unexpected read failure

  // Apply the volume. There was NO gain stage here at all - recordings always
  // played at whatever level they were captured, ignoring the volume setting
  // completely.
  //
  // The media volume (the owner, 13 Nov: Music's, shared by Voice memos and the
  // games - set it in one, it is the same in all; it was the ringer's level).
  // 1..9, NOT 0, and that is deliberate: this is the opposite of the
  // ringtone. Silent mode governs the RINGER, not media - if you press play on
  // a recording you have explicitly asked to hear it, so the floor is the
  // quietest audible step rather than silence.
  //
  // RING_AMPLITUDE is already a roughly geometric curve, which is what
  // perceived loudness needs - a linear 1..9 would feel like most of the range
  // did nothing. Reusing it keeps one volume curve in the OS instead of two.
  // >> 13 is 8192, so level 9 is 8000/8192 = 98% - unity for practical
  // purposes, and no divide in the sample loop.
  {
    let lvl = musicVol();                 // the media volume: 1..9 (13 Nov)
    let g = RING_AMPLITUDE[lvl];
    let samples = i32((Math.trunc(n / 2 /*sizeof int16_t*/)));
    for (let i = 0; i < samples; i++)
      voicePlayTick__buf[i] = i16(((voicePlayTick__buf[i] * g) >> 13));
  }

  // Bounded, but not zero: a strict 0ms timeout (the previous fix) gives up
  // instantly whenever the DMA queue is momentarily full, which is normal -
  // but if anything else in loop() (an SD read, modemPoll(), sdPoll()) ever
  // runs a bit long, nothing refills the queue in time, it runs dry, and the
  // I2S hardware repeats the last buffer it has until new data arrives -
  // that's the "stuck replaying the same frames" you heard. A short wait
  // (well under the ~128ms the DMA queue can hold) is enough to guarantee
  // delivery and self-correct after a brief stall, without blocking the loop
  // long enough to meaningfully affect the CPU reading the way 50ms did.
  let written = 0;
  i2s_write(I2S_NUM_1, voicePlayTick__buf, n, ref(() => written, v => written = u32(v), 'u32'), pdMS_TO_TICKS(15));
  voicePlayPosBytes = u32(voicePlayPosBytes + written);
  if (written < n) voicePlayFile.seek(u32(44 + voicePlayPosBytes));  // put back what didn't send
}

// ---- Ringtone ----
// No WAV file needed - synthesizes the active melody as square-wave PCM
// samples on the fly, one note at a time, fed through the exact same
// i2s_write(I2S_NUM_1, ...) path voice memo playback already proves works.
// Ticked non-blocking from loop(), same shape/bounded-timeout reasoning as
// voicePlayTick(); active only while callState == CALL_RINGING, stopped the
// instant ATA/ATH fires (see callFinalize() and the answer path).
//
// Note table shape matches the ringtone composer tool's output exactly
// (RingtoneNote{hz, ms} array) - copy a melody straight from the tool's
// "firmware note table" box and paste it in as a new array below, then add
// it to RINGTONES[]/RINGTONE_COUNT so it shows up in the picker.
// hz == 0 is a pause/rest, not a tone.
class RingtoneNote {
  constructor() {
    this.hz = 0;
    this.ms = 0;
  }
}
RingtoneNote.$f = [['hz', 'i32', 0], ['ms', 'i32', 4]];
RingtoneNote.$size = 8;

// Each melody is its own fixed array (C doesn't support a clean array-of
// variable-length-arrays, so this is the simplest layout for a small,
// hand-curated set) - add more the same way: array + RingtoneDef entry.
