class RingtoneDef {
  constructor() {
    this.name = null;
    this.notes = null;
    this.count = 0;
  }
}
RingtoneDef.$f = [['name', 'ptr', 0], ['notes', 'ptr', 4], ['count', 'i32', 8]];
RingtoneDef.$size = 12;

