  bjCentre(212, S("Six horses, first to the flag"), 8, COL_GRAY8);
  bjCentre(226, S("Your horse wins: 6x your bet"), 8, COL_GRAY8);
  bjCentre(270, S("OK: pick your horse"), 14, COL_GRAY8);
