// ---- the game ----
const STAR_TITLE = 0;
const STAR_PLAY = 1;
const STAR_OVER = 2;
let starPhase = STAR_TITLE;
let starPaused = false;
let starMs = 0;                  // the game's clock (ms), for the blinks and flames
let starScore = 0, starBest = 0; // the best: /games.dat's
let starNewBest = false;
let starLives = STAR_LIVES;
let starNextExtra = STAR_EXTRA;
let starPower = 1;
let starWave = 0;                // 1, 2, ... (wave 16 is wave 1's second round)
let starBannerMs = 0;            // the wave's banner still showing
let starWaveMs = 0;              // since the wave came (after its banner)
let starSent = new Int32Array(12);        // of each line, how many have come
let starCallMs = 0, starCallKind = 0;   // a mini boss's name still showing
let starX = 0, starY = 0;        // your ship's top left (px)
let starHeld = 0;                // keys held: 1 left, 2 right, 4 up, 8 down, 16 fire
let starLastH = 0, starLastV = 0;   // the last of left/right (-1/1) and of up/down pressed
let starShotWait = 0;            // ms to the next shot
let starSafeMs = 0;              // can't be hit yet
let starDyingMs = 0;             // your ship blowing up
let starSnd = 0;                 // the steps' sounds: 1 a hit, 2 one down, 4 your ship hit, 8 a power-up, 16 a ship more,
                                   // 32 a boss comes, 64 a boss down, 128 game over, 256 a new wave, 512 the laser fires,
                                   // 1024 a shot fired (a pew)
let starRand = 0x5F3759DF;
// your shots
let starShotOn = new Uint8Array(24);
let starShotX = new Float32Array(24), starShotY = new Float32Array(24), starShotVX = new Float32Array(24);
// theirs
let starBulOn = new Uint8Array(96);
let starBulX = new Float32Array(96), starBulY = new Float32Array(96), starBulVX = new Float32Array(96), starBulVY = new Float32Array(96);   // the middle of a 9 x 9 ball
// the enemies
let starFoeOn = new Uint8Array(32);
let starFoeKind = new Int32Array(32), starFoeHP = new Int32Array(32), starFoeMax = new Int32Array(32), starFoeMs = new Int32Array(32), starFoeFire = new Int32Array(32), starFoeFlash = new Int32Array(32);
let starFoeStage = new Int32Array(32), starFoeAct = new Int32Array(32), starFoeSub = new Int32Array(32);
let starFoeX = new Float32Array(32), starFoeY = new Float32Array(32), starFoeVX = new Float32Array(32), starFoeVY = new Float32Array(32), starFoeX0 = new Float32Array(32), starFoeAng = new Float32Array(32), starFoeTX = new Float32Array(32);
// the Fortress's laser: 0 none, 1 the warning line (it moves over you), 2 the beam
let starLaser = 0, starLaserMs = 0;
// power-ups
let starCapOn = new Uint8Array(4);
let starCapX = new Float32Array(4), starCapY = new Float32Array(4);
// sparks
let starBitMs = new Int32Array(128);        // > 0: alive
let starBitX = new Float32Array(128), starBitY = new Float32Array(128), starBitVX = new Float32Array(128), starBitVY = new Float32Array(128);
let starBitHot = new Int32Array(128);       // its life at the start (the colour goes by the share left)
// the stars: three depths
let starStarX = new Int32Array(18), starStarD = new Int32Array(18);
let starStarY = new Float32Array(18);
const STAR_STAR_V = new Float32Array([16.0, 36.0, 72.0]);
// on the phone: the clock, the frames, the sounds
let starLastMs = 0;           // loop()'s time last seen (0: start afresh)
let starClockMs = 0;             // time not stepped yet
let starNextFrame = 0;
let starRedraw = true;           // the next frame draws the whole screen
let starInFrame = false;         // starFrame() is drawing (anything else drawing the game: the whole screen next)
let starShownPhase = -1;         // what the screen shows
let starShownPaused = false;
let starSndUntil = 0;         // the sound playing ends then...
let starSndRank = 0;             // ...and matters this much: 3 a tune, 2 a pop, 1 a tick or a pew

function starRnd() { starRand = u32(starRand ^ u32(starRand << 13)); starRand = u32(starRand ^ (starRand >>> 17)); starRand = u32(starRand ^ u32(starRand << 5)); return starRand; }
function starRndI(a, b) { return a + i32((starRnd() % u32((b - a + 1)))); }   // a..b
function starClamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
// sin of t turns, with no maths library (as the play page's build, which has none - the same numbers)
function starFloor(v) { let i = Math.trunc(v); return f32(((v < f32(i)) ? i - 1 : i)); }
function starSinT(t) {
  const PI_F = f32(3.14159265);
  let x = f32(f32((f32(t + 0.5)) - starFloor(f32(t + 0.5))) - 0.5);
  x = f32(x * f32(2 * PI_F));
  if (x > f32(PI_F / 2)) x = f32(PI_F - x);
  if (x < f32(-PI_F / 2)) x = f32(-PI_F - x);
  let x2 = f32(x * x);
  return f32(x * (f32(1 - f32(f32(x2 / 6) * (f32(1 - f32(f32(x2 / 20) * (f32(1 - f32(f32(x2 / 42) * (f32(1 - f32(f32(x2 / 72) * (f32(1 - f32(x2 / 110))))))))))))))));
}
function starCosT(t) { return starSinT(f32(t + 0.25)); }
function starRound() { let r = Math.trunc((starWave - 1) / STAR_WAVES); return f32((r > 4 ? 4 : r)); }   // 0 the first round, 1 the second...
function starFast() { return f32(1.0 + f32(f32(0.15) * starRound())); }                                       // their speed
function starFireEvery(ms) { return Math.trunc((f32(f32(ms) / starFast()))); }                         // ...and their shots
function starLines() { return STAR_WAVE[(starWave - 1) % STAR_WAVES]; }            // this wave's lines

// ---- the things in the field ----
function starStarsNew() {
  for (let i = 0; i < STAR_STARS; i++) {
    starStarD[i] = i < 8 ? 0 : (i < 14 ? 1 : 2);
    starStarX[i] = starRndI(0, IN_W - 1);
    starStarY[i] = f32(starRndI(0, IN_H - 1));
  }
}
function starClearAll() {
  for (let i = 0; i < STAR_SHOTS; i++) starShotOn[i] = false;
  for (let i = 0; i < STAR_BULLETS; i++) starBulOn[i] = false;
  for (let i = 0; i < STAR_FOES; i++) starFoeOn[i] = false;
  for (let i = 0; i < STAR_CAPS; i++) starCapOn[i] = false;
  for (let i = 0; i < STAR_BITS; i++) starBitMs[i] = 0;
  starLaser = 0; starLaserMs = 0; starCallMs = 0;
}
function starShipHome() { starX = f32((Math.trunc((0 + IN_W - STAR_SHIP_W) / 2))); starY = f32((STAR_B - STAR_SHIP_H - 10)); }
function starWaveNew() {
  starWave++;
  starBannerMs = STAR_BANNER_MS; starWaveMs = 0;
  for (let i = 0; i < STAR_LINES; i++) starSent[i] = 0;
  starSnd |= 256;
}
function starNewGame() {
  starPhase = STAR_PLAY; starPaused = false; starMs = 0;
  starScore = 0; starNewBest = false; starLives = STAR_LIVES; starNextExtra = STAR_EXTRA; starPower = 1;
  starWave = 0;
  starClearAll();
  starShipHome();
  starShotWait = 0; starSafeMs = STAR_SAFE_MS; starDyingMs = 0;
  starWaveNew();
}

function starSpark(x, y, n, ms, v) {          // an explosion: n sparks from (x, y)
  for (let k = 0; k < n; k++) {
    let i = 0;
    while (i < STAR_BITS && starBitMs[i] > 0) i++;
    if (i == STAR_BITS) return;
    let a = f32(f32(f32(k) / f32(n)) + f32(f32((starRnd() % 100)) / 800.0));
    let sp = f32(v * (f32(0.5 + f32(f32((starRnd() % 100)) / 200.0))));
    starBitX[i] = x; starBitY[i] = y;
    starBitVX[i] = f32(sp * starSinT(a)); starBitVY[i] = f32(-sp * starCosT(a));
    starBitMs[i] = starBitHot[i] = ms - i32((starRnd() % 120));
  }
}
function starShoot() {                                                  // your shots: one, two side by side, or three spread
  let cx = f32(starX + f32(Math.trunc(STAR_SHIP_W / 2))), y = f32(starY - 6);
  let want = starPower == 1 ? 1 : (starPower == 2 ? 2 : 3);
  for (let k = 0; k < want; k++) {
    let i = 0;
    while (i < STAR_SHOTS && starShotOn[i]) i++;
    if (i == STAR_SHOTS) return;
    starShotOn[i] = true; starShotY[i] = y; starShotVX[i] = 0;
    starSnd |= 1024;                                                // a pew (one for the two or three side by side)
    if (want == 1) starShotX[i] = f32(cx - 1);
    else if (want == 2) starShotX[i] = f32(f32(cx - 1) + (k == 0 ? -6.0 : 6.0));
    else { starShotX[i] = f32(f32(cx - 1) + f32(f32((k - 1)) * 5.0)); starShotVX[i] = f32(f32((k - 1)) * 80.0); }
  }
}
function starBullet(x, y, vx, vy) {             // one of theirs, from (x, y): its middle
  let i = 0;
  while (i < STAR_BULLETS && starBulOn[i]) i++;
  if (i == STAR_BULLETS) return;
  starBulOn[i] = true; starBulX[i] = x; starBulY[i] = y; starBulVX[i] = vx; starBulVY[i] = vy;
}
function starAngled(x, y, turns, v) {           // a shot at an angle: 0 straight down, + to your right
  starBullet(x, y, f32(v * starSinT(turns)), f32(v * starCosT(turns)));
}
function starAimedOff(x, y, v, off) {           // a shot at your ship, turned `off` turns
  let dx = f32(f32(starX + f32(Math.trunc(STAR_SHIP_W / 2))) - x), dy = f32(f32(starY + f32(Math.trunc(STAR_SHIP_H / 2))) - y);
  let d = sqrtf(f32(f32(dx * dx) + f32(dy * dy)));
  if (d < 1) { dx = 0; dy = 1; d = 1; }
  dx = f32(dx / d); dy = f32(dy / d);
  let s = starSinT(off), c = starCosT(off);
  starBullet(x, y, f32(v * (f32(f32(dx * c) + f32(dy * s)))), f32(v * (f32(f32(dy * c) - f32(dx * s)))));
}
function starAimed(x, y, v) { starAimedOff(x, y, v, 0); }
function starFoeNew(kind, midX) {                                // a new one at the top; its slot, or -1 (the field is full)
  let i = 0;
  while (i < STAR_FOES && starFoeOn[i]) i++;
  if (i == STAR_FOES) return -1;
  let w = STAR_FOE_W[kind], h = STAR_FOE_H[kind];
  if (midX < 0) midX = starRndI(0 + 10 + Math.trunc(w / 2), IN_W - 10 - Math.trunc(w / 2));
  starFoeOn[i] = true; starFoeKind[i] = kind;
  starFoeX[i] = f32((midX - Math.trunc(w / 2))); starFoeY[i] = f32((STAR_FT - h));
  starFoeX0[i] = starFoeX[i]; starFoeVX[i] = 0; starFoeVY[i] = 0; starFoeAng[i] = 0; starFoeTX[i] = 0;
  starFoeMs[i] = 0; starFoeFlash[i] = 0; starFoeStage[i] = 0; starFoeAct[i] = 0; starFoeSub[i] = 0;
  let r = Math.trunc(starRound());
  starFoeHP[i] = (starIsBoss(kind) || starIsMini(kind)) ? Math.trunc(STAR_FOE_HP[kind] * (4 + r) / 4) : STAR_FOE_HP[kind] + r;   // a round on: +25% / +1
  starFoeMax[i] = starFoeHP[i];
  starFoeFire[i] = 0;
  if (kind == STAR_WEAVER) starFoeFire[i] = starRndI(800, 2200);
  if (kind == STAR_GUNNER) starFoeFire[i] = 800;
  if (starIsMini(kind) || starIsBoss(kind)) {
    starFoeY[i] = f32((STAR_FT - h - 4));
    starFoeFire[i] = 1500;
    starSnd |= 32;
    if (starIsMini(kind)) { starCallMs = STAR_CALL_MS; starCallKind = kind; }
  }
  return i;
}
function starCapNew(x, y) {
  let i = 0;
  while (i < STAR_CAPS && starCapOn[i]) i++;
  if (i == STAR_CAPS) return;
  starCapOn[i] = true; starCapX[i] = f32(x - 8); starCapY[i] = f32(y - 9);
}
function starAddScore(pts) {
  starScore += pts;
  while (starScore >= starNextExtra) {
    starNextExtra += STAR_EXTRA;
    if (starLives < STAR_LIVES_MAX) { starLives++; starSnd |= 16; }
  }
}
// One of theirs hit `dmg` times: down at no hits left - its points, sparks, maybe a power-up.
function starFoeHit(i, dmg) {
  let k = starFoeKind[i];
  starFoeHP[i] -= dmg;
  let tick = true;
  if (!starIsMini(k) && !starIsBoss(k)) starFoeFlash[i] = 60;      // white for 60 ms...
  else if (starFoeFlash[i] <= 0) starFoeFlash[i] = 300;            // ...a boss for 50 ms, at most every 0.3 s,
  else tick = false;                                                // its tick with it
  let cx = f32(starFoeX[i] + f32(Math.trunc(STAR_FOE_W[k] / 2))), cy = f32(starFoeY[i] + f32(Math.trunc(STAR_FOE_H[k] / 2)));
  if (starFoeHP[i] > 0) { if (tick) starSnd |= 1; return; }
  starFoeOn[i] = false;
  let round = Math.trunc(starRound()) + 1;
  if (starIsBoss(k)) {
    starAddScore(STAR_FOE_PTS[k] * round);
    starSpark(f32(cx - 34), cy, 18, 700, 80.0); starSpark(f32(cx + 34), cy, 18, 700, 80.0); starSpark(cx, cy, 32, 900, 110.0);
    for (let b = 0; b < STAR_BULLETS; b++) starBulOn[b] = false;    // its shots go with it...
    for (let o = 0; o < STAR_FOES; o++) {                           // ...and the others in the field (no points)
      if (!starFoeOn[o]) continue;
      let ok = starFoeKind[o];
      starFoeOn[o] = false;
      starSpark(f32(starFoeX[o] + f32(Math.trunc(STAR_FOE_W[ok] / 2))), f32(starFoeY[o] + f32(Math.trunc(STAR_FOE_H[ok] / 2))), 8, 400, 70.0);
    }
    let line = starLines();                         // the wave's rest left out: it ends here
    for (let l = 0; l < STAR_LINES && line[l][0] >= 0; l++) starSent[l] = line[l][3];
    if (k == STAR_FORTRESS) starLaser = 0;
    starCapNew(f32(cx - 20), cy); starCapNew(f32(cx + 20), cy);
    starSnd |= 64;
    return;
  }
  if (starIsMini(k)) {
    starAddScore(STAR_FOE_PTS[k] * round);
    starSpark(cx, cy, 28, 700, 95.0);
    starCapNew(cx, cy);
    starSnd |= 64;
    return;
  }
  starAddScore(STAR_FOE_PTS[k]);
  starSpark(cx, cy, k == STAR_GUNNER ? 16 : 12, 450, 75.0);
  starSnd |= 2;
  let chance = k == STAR_GUNNER ? 50 : (k == STAR_WEAVER ? 5 : 0);
  if (chance && i32((starRnd() % 100)) < chance) starCapNew(cx, cy);
}
function starShipHit() {                                                // your ship blows up
  starSpark(f32(starX + f32(Math.trunc(STAR_SHIP_W / 2))), f32(starY + f32(Math.trunc(STAR_SHIP_H / 2))), 24, 800, 85.0);
  starDyingMs = STAR_DYING_MS;
  starHeld &= 16;                                                   // (the arrows let go: the next ship starts still)
  starSnd |= 4;
}

// ---- 10 ms ----
function starStarsStep() {
  for (let i = 0; i < STAR_STARS; i++) {
    starStarY[i] += f32(f32(STAR_STAR_V[starStarD[i]] * STAR_STEP_MS) / 1000.0);
    if (starStarY[i] >= IN_H) { starStarY[i] -= IN_H; starStarX[i] = starRndI(0, IN_W - 1); }
  }
}
function starShipStep() {
  if (starDyingMs > 0) return;
  let h = 0, v = 0;
  if ((starHeld & 3) == 3) h = starLastH; else if (starHeld & 1) h = -1; else if (starHeld & 2) h = 1;
  if ((starHeld & 12) == 12) v = starLastV; else if (starHeld & 4) v = -1; else if (starHeld & 8) v = 1;
  let d = f32(f32(STAR_SHIP_V * STAR_STEP_MS) / 1000.0);
  starX = starClamp(f32(starX + f32(f32(h) * d)), 0, f32((IN_W - STAR_SHIP_W)));
  starY = starClamp(f32(starY + f32(f32(v) * d)), f32((STAR_FT + 40)), f32((STAR_B - STAR_SHIP_H - 2)));
  if (starSafeMs > 0) starSafeMs -= STAR_STEP_MS;
  if (starShotWait > 0) starShotWait -= STAR_STEP_MS;
  let firing = (starHeld & 16) != 0;                               // the owner's pick: while fire is held
  if (firing && starShotWait <= 0) { starShoot(); starShotWait = STAR_SHOT_MS; }
}
// Side to side between the field's edges (4 px in), at its own speed.
function starBounce(i, speed) {
  let w = STAR_FOE_W[starFoeKind[i]];
  starFoeX[i] += f32(f32(f32(starFoeVX[i] * speed) * STAR_STEP_MS) / 1000.0);
  if (starFoeX[i] < f32((0 + 4))) { starFoeX[i] = f32((0 + 4)); starFoeVX[i] = -starFoeVX[i]; }
  if (starFoeX[i] > f32((IN_W - 4 - w))) { starFoeX[i] = f32((IN_W - 4 - w)); starFoeVX[i] = -starFoeVX[i]; }
}
// A mini boss's or big boss's way in: down to where it stays, then its attacks (stage 1).
function starComeIn(i, speed, stay) {
  starFoeY[i] += f32(f32(speed * STAR_STEP_MS) / 1000.0);
  if (starFoeY[i] >= f32((STAR_FT + stay))) {
    starFoeY[i] = f32((STAR_FT + stay));
    starFoeStage[i] = 1; starFoeMs[i] = 0; starFoeAct[i] = 0;
    starFoeVX[i] = (u32(starRnd() & 1)) ? 1.0 : -1.0;                 // (its sideways speed's sign; each sets its own)
  }
}
function starMiniStep(i) {
  let k = starFoeKind[i], w = STAR_FOE_W[k], h = STAR_FOE_H[k];
  let f = starFast(), cx = f32(starFoeX[i] + f32(Math.trunc(w / 2))), by = f32(starFoeY[i] + f32(h));
  let live = starDyingMs == 0;
  if (k == STAR_LANCER) {
    if (starFoeStage[i] == 0) { starComeIn(i, 60.0, 24); if (starFoeStage[i]) starFoeVX[i] *= 70.0; return; }
    starBounce(i, f);
    if ((starFoeFire[i] -= STAR_STEP_MS) <= 0) {                    // a spread of 3, every third a spread of 5
      starFoeFire[i] = starFireEvery(1300);
      let five = (++starFoeAct[i] % 3) == 0;
      let n = five ? 5 : 3;
      let step = five ? f32(15.0 / 360.0) : f32(20.0 / 360.0);
      if (live) for (let b = 0; b < n; b++) starAngled(cx, by, f32((f32(f32(b) - f32(f32((n - 1)) / 2))) * step), f32(120.0 * f));
    }
  }
  if (k == STAR_HIVE) {
    if (starFoeStage[i] == 0) { starComeIn(i, 60.0, 18); if (starFoeStage[i]) { starFoeVX[i] *= 25.0; starFoeSub[i] = 2000; } return; }
    starBounce(i, f);
    if ((starFoeFire[i] -= STAR_STEP_MS) <= 0) {
      starFoeFire[i] = starFireEvery(1700);
      if (live) starAimed(cx, by, f32(120.0 * f));
    }
    if ((starFoeSub[i] -= STAR_STEP_MS) <= 0) {                     // two darts out of its sides
      starFoeSub[i] = starFireEvery(2600);
      for (let side = 0; side < 2; side++) {
        let d = starFoeNew(STAR_DART, Math.trunc((side ? f32(f32(starFoeX[i] + f32(w)) - 8) : f32(starFoeX[i] + 8))));
        if (d < 0) continue;
        starFoeY[d] = f32(by - 10); starFoeVX[d] = side ? 30.0 : -30.0;
      }
    }
  }
  if (k == STAR_SENTINEL) {
    if (starFoeStage[i] == 0) {
      starComeIn(i, 60.0, 36);
      if (starFoeStage[i]) starFoeTX[i] = f32(starRndI(0 + 4, IN_W - 4 - w));
      return;
    }
    if (starFoeAct[i] == 0) {                                       // moves over to a place...
      let d = f32(starFoeTX[i] - starFoeX[i]), step = f32(f32(f32(90.0 * f) * STAR_STEP_MS) / 1000.0);
      if (d > step) starFoeX[i] += step; else if (d < -step) starFoeX[i] -= step;
      else { starFoeX[i] = starFoeTX[i]; starFoeAct[i] = 1; starFoeSub[i] = 600; }
    } else if (starFoeAct[i] == 1) {                                // ...glows white (you can see it coming)...
      if ((starFoeSub[i] -= STAR_STEP_MS) <= 0) { starFoeAct[i] = 2; starFoeSub[i] = 0; starFoeAng[i] = 0; }
    } else if (starFoeAct[i] == 2) {                                // ...a fast burst of 4 at you...
      if ((starFoeSub[i] -= STAR_STEP_MS) <= 0) {
        if (live) starAimed(cx, by, f32(165.0 * f));
        starFoeSub[i] = 70;
        starFoeAng[i] += 1;
        if (starFoeAng[i] >= 4) { starFoeAct[i] = 3; starFoeSub[i] = starFireEvery(700); }
      }
    } else if ((starFoeSub[i] -= STAR_STEP_MS) <= 0) {              // ...rests, and goes on
      starFoeAct[i] = 0;
      starFoeTX[i] = f32(starRndI(0 + 4, IN_W - 4 - w));
    }
  }
}
function starBossStep(i) {
  let k = starFoeKind[i], w = STAR_FOE_W[k], h = STAR_FOE_H[k];
  let f = starFast(), cx = f32(starFoeX[i] + f32(Math.trunc(w / 2))), by = f32(starFoeY[i] + f32(h));
  let live = starDyingMs == 0, angry = starFoeHP[i] * 2 <= starFoeMax[i];   // half its hits gone: quicker, more
  if (k == STAR_MOTHER) {
    if (starFoeStage[i] == 0) { starComeIn(i, 25.0, 16); if (starFoeStage[i]) starFoeVX[i] *= 42.0; return; }
    starBounce(i, f32((angry ? f32(1.4) : 1.0) * f));
    if ((starFoeFire[i] -= STAR_STEP_MS) <= 0) {
      starFoeFire[i] = starFireEvery(angry ? 950 : 1400);
      if (!live) return;
      if ((starFoeAct[i]++ & 1) == 1) {                             // a fan from the middle: 5, or 7 when angry
        let n = angry ? 7 : 5;
        let step = angry ? f32(f32(50.0 / 3.0) / 360.0) : f32(20.0 / 360.0);
        for (let b = 0; b < n; b++) starAngled(cx, by, f32((f32(f32(b) - f32(f32((n - 1)) / 2))) * step), f32(105.0 * f));
      } else {                                                      // a pair at you from its two guns
        starAimed(f32(starFoeX[i] + 21), f32(by - 4), f32(130.0 * f));
        starAimed(f32(starFoeX[i] + 83), f32(by - 4), f32(130.0 * f));
      }
    }
  }
  if (k == STAR_DESTROYER) {
    if (starFoeStage[i] == 0) {
      starComeIn(i, 25.0, 16);
      if (starFoeStage[i]) { starFoeVX[i] *= 30.0; starFoeSub[i] = 2400; starFoeFire[i] = 0; }
      return;
    }
    starBounce(i, f32((angry ? 1.5 : 1.0) * f));
    let a = starFoeAct[i];
    starFoeSub[i] -= STAR_STEP_MS;
    if (a == 0) {                                                   // a spinning stream from its middle (two when angry)
      if ((starFoeFire[i] -= STAR_STEP_MS) <= 0) {
        starFoeFire[i] = starFireEvery(angry ? 80 : 110);
        if (live) {
          starAngled(cx, f32(starFoeY[i] + 24), starFoeAng[i], f32(95.0 * f));
          if (angry) starAngled(cx, f32(starFoeY[i] + 24), f32(starFoeAng[i] + 0.5), f32(95.0 * f));
        }
        starFoeAng[i] += f32(1.0 / 12.0);
        if (starFoeAng[i] >= 1.0) starFoeAng[i] -= 1.0;
      }
      if (starFoeSub[i] <= 0) { starFoeAct[i] = 1; starFoeSub[i] = 900; }
    } else if (a == 1 || a == 3 || a == 5) {                        // the pauses
      if (starFoeSub[i] <= 0) {
        starFoeAct[i] = (a + 1) % 6;
        starFoeSub[i] = starFoeAct[i] == 0 ? 2400 : 0;
        starFoeFire[i] = 0;
      }
    } else if (a == 2) {                                            // two divers out of its bays
      for (let bay = 0; bay < 2; bay++) {
        let d = starFoeNew(STAR_DIVER, Math.trunc((f32(starFoeX[i] + f32((bay ? 92 : 28))))));
        if (d >= 0) starFoeY[d] = f32(starFoeY[i] + 26);
      }
      starFoeAct[i] = 3; starFoeSub[i] = 1500;
    } else if (a == 4) {                                            // three at you, a little spread
      if (live) for (let b = -1; b <= 1; b++) starAimedOff(cx, by, f32(125.0 * f), f32(f32(f32(b) * 12.0) / 360.0));
      starFoeAct[i] = 5; starFoeSub[i] = 1200;
    }
  }
  if (k == STAR_FORTRESS) {
    if (starFoeStage[i] == 0) { starComeIn(i, 25.0, 14); if (starFoeStage[i]) { starFoeVX[i] *= 20.0; starFoeSub[i] = 1200; } return; }
    let a = starFoeAct[i];
    let mid = f32((Math.trunc((0 + IN_W - w) / 2)));
    if (a == 4 && starLaser == 1) {                                 // the warning: it moves over you
      let to = f32(f32(starX + f32(Math.trunc(STAR_SHIP_W / 2))) - f32(Math.trunc(w / 2))), step = f32(f32(f32(45.0 * f) * STAR_STEP_MS) / 1000.0);
      to = starClamp(to, f32((0 + 4)), f32((IN_W - 4 - w)));
      if (starFoeX[i] < f32(to - step)) starFoeX[i] += step; else if (starFoeX[i] > f32(to + step)) starFoeX[i] -= step; else starFoeX[i] = to;
    } else if (a != 4) {                                            // else it sways about the middle
      starFoeX[i] += f32(f32(f32(starFoeVX[i] * f) * STAR_STEP_MS) / 1000.0);
      if (starFoeX[i] < f32(mid - 30)) starFoeVX[i] = 20.0;
      if (starFoeX[i] > f32(mid + 30)) starFoeVX[i] = -20.0;
    }
    if ((starFoeSub[i] -= STAR_STEP_MS) > 0) return;
    if (a == 0 || a == 2) {                                         // a ring with a gap (16, one gap when angry)
      let n = angry ? 16 : 12, gap = starRndI(0, n - 1);
      let off = f32(f32(f32((starRnd() % 100)) / 100.0) / f32(n));
      for (let b = 0; b < n && live; b++)
        if (b != gap && (angry || b != (gap + 1) % n)) starAngled(cx, f32(starFoeY[i] + 30), f32(f32(f32(b) / f32(n)) + off), f32(85.0 * f));
      starFoeAct[i] = a + 1; starFoeSub[i] = starFireEvery(1500);
    } else if (a == 1) {
      starFoeAct[i] = 2;
    } else if (a == 3) {                                            // the laser: first the warning line
      starLaser = 1; starLaserMs = 0;
      starFoeAct[i] = 4; starFoeSub[i] = 1700;
    } else if (a == 4) {
      starFoeAct[i] = 5;
    } else {                                                        // three at you; angry: the laser again first
      if (live) for (let b = -1; b <= 1; b++) starAimedOff(cx, by, f32(130.0 * f), f32(f32(f32(b) * 10.0) / 360.0));
      if (angry && starFoeAng[i] == 0) { starFoeAng[i] = 1; starFoeAct[i] = 3; starFoeSub[i] = 800; }
      else { starFoeAng[i] = 0; starFoeAct[i] = 0; starFoeSub[i] = starFireEvery(1200); }
    }
  }
}
// The laser's beam: under the Fortress's gun, to the bottom of the field.
function starLaserFoe() { for (let i = 0; i < STAR_FOES; i++) if (starFoeOn[i] && starFoeKind[i] == STAR_FORTRESS) return i; return -1; }
function starLaserX() { let i = starLaserFoe(); return i < 0 ? 0 : Math.trunc(starFoeX[i]) + Math.trunc(STAR_FOE_W[STAR_FORTRESS] / 2); }
function starLaserTop() { let i = starLaserFoe(); return i < 0 ? 0 : Math.trunc(starFoeY[i]) + STAR_FOE_H[STAR_FORTRESS]; }
function starLaserStep() {
  if (starLaser == 0) return;
  if (starLaserFoe() < 0) { starLaser = 0; return; }
  starLaserMs += STAR_STEP_MS;
  if (starLaser == 1 && starLaserMs >= 900) { starLaser = 2; starLaserMs = 0; starSnd |= 512; }   // 0.9 s of warning, then the beam...
  else if (starLaser == 2 && starLaserMs >= 700) starLaser = 0;                                    // ...for 0.7 s
}
function starFoeStep(i) {
  let k = starFoeKind[i];
  let s = f32(STAR_STEP_MS / 1000.0), f = starFast();
  let w = STAR_FOE_W[k], h = STAR_FOE_H[k];
  starFoeMs[i] += STAR_STEP_MS;
  if (starFoeFlash[i] > 0) starFoeFlash[i] -= STAR_STEP_MS;
  let cx = f32(starFoeX[i] + f32(Math.trunc(w / 2))), by = f32(starFoeY[i] + f32(h));
  let seen = starFoeY[i] > f32(STAR_FT) && by < f32(starY - 24);     // in the field, above you: may shoot
  if (k == STAR_DART) { starFoeY[i] += f32(f32(75.0 * f) * s); starFoeX[i] += f32(f32(starFoeVX[i] * f) * s); }
  if (k == STAR_WEAVER) {
    starFoeY[i] += f32(f32(55.0 * f) * s);
    starFoeX0[i] += f32(f32(starFoeVX[i] * f) * s);
    starFoeX[i] = f32(starFoeX0[i] + f32(32.0 * starSinT(f32(f32(starFoeMs[i]) / 1700.0))));
    if ((starFoeFire[i] -= STAR_STEP_MS) <= 0) {
      starFoeFire[i] = starFireEvery(2600);
      if (seen && starDyingMs == 0) starBullet(cx, by, 0, f32(110.0 * f));
    }
  }
  if (k == STAR_DIVER) {
    if (starFoeStage[i] == 0) {                                     // comes in...
      starFoeY[i] += f32(f32(70.0 * f) * s);
      if (starFoeMs[i] >= 650) { starFoeStage[i] = 1; starFoeMs[i] = 0; }
    } else if (starFoeStage[i] == 1) {                              // ...stops a moment, blinking (you can see it coming)...
      starFoeFlash[i] = (Math.trunc(starFoeMs[i] / 80)) % 2 ? 20 : 0;
      if (starFoeMs[i] >= 300) {                                    // ...takes aim where you are, and dives
        starFoeStage[i] = 2; starFoeFlash[i] = 0;
        let dx = f32(f32(starX + f32(Math.trunc(STAR_SHIP_W / 2))) - cx), dy = f32(f32(starY + f32(Math.trunc(STAR_SHIP_H / 2))) - (f32(starFoeY[i] + f32(Math.trunc(h / 2)))));
        if (starDyingMs > 0 || dy < 40) { dx = 0; dy = 1; }
        let d = sqrtf(f32(f32(dx * dx) + f32(dy * dy)));
        starFoeVX[i] = f32(f32(f32(150.0 * f) * dx) / d); starFoeVY[i] = f32(f32(f32(150.0 * f) * dy) / d);
      }
    } else { starFoeX[i] += f32(starFoeVX[i] * s); starFoeY[i] += f32(starFoeVY[i] * s); }
  }
  if (k == STAR_GUNNER) {
    if (starFoeStage[i] == 0) {
      starFoeY[i] += f32(f32(60.0 * f) * s);
      let stop = STAR_FT + Math.trunc((STAR_B - STAR_FT) / 5) + (i % 3) * 18;
      if (starFoeY[i] >= f32(stop)) { starFoeStage[i] = 1; starFoeMs[i] = 0; starFoeVX[i] = (u32(starRnd() & 1)) ? 28.0 : -28.0; }
    } else if (starFoeStage[i] == 1) {
      starBounce(i, f);
      if ((starFoeFire[i] -= STAR_STEP_MS) <= 0) {
        starFoeFire[i] = starFireEvery(1800);
        if (seen && starDyingMs == 0) starAimed(cx, by, f32(110.0 * f));
      }
      if (starFoeMs[i] >= 6500) starFoeStage[i] = 2;                // and leaves
    } else starFoeY[i] += f32(f32(60.0 * f) * s);
  }
  if (starIsMini(k)) starMiniStep(i);
  if (starIsBoss(k)) starBossStep(i);
  if (starFoeY[i] > f32((STAR_B + 4)) || starFoeX[i] < f32((0 - w - 20)) || starFoeX[i] > f32((IN_W + 20))) starFoeOn[i] = false;
}
function starOverlap(ax, ay, aw, ah, bx, by, bw, bh) {
  return ax < f32(bx + f32(bw)) && bx < f32(ax + f32(aw)) && ay < f32(by + f32(bh)) && by < f32(ay + f32(ah));
}
// Your ship's hit box: its middle (the wings may touch - the owner: "keep them as they are").
function starHitX() { return f32(starX + 10); }
function starHitY() { return f32(starY + 6); }
const STAR_HIT_W = 10;
const STAR_HIT_H = 14;
function starCollide() {
  // your shots on theirs
  for (let s = 0; s < STAR_SHOTS; s++) {
    if (!starShotOn[s]) continue;
    for (let i = 0; i < STAR_FOES && starShotOn[s]; i++) {
      if (!starFoeOn[i]) continue;
      let k = starFoeKind[i];
      if (f32(starFoeY[i] + f32(STAR_FOE_H[k])) < f32(STAR_FT)) continue;   // still under the score's strip
      if (starOverlap(starShotX[s], starShotY[s], STAR_SHOT_W, STAR_SHOT_H, f32(starFoeX[i] + 2), f32(starFoeY[i] + 2), STAR_FOE_W[k] - 4, STAR_FOE_H[k] - 4)) {
        starShotOn[s] = false;
        starFoeHit(i, 1);
        if (starFoeOn[i]) starSpark(f32(starShotX[s] + 1), starShotY[s], 3, 180, 50.0);   // a spark where it hit
      }
    }
  }
  if (starDyingMs > 0) return;
  // power-ups
  for (let c = 0; c < STAR_CAPS; c++) {
    if (!starCapOn[c] || !starOverlap(starX, starY, STAR_SHIP_W, STAR_SHIP_H, starCapX[c], starCapY[c], 16, 18)) continue;
    starCapOn[c] = false;
    if (starPower < STAR_POWER_MAX) starPower++; else starAddScore(500);
    starSnd |= 8;
  }
  if (starSafeMs > 0) return;
  // theirs on you
  for (let b = 0; b < STAR_BULLETS; b++) {
    if (!starBulOn[b] || !starOverlap(starHitX(), starHitY(), STAR_HIT_W, STAR_HIT_H, f32(starBulX[b] - 2), f32(starBulY[b] - 2), 4, 4)) continue;   // (the ball's middle)
    starBulOn[b] = false;
    starShipHit();
    return;
  }
  if (starLaser == 2) {                                             // the beam: 8 px wide
    let lx = starLaserX(), ly = starLaserTop();
    if (starOverlap(starHitX(), starHitY(), STAR_HIT_W, STAR_HIT_H, f32((lx - 4)), f32(ly), 8, STAR_B - ly)) {
      starShipHit();
      return;
    }
  }
  for (let i = 0; i < STAR_FOES; i++) {
    if (!starFoeOn[i]) continue;
    let k = starFoeKind[i];
    if (!starOverlap(starHitX(), starHitY(), STAR_HIT_W, STAR_HIT_H, f32(starFoeX[i] + 4), f32(starFoeY[i] + 4), STAR_FOE_W[k] - 8, STAR_FOE_H[k] - 8)) continue;
    starFoeHit(i, 3);                                               // a crash: it takes three hits too
    starShipHit();
    return;
  }
}
// The game over: the best kept (saved) if beaten.
function starOver() {
  starPhase = STAR_OVER;
  if (starScore > starBest) {
    starBest = starScore; starNewBest = true;
    gameData[GAME_STARFALL][STAR_BEST] = u32(starScore);
    gamesSave();
  }
  starSnd |= 128;
}
function starStep() {
  starStarsStep();
  for (let i = 0; i < STAR_BITS; i++) {
    if (starBitMs[i] <= 0) continue;
    starBitX[i] += f32(f32(starBitVX[i] * STAR_STEP_MS) / 1000.0); starBitY[i] += f32(f32(starBitVY[i] * STAR_STEP_MS) / 1000.0);
    starBitMs[i] -= STAR_STEP_MS;
  }
  if (starPhase != STAR_PLAY || starPaused) return;
  starMs += STAR_STEP_MS;
  if (starCallMs > 0) starCallMs -= STAR_STEP_MS;
  starShipStep();
  for (let s = 0; s < STAR_SHOTS; s++) {
    if (!starShotOn[s]) continue;
    starShotY[s] -= f32(f32(STAR_SHOT_V * STAR_STEP_MS) / 1000.0);
    starShotX[s] += f32(f32(starShotVX[s] * STAR_STEP_MS) / 1000.0);
    if (starShotY[s] < f32((STAR_FT - STAR_SHOT_H)) || starShotX[s] < f32((0 - 2)) || starShotX[s] > IN_W) starShotOn[s] = false;
  }
  // the wave: its banner, then its lines as their times come
  if (starBannerMs > 0) starBannerMs -= STAR_STEP_MS;
  else {
    starWaveMs += STAR_STEP_MS;
    let line = starLines();
    for (let l = 0; l < STAR_LINES && line[l][0] >= 0; l++)
      while (starSent[l] < line[l][3] && starWaveMs >= line[l][0] + starSent[l] * line[l][4]) {
        let x = line[l][2] < 0 ? -1 : line[l][2] + starSent[l] * line[l][5];
        let i = starFoeNew(line[l][1], x);
        if (i >= 0 && line[l][6]) starFoeVX[i] = line[l][6];
        starSent[l]++;
      }
  }
  for (let i = 0; i < STAR_FOES; i++) if (starFoeOn[i]) starFoeStep(i);
  starLaserStep();
  for (let b = 0; b < STAR_BULLETS; b++) {
    if (!starBulOn[b]) continue;
    starBulX[b] += f32(f32(starBulVX[b] * STAR_STEP_MS) / 1000.0); starBulY[b] += f32(f32(starBulVY[b] * STAR_STEP_MS) / 1000.0);
    if (starBulY[b] > f32((STAR_B + 5)) || starBulY[b] < f32((STAR_FT - 5)) || starBulX[b] < f32((0 - 5)) || starBulX[b] > f32((IN_W + 5)))
      starBulOn[b] = false;
  }
  for (let c = 0; c < STAR_CAPS; c++) {
    if (!starCapOn[c]) continue;
    starCapY[c] += f32(f32(40.0 * STAR_STEP_MS) / 1000.0);
    if (starCapY[c] > STAR_B) starCapOn[c] = false;
  }
  starCollide();
  // your ship's end, and the next
  if (starDyingMs > 0 && (starDyingMs -= STAR_STEP_MS) <= 0) {
    starDyingMs = 0;
    if (--starLives <= 0) {
      starLives = 0;
      starOver();
      return;
    }
    starShipHome();
    starSafeMs = STAR_SAFE_MS;
    if (starPower > 1) starPower--;
  }
  // the wave over: all came, none left
  if (starBannerMs <= 0) {
    let line = starLines();
    let all = true;
    for (let l = 0; l < STAR_LINES && line[l][0] >= 0; l++) if (starSent[l] < line[l][3]) all = false;
    for (let i = 0; i < STAR_FOES && all; i++) if (starFoeOn[i]) all = false;
    if (all) starWaveNew();
  }
}

// ---- the keys: 0 left, 1 right, 2 OK, 3 up, 4 the right key, 5 down, 6 the left key, 10-19 the number keys 0-9 ----
function starKeyBit(k) {
  if (k == 0 || k == 14) return 1;
  if (k == 1 || k == 16) return 2;
  if (k == 3 || k == 12) return 4;
  if (k == 5 || k == 18) return 8;
  if (k == 2 || k == 15 || k == 6) return 16;
  return 0;
}
function starKey(k, down) {
  let bit = starKeyBit(k);
  if (!down) { starHeld &= ~bit; return; }
  if (bit & 3) starLastH = (bit & 1) ? -1 : 1;
  if (bit & 12) starLastV = (bit & 4) ? -1 : 1;
  if (starPhase == STAR_TITLE) { if (k == 2 || k == 15) starNewGame(); return; }
  if (starPhase == STAR_OVER) {                                     // the left key ("Again") or OK: a new game; the right key: the first screen
    if (k == 2 || k == 15 || k == 6) starNewGame();
    else if (k == 4) starPhase = STAR_TITLE;
    return;
  }
  if (starPaused) {                                                 // OK or the left key ("Go on"): on; the right key again: quit (not counted)
    if (k == 2 || k == 15 || k == 6) { starPaused = false; starHeld = 0; }
    else if (k == 4) { starPaused = false; starPhase = STAR_TITLE; }
    return;
  }
  if (k == 4) { starPaused = true; starHeld = 0; return; }
  if (starDyingMs > 0 && (bit & 15)) return;                        // no steering a ship that is blowing up
  starHeld |= bit;
  if ((bit & 16) && starShotWait <= 0 && starDyingMs == 0) { starShoot(); starShotWait = STAR_SHOT_MS; }   // a tap: a shot at once
}

// ==================== the screen (look A: arcade colours on black) ====================
// Each 4 x 8 tile of the field keeps a fingerprint of what was drawn in it this
// frame (starMark(): every thing, its place and its look, in the order drawn);
// the field is drawn whole each frame, so a tile with the same fingerprint as
// the last frame's shows the same pixels and is not sent again.
const STAR_TILE_W = 4;  // a tile: 4 px wide (shots and stars are narrow), 8 tall
const STAR_TILE_H = 8;
const STAR_TCOLS = Math.trunc(IN_W / STAR_TILE_W);
const STAR_TROW0 = Math.trunc(STAR_T / STAR_TILE_H);  // the field's rows of tiles only (15 KB)
const STAR_TROWS = (Math.trunc((STAR_B + STAR_TILE_H - 1) / STAR_TILE_H) - STAR_TROW0);
