  let got = u32((have - nl - 1));            // what came with the first line
  if (got > total) got = total;
  if (got && f.write(ptrAdd(ptrAdd(ppBuf, nl), 1), got) != got) err = S("The card is full");
  ppActDone = got;
  timeouts = 0;
  while (!err && got < total) {
    let want = (u32(total - got)) < ppBuf.length ? i32((u32(total - got))) : i32(ppBuf.length);
    let n = httpd_req_recv(req, ppBuf, u32(want));
    if (n == HTTPD_SOCK_ERR_TIMEOUT) {
      if (ppStopping || ++timeouts > 10) err = S("The file stopped arriving");
      continue;
    }
    if (n <= 0) { err = S("The file stopped arriving"); break; }
    timeouts = 0;
    if (i32(f.write(ppBuf, u32(n))) != n) { err = S("The card is full"); break; }
    got = u32(got + u32(n));
    ppActDone = got;
    if (ppStopping) { err = S("pptransfer closed"); break; }
    vTaskDelay(1);                                     // the idle task (its watchdog) gets a turn
  }
  f.close();
  if (!err && !SD.rename(ppHandleUpload__part, ppHandleUpload__final)) err = S("Couldn't save on the card");
  if (err) {
    SD.remove(ppHandleUpload__part);
    ppActSet(PP_ACT_NONE, null, 0);
    let ev = new Uint8Array(96); snprintf(ev, ev.length, S("[pptransfer] not received: %.60s"), nm); ppEvent(ev);
    return ppSendError(req, S("500 Internal Server Error"), err);
  }
